INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_basic#2','math',4,2,'u3','L02','g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',1,'mc','auto','0.79를 바르게 읽은 것은 어느 것인가요?',ARRAY['M4-2-u3-X02','M4-2-u3-X03','M4-2-u3-X01']::text[],true,'{"seq":2,"concept":"M4-2-u3-C1","difficulty":1,"kind":"mc","stem":"0.79를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"영 점 칠구","correct":true},{"t":"영 점 칠십구","mis":"M4-2-u3-X02"},{"t":"영 점 구칠","mis":"M4-2-u3-X03"},{"t":"칠 점 구","mis":"M4-2-u3-X01"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 영.","소수점 오른쪽은 숫자를 하나씩 읽어요 — 칠구.","0.79는 「영 점 칠구」라고 읽어요."],"variant_rule":{"alt":[{"stem":"0.63을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"영 점 육삼","correct":true},{"t":"영 점 육십삼","mis":"M4-2-u3-X02"},{"t":"영 점 삼육","mis":"M4-2-u3-X03"},{"t":"육 점 삼","mis":"M4-2-u3-X01"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 영.","소수점 오른쪽은 숫자를 하나씩 읽어요 — 육삼.","0.63은 「영 점 육삼」이라고 읽어요."],"asset":null},{"stem":"9.81을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"구 점 팔일","correct":true},{"t":"구 점 팔십일","mis":"M4-2-u3-X02"},{"t":"구 점 일팔","mis":"M4-2-u3-X03"},{"t":"구십팔 점 일","mis":"M4-2-u3-X01"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 구.","소수점 오른쪽은 숫자를 하나씩 읽어요 — 팔일.","9.81은 「구 점 팔일」이라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_basic#3','math',4,2,'u3','L02','g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',1,'sa','auto','자릿값 표에 1.32를 나타냈어요. 1.32의 소수 둘째 자리 숫자는 몇인가요?','{}'::text[],true,'{"seq":3,"concept":"M4-2-u3-C1","difficulty":1,"kind":"sa","stem":"자릿값 표에 1.32를 나타냈어요. 1.32의 소수 둘째 자리 숫자는 몇인가요?","answer":["2"],"explanation":["소수점 오른쪽 첫 번째 자리가 소수 첫째 자리, 두 번째가 소수 둘째 자리예요.","1.32 — 일 자리 1, 소수 첫째 자리 3, 소수 둘째 자리 2.","소수 둘째 자리 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["일의 자리","소수 첫째","소수 둘째"],["1","3","2"]]},"variant_rule":{"alt":[{"stem":"자릿값 표에 7.95를 나타냈어요. 7.95의 소수 첫째 자리 숫자는 몇인가요?","answer":["9"],"explanation":["소수점 오른쪽 첫 번째 자리가 소수 첫째 자리, 두 번째가 소수 둘째 자리예요.","7.95 — 일 자리 7, 소수 첫째 자리 9, 소수 둘째 자리 5.","소수 첫째 자리 숫자는 9예요."],"asset":{"type":"expr_grid","rows":[["일의 자리","소수 첫째","소수 둘째"],["7","9","5"]]}},{"stem":"자릿값 표에 6.17을 나타냈어요. 6.17의 소수 둘째 자리 숫자는 몇인가요?","answer":["7"],"explanation":["소수점 오른쪽 첫 번째 자리가 소수 첫째 자리, 두 번째가 소수 둘째 자리예요.","6.17 — 일 자리 6, 소수 첫째 자리 1, 소수 둘째 자리 7.","소수 둘째 자리 숫자는 7이에요."],"asset":{"type":"expr_grid","rows":[["일의 자리","소수 첫째","소수 둘째"],["6","1","7"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_basic#4','math',4,2,'u3','L02','g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',1,'mc','auto','사육사가 기린 우리 문의 폭을 재어 보니 79 cm였어요. 안내판에는 m 단위로 적어야 해요. 79 cm는 몇 m인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":4,"concept":"M4-2-u3-C1","difficulty":1,"kind":"mc","stem":"사육사가 기린 우리 문의 폭을 재어 보니 79 cm였어요. 안내판에는 m 단위로 적어야 해요. 79 cm는 몇 m인가요?","options":[{"t":"0.79 m","correct":true},{"t":"7.9 m","mis":"M4-2-u3-X04"},{"t":"0.079 m","mis":"M4-2-u3-X04"},{"t":"79 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","79 cm는 0.01 m가 79개예요.","79 cm = 0.79 m."],"variant_rule":{"alt":[{"stem":"사육사가 바다사자 먹이통의 높이를 재어 보니 13 cm였어요. 안내판에는 m 단위로 적어야 해요. 13 cm는 몇 m인가요?","options":[{"t":"0.13 m","correct":true},{"t":"1.3 m","mis":"M4-2-u3-X04"},{"t":"0.013 m","mis":"M4-2-u3-X04"},{"t":"13 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","13 cm는 0.01 m가 13개예요.","13 cm = 0.13 m."],"asset":null},{"stem":"사육사가 홍학의 다리 길이를 재어 보니 89 cm였어요. 안내판에는 m 단위로 적어야 해요. 89 cm는 몇 m인가요?","options":[{"t":"0.89 m","correct":true},{"t":"8.9 m","mis":"M4-2-u3-X04"},{"t":"0.089 m","mis":"M4-2-u3-X04"},{"t":"89 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","89 cm는 0.01 m가 89개예요.","89 cm = 0.89 m."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
