INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_basic#7','math',4,2,'u3','L02','g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',2,'mc','auto','수직선에서 작은 눈금 한 칸은 0.01이에요. 3.3에서 오른쪽으로 작은 눈금 9칸 더 간 곳의 수는 얼마인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X17']::text[],true,'{"seq":7,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 3.3에서 오른쪽으로 작은 눈금 9칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"3.39","correct":true},{"t":"4.2","mis":"M4-2-u3-X01"},{"t":"3.21","mis":"M4-2-u3-X17"},{"t":"12.3","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 9칸은 0.09예요.","3.3 + 0.09 = 3.39.","0.1씩이 아니라 0.01씩 커져요."],"variant_rule":{"alt":[{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 8.8에서 오른쪽으로 작은 눈금 5칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"8.85","correct":true},{"t":"9.3","mis":"M4-2-u3-X01"},{"t":"8.75","mis":"M4-2-u3-X17"},{"t":"13.8","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 5칸은 0.05예요.","8.8 + 0.05 = 8.85.","0.1씩이 아니라 0.01씩 커져요."],"asset":null},{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 9.6에서 오른쪽으로 작은 눈금 6칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"9.66","correct":true},{"t":"10.2","mis":"M4-2-u3-X01"},{"t":"9.54","mis":"M4-2-u3-X17"},{"t":"15.6","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 6칸은 0.06이에요.","9.6 + 0.06 = 9.66.","0.1씩이 아니라 0.01씩 커져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_basic#8','math',4,2,'u3','L02','g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',2,'mc','auto','1이 3개, 0.1이 7개, 0.01이 1개인 수는 얼마인가요?',ARRAY['M4-2-u3-X03','M4-2-u3-X01']::text[],true,'{"seq":8,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"1이 3개, 0.1이 7개, 0.01이 1개인 수는 얼마인가요?","options":[{"t":"3.71","correct":true},{"t":"3.17","mis":"M4-2-u3-X03"},{"t":"1.73","mis":"M4-2-u3-X03"},{"t":"0.371","mis":"M4-2-u3-X01"}],"explanation":["1이 3개 → 일의 자리 3.","0.1이 7개 → 소수 첫째 자리 7, 0.01이 1개 → 소수 둘째 자리 1.","3 + 0.7 + 0.01 = 3.71."],"variant_rule":{"alt":[{"stem":"1이 2개, 0.1이 8개, 0.01이 7개인 수는 얼마인가요?","options":[{"t":"2.87","correct":true},{"t":"2.78","mis":"M4-2-u3-X03"},{"t":"7.82","mis":"M4-2-u3-X03"},{"t":"0.287","mis":"M4-2-u3-X01"}],"explanation":["1이 2개 → 일의 자리 2.","0.1이 8개 → 소수 첫째 자리 8, 0.01이 7개 → 소수 둘째 자리 7.","2 + 0.8 + 0.07 = 2.87."],"asset":null},{"stem":"1이 2개, 0.1이 3개, 0.01이 1개인 수는 얼마인가요?","options":[{"t":"2.31","correct":true},{"t":"2.13","mis":"M4-2-u3-X03"},{"t":"1.32","mis":"M4-2-u3-X03"},{"t":"0.231","mis":"M4-2-u3-X01"}],"explanation":["1이 2개 → 일의 자리 2.","0.1이 3개 → 소수 첫째 자리 3, 0.01이 1개 → 소수 둘째 자리 1.","2 + 0.3 + 0.01 = 2.31."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_basic#9','math',4,2,'u3','L02','g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',2,'ox','auto','은비가 「6.72에서 2는 0.2를 나타내.」라고 했어요. 바르게 말했어요.',ARRAY['M4-2-u3-X03']::text[],true,'{"seq":9,"concept":"M4-2-u3-C1","difficulty":2,"kind":"ox","stem":"은비가 「6.72에서 2는 0.2를 나타내.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"2는 소수 둘째 자리 숫자라서 0.02를 나타내서","correct":true},{"t":"2는 소수점 오른쪽 끝에 있어서 0.2가 맞아서","mis":"M4-2-u3-X03"}],"mis":"M4-2-u3-X03","explanation":["6.72의 2는 소수 둘째 자리 숫자예요.","소수 둘째 자리 한 칸은 0.01 — 2는 0.02.","은비의 말은 틀렸어요 ×."],"variant_rule":{"alt":[{"stem":"지유가 「3.57에서 7은 0.7을 나타내.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"7은 소수 둘째 자리 숫자라서 0.07을 나타내서","correct":true},{"t":"7은 소수점 오른쪽 끝에 있어서 0.7이 맞아서","mis":"M4-2-u3-X03"}],"explanation":["3.57의 7은 소수 둘째 자리 숫자예요.","소수 둘째 자리 한 칸은 0.01 — 7은 0.07.","지유의 말은 틀렸어요 ×."],"asset":null},{"stem":"준우가 「0.91은 0.01이 91개인 수야.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"1은 0.01이 100개, 0.1은 0.01이 10개라서","correct":true},{"t":"0.91은 0.1이 91개라서","mis":"M4-2-u3-X01"}],"explanation":["1은 0.01이 100개 — 0은 0.01이 0개.","0.91은 0.01이 91개.","모두 91개 — 바르게 말했어요 ○."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_basic#10','math',4,2,'u3','L02','g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',3,'mc','auto','0.6과 0.7 사이에 있는 수는 어느 것인가요?',ARRAY['M4-2-u3-X08','M4-2-u3-X03','M4-2-u3-X07']::text[],true,'{"seq":10,"concept":"M4-2-u3-C1","difficulty":3,"kind":"mc","stem":"0.6과 0.7 사이에 있는 수는 어느 것인가요?","options":[{"t":"0.63","correct":true},{"t":"0.73","mis":"M4-2-u3-X08"},{"t":"0.36","mis":"M4-2-u3-X03"},{"t":"0.063","mis":"M4-2-u3-X07"}],"explanation":["0.6 = 0.60, 0.7 = 0.70으로 보면 0.01의 개수로 견줄 수 있어요.","0.01이 60개와 70개 사이 — 0.63.","소수 한 자리 수로는 나타낼 수 없어 소수 둘째 자리가 필요해요."],"variant_rule":{"alt":[{"stem":"0.5와 0.6 사이에 있는 수는 어느 것인가요?","options":[{"t":"0.56","correct":true},{"t":"0.66","mis":"M4-2-u3-X08"},{"t":"0.65","mis":"M4-2-u3-X03"},{"t":"0.056","mis":"M4-2-u3-X07"}],"explanation":["0.5 = 0.50, 0.6 = 0.60으로 보면 0.01의 개수로 견줄 수 있어요.","0.01이 50개와 60개 사이 — 0.56.","소수 한 자리 수로는 나타낼 수 없어 소수 둘째 자리가 필요해요."],"asset":null},{"stem":"0.5와 0.6 사이에 있는 수는 어느 것인가요?","options":[{"t":"0.58","correct":true},{"t":"0.68","mis":"M4-2-u3-X08"},{"t":"0.85","mis":"M4-2-u3-X03"},{"t":"0.058","mis":"M4-2-u3-X07"}],"explanation":["0.5 = 0.50, 0.6 = 0.60으로 보면 0.01의 개수로 견줄 수 있어요.","0.01이 50개와 60개 사이 — 0.58.","소수 한 자리 수로는 나타낼 수 없어 소수 둘째 자리가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_challenge#1','math',4,2,'u3','L02','g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',2,'mc','auto','사육사가 펭귄의 키를 재어 보니 106 cm였어요. 안내판에는 m 단위로 적어야 해요. 106 cm는 몇 m인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":1,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"사육사가 펭귄의 키를 재어 보니 106 cm였어요. 안내판에는 m 단위로 적어야 해요. 106 cm는 몇 m인가요?","options":[{"t":"1.06 m","correct":true},{"t":"10.6 m","mis":"M4-2-u3-X04"},{"t":"0.106 m","mis":"M4-2-u3-X04"},{"t":"106 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","106 cm는 0.01 m가 106개예요.","106 cm = 1.06 m."],"variant_rule":{"alt":[{"stem":"사육사가 기린 우리 문의 폭을 재어 보니 381 cm였어요. 안내판에는 m 단위로 적어야 해요. 381 cm는 몇 m인가요?","options":[{"t":"3.81 m","correct":true},{"t":"38.1 m","mis":"M4-2-u3-X04"},{"t":"0.381 m","mis":"M4-2-u3-X04"},{"t":"381 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","381 cm는 0.01 m가 381개예요.","381 cm = 3.81 m."],"asset":null},{"stem":"사육사가 바다사자 먹이통의 높이를 재어 보니 292 cm였어요. 안내판에는 m 단위로 적어야 해요. 292 cm는 몇 m인가요?","options":[{"t":"2.92 m","correct":true},{"t":"29.2 m","mis":"M4-2-u3-X04"},{"t":"0.292 m","mis":"M4-2-u3-X04"},{"t":"292 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","292 cm는 0.01 m가 292개예요.","292 cm = 2.92 m."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_challenge#2','math',4,2,'u3','L02','g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',2,'mc','auto','3.19에서 소수 첫째 자리 숫자 1은 얼마를 나타내나요?',ARRAY['M4-2-u3-X03']::text[],true,'{"seq":2,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"3.19에서 소수 첫째 자리 숫자 1은 얼마를 나타내나요?","options":[{"t":"0.1","correct":true},{"t":"1","mis":"M4-2-u3-X03"},{"t":"0.01","mis":"M4-2-u3-X03"},{"t":"0.001","mis":"M4-2-u3-X03"}],"explanation":["소수 첫째 자리 한 칸은 0.1이에요.","숫자 1은 0.1이 1개 — 0.1을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"alt":[{"stem":"4.69에서 소수 둘째 자리 숫자 9는 얼마를 나타내나요?","options":[{"t":"0.09","correct":true},{"t":"9","mis":"M4-2-u3-X03"},{"t":"0.9","mis":"M4-2-u3-X03"},{"t":"0.009","mis":"M4-2-u3-X03"}],"explanation":["소수 둘째 자리 한 칸은 0.01이에요.","숫자 9는 0.01이 9개 — 0.09를 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"asset":null},{"stem":"6.28에서 소수 둘째 자리 숫자 8은 얼마를 나타내나요?","options":[{"t":"0.08","correct":true},{"t":"8","mis":"M4-2-u3-X03"},{"t":"0.8","mis":"M4-2-u3-X03"},{"t":"0.008","mis":"M4-2-u3-X03"}],"explanation":["소수 둘째 자리 한 칸은 0.01이에요.","숫자 8은 0.01이 8개 — 0.08을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_challenge#3','math',4,2,'u3','L02','g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',3,'sa','auto','1인 것 1개, 0.1인 것 3개, 0.01인 것 2개를 색칠했어요. 이 수는 0.01이 모두 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u3-C1","difficulty":3,"kind":"sa","stem":"1인 것 1개, 0.1인 것 3개, 0.01인 것 2개를 색칠했어요. 이 수는 0.01이 모두 몇 개인 수인가요? 숫자로 쓰세요.","answer":["132"],"explanation":["1은 0.01이 100개, 0.1은 0.01이 10개예요.","1 × 100 + 3 × 10 + 2 = 132.","이 수는 1.32 — 0.01이 132개예요."],"variant_rule":{"alt":[{"stem":"1인 것 3개, 0.1인 것 9개, 0.01인 것 7개를 색칠했어요. 이 수는 0.01이 모두 몇 개인 수인가요? 숫자로 쓰세요.","answer":["397"],"explanation":["1은 0.01이 100개, 0.1은 0.01이 10개예요.","3 × 100 + 9 × 10 + 7 = 397.","이 수는 3.97 — 0.01이 397개예요."],"asset":null},{"stem":"1인 것 4개, 0.1인 것 2개, 0.01인 것 1개를 색칠했어요. 이 수는 0.01이 모두 몇 개인 수인가요? 숫자로 쓰세요.","answer":["421"],"explanation":["1은 0.01이 100개, 0.1은 0.01이 10개예요.","4 × 100 + 2 × 10 + 1 = 421.","이 수는 4.21 — 0.01이 421개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_challenge#4','math',4,2,'u3','L02','g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',3,'mc','auto','수직선에서 작은 눈금 한 칸은 0.01이에요. 8.1에서 오른쪽으로 작은 눈금 8칸 더 간 곳의 수는 얼마인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X17']::text[],true,'{"seq":4,"concept":"M4-2-u3-C1","difficulty":3,"kind":"mc","stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 8.1에서 오른쪽으로 작은 눈금 8칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"8.18","correct":true},{"t":"8.9","mis":"M4-2-u3-X01"},{"t":"8.02","mis":"M4-2-u3-X17"},{"t":"16.1","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 8칸은 0.08이에요.","8.1 + 0.08 = 8.18.","0.1씩이 아니라 0.01씩 커져요."],"variant_rule":{"alt":[{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 2.6에서 오른쪽으로 작은 눈금 4칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"2.64","correct":true},{"t":"3","mis":"M4-2-u3-X01"},{"t":"2.56","mis":"M4-2-u3-X17"},{"t":"6.6","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 4칸은 0.04예요.","2.6 + 0.04 = 2.64.","0.1씩이 아니라 0.01씩 커져요."],"asset":null},{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 6.8에서 오른쪽으로 작은 눈금 6칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"6.86","correct":true},{"t":"7.4","mis":"M4-2-u3-X01"},{"t":"6.74","mis":"M4-2-u3-X17"},{"t":"12.8","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 6칸은 0.06이에요.","6.8 + 0.06 = 6.86.","0.1씩이 아니라 0.01씩 커져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_challenge#5','math',4,2,'u3','L02','g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',3,'error','auto','소수 5.79를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u3-X03','M4-2-u3-X17']::text[],true,'{"seq":5,"concept":"M4-2-u3-C1","difficulty":3,"kind":"error","stem":"소수 5.79를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 「5.79의 소수 첫째 자리 숫자는 9」","correct":true,"mis_target":"M4-2-u3-X03"},{"t":"건우 — 「5.79는 0.01이 579개인 수」","mis":"M4-2-u3-X17"},{"t":"은비 — 「5.79는 「오 점 칠구」라고 읽어요」","mis":"M4-2-u3-X17"},{"t":"민서 — 「5.79 = 5 + 0.7 + 0.09」","mis":"M4-2-u3-X17"}],"explanation":["5.79는 0.01이 579개 — 「오 점 칠구」.","소수 첫째 자리 7, 소수 둘째 자리 9.","준우의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"소수 3.94를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지훈 — 「3.94의 소수 첫째 자리 숫자는 4」","correct":true,"mis_target":"M4-2-u3-X03"},{"t":"서윤 — 「3.94는 0.01이 394개인 수」","mis":"M4-2-u3-X17"},{"t":"민서 — 「3.94는 「삼 점 구사」라고 읽어요」","mis":"M4-2-u3-X17"},{"t":"건우 — 「3.94 = 3 + 0.9 + 0.04」","mis":"M4-2-u3-X17"}],"explanation":["3.94는 0.01이 394개 — 「삼 점 구사」.","소수 첫째 자리 9, 소수 둘째 자리 4.","지훈의 말이 틀렸어요."],"asset":null},{"stem":"소수 8.41을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「8.41의 소수 첫째 자리 숫자는 1」","correct":true,"mis_target":"M4-2-u3-X03"},{"t":"도연 — 「8.41은 0.01이 841개인 수」","mis":"M4-2-u3-X17"},{"t":"지유 — 「8.41은 「팔 점 사일」이라고 읽어요」","mis":"M4-2-u3-X17"},{"t":"서준 — 「8.41 = 8 + 0.4 + 0.01」","mis":"M4-2-u3-X17"}],"explanation":["8.41은 0.01이 841개 — 「팔 점 사일」.","소수 첫째 자리 4, 소수 둘째 자리 1.","민서의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
