INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_challenge#7','math',4,2,'u3','L02','g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',3,'mc','auto','1이 1개, 0.1이 9개, 0.01이 2개인 수는 얼마인가요?',ARRAY['M4-2-u3-X03','M4-2-u3-X01']::text[],true,'{"seq":7,"concept":"M4-2-u3-C1","difficulty":3,"kind":"mc","stem":"1이 1개, 0.1이 9개, 0.01이 2개인 수는 얼마인가요?","options":[{"t":"1.92","correct":true},{"t":"1.29","mis":"M4-2-u3-X03"},{"t":"2.91","mis":"M4-2-u3-X03"},{"t":"0.192","mis":"M4-2-u3-X01"}],"explanation":["1이 1개 → 일의 자리 1.","0.1이 9개 → 소수 첫째 자리 9, 0.01이 2개 → 소수 둘째 자리 2.","1 + 0.9 + 0.02 = 1.92."],"variant_rule":{"alt":[{"stem":"1이 4개, 0.1이 9개, 0.01이 2개인 수는 얼마인가요?","options":[{"t":"4.92","correct":true},{"t":"4.29","mis":"M4-2-u3-X03"},{"t":"2.94","mis":"M4-2-u3-X03"},{"t":"0.492","mis":"M4-2-u3-X01"}],"explanation":["1이 4개 → 일의 자리 4.","0.1이 9개 → 소수 첫째 자리 9, 0.01이 2개 → 소수 둘째 자리 2.","4 + 0.9 + 0.02 = 4.92."],"asset":null},{"stem":"1이 3개, 0.1이 5개, 0.01이 1개인 수는 얼마인가요?","options":[{"t":"3.51","correct":true},{"t":"3.15","mis":"M4-2-u3-X03"},{"t":"1.53","mis":"M4-2-u3-X03"},{"t":"0.351","mis":"M4-2-u3-X01"}],"explanation":["1이 3개 → 일의 자리 3.","0.1이 5개 → 소수 첫째 자리 5, 0.01이 1개 → 소수 둘째 자리 1.","3 + 0.5 + 0.01 = 3.51."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_challenge#8','math',4,2,'u3','L02','g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',4,'essay','teacher','사육사가 「다람쥐의 몸무게가 지난달에는 0.63 kg이었어요.」라고 했어요. 0.63이 어떤 수인지 0.1과 0.01을 써서 설명하고, 0.6과 0.7 중 어느 수에 더 가까운지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C1","difficulty":4,"kind":"essay","stem":"사육사가 「다람쥐의 몸무게가 지난달에는 0.63 kg이었어요.」라고 했어요. 0.63이 어떤 수인지 0.1과 0.01을 써서 설명하고, 0.6과 0.7 중 어느 수에 더 가까운지 써 보세요.","answer_guide":{"answer":"예: 0.63은 0.1이 6개, 0.01이 3개인 수이고 0.01이 63개인 수이다. 0.6은 0.01이 60개, 0.7은 0.01이 70개이므로 0.63은 0.6보다 0.01이 3개 많고 0.7보다 7개 적어 0.6에 더 가깝다. 소수 한 자리 수로는 나타낼 수 없어 소수 둘째 자리가 필요하다.","scoring_points":["0.1이 6개·0.01이 3개(0.01이 63개)라고 썼는가","0.6 = 0.60, 0.7 = 0.70처럼 0.01의 개수로 견주었는가","0.6에 더 가깝다고 답했는가"]},"explanation":["0.63 = 0.6 + 0.03.","0.01이 63개.","0.6에 더 가까워요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[0,2],[1,2],[1,3],[0,3]],"hi":true},{"p":[[0,3],[1,3],[1,4],[0,4]],"hi":true},{"p":[[0,4],[1,4],[1,5],[0,5]],"hi":true},{"p":[[0,5],[1,5],[1,6],[0,6]],"hi":true},{"p":[[0,6],[1,6],[1,7],[0,7]],"hi":true},{"p":[[0,7],[1,7],[1,8],[0,8]],"hi":true},{"p":[[0,8],[1,8],[1,9],[0,9]],"hi":true},{"p":[[0,9],[1,9],[1,10],[0,10]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[1,2],[2,2],[2,3],[1,3]],"hi":true},{"p":[[1,3],[2,3],[2,4],[1,4]],"hi":true},{"p":[[1,4],[2,4],[2,5],[1,5]],"hi":true},{"p":[[1,5],[2,5],[2,6],[1,6]],"hi":true},{"p":[[1,6],[2,6],[2,7],[1,7]],"hi":true},{"p":[[1,7],[2,7],[2,8],[1,8]],"hi":true},{"p":[[1,8],[2,8],[2,9],[1,9]],"hi":true},{"p":[[1,9],[2,9],[2,10],[1,10]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[2,1],[3,1],[3,2],[2,2]],"hi":true},{"p":[[2,2],[3,2],[3,3],[2,