INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_challenge#9','math',4,2,'u3','L02','g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',4,'essay','teacher','2.58에서 숫자 2, 5, 8은 각각 얼마를 나타내는지 쓰고, 「같은 숫자라도 자리에 따라 값이 달라진다」는 말을 2.58과 5.28을 견주어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C1","difficulty":4,"kind":"essay","stem":"2.58에서 숫자 2, 5, 8은 각각 얼마를 나타내는지 쓰고, 「같은 숫자라도 자리에 따라 값이 달라진다」는 말을 2.58과 5.28을 견주어 설명해 보세요.","answer_guide":{"answer":"예: 2.58에서 2는 2, 5는 0.5, 8은 0.08을 나타낸다. 5.28에서는 5가 일의 자리에 있어 5를 나타내고 2는 0.2를 나타낸다. 같은 숫자 5라도 2.58에서는 0.5, 5.28에서는 5로 자리에 따라 값이 10배 차이 난다.","scoring_points":["2.58의 2·5·8이 나타내는 값을 바르게 썼는가","5.28에서 5와 2가 나타내는 값을 썼는가","자리에 따라 값이 달라진다는 것을 견주어 설명했는가"]},"explanation":["2, 0.5, 0.08.","5.28 → 5, 0.2, 0.08.","자리가 값을 정해요."],"asset":{"type":"expr_grid","rows":[["일의 자리","소수 첫째","소수 둘째"],["2","5","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L02_challenge#10','math',4,2,'u3','L02','g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',4,'sa','auto','1인 것 1개, 0.1인 것 4개, 0.01인 것 6개를 색칠했어요. 이 수는 0.01이 모두 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u3-C1","difficulty":4,"kind":"sa","stem":"1인 것 1개, 0.1인 것 4개, 0.01인 것 6개를 색칠했어요. 이 수는 0.01이 모두 몇 개인 수인가요? 숫자로 쓰세요.","answer":["146"],"explanation":["1은 0.01이 100개, 0.1은 0.01이 10개예요.","1 × 100 + 4 × 10 + 6 = 146.","이 수는 1.46 — 0.01이 146개예요."],"variant_rule":{"alt":[{"stem":"1인 것 3개, 0.1인 것 2개, 0.01인 것 4개를 색칠했어요. 이 수는 0.01이 모두 몇 개인 수인가요? 숫자로 쓰세요.","answer":["324"],"explanation":["1은 0.01이 100개, 0.1은 0.01이 10개예요.","3 × 100 + 2 × 10 + 4 = 324.","이 수는 3.24 — 0.01이 324개예요."],"asset":null},{"stem":"1인 것 3개, 0.1인 것 2개, 0.01인 것 5개를 색칠했어요. 이 수는 0.01이 모두 몇 개인 수인가요? 숫자로 쓰세요.","answer":["325"],"explanation":["1은 0.01이 100개, 0.1은 0.01이 10개예요.","3 × 100 + 2 × 10 + 5 = 325.","이 수는 3.25 — 0.01이 325개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_basic#1','math',4,2,'u3','L03','g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',1,'sa','auto','0.814는 0.001이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u3-C2","difficulty":1,"kind":"sa","stem":"0.814는 0.001이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["814"],"explanation":["1을 똑같이 1000으로 나눈 하나가 0.001이에요.","1은 0.001이 1000개, 0.1은 100개, 0.01은 10개예요.","0.814는 0.001이 814개인 수예요."],"variant_rule":{"alt":[{"stem":"0.238은 0.001이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["238"],"explanation":["1을 똑같이 1000으로 나눈 하나가 0.001이에요.","1은 0.001이 1000개, 0.1은 100개, 0.01은 10개예요.","0.238은 0.001이 238개인 수예요."],"asset":null},{"stem":"0.251은 0.001이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["251"],"explanation":["1을 똑같이 1000으로 나눈 하나가 0.001이에요.","1은 0.001이 1000개, 0.1은 100개, 0.01은 10개예요.","0.251은 0.001이 251개인 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_basic#2','math',4,2,'u3','L03','g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',1,'mc','auto','0.814를 바르게 읽은 것은 어느 것인가요?',ARRAY['M4-2-u3-X02','M4-2-u3-X03','M4-2-u3-X01']::text[],true,'{"seq":2,"concept":"M4-2-u3-C2","difficulty":1,"kind":"mc","stem":"0.814를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"영 점 팔일사","correct":true},{"t":"영 점 팔백십사","mis":"M4-2-u3-X02"},{"t":"영 점 사일팔","mis":"M4-2-u3-X03"},{"t":"팔 점 일사","mis":"M4-2-u3-X01"}],"explanation":["소수점 왼쪽은 자연수처럼 — 영.","소수점 오른쪽은 하나씩 — 팔일사.","0.814는 「영 점 팔일사」라고 읽어요."],"variant_rule":{"alt":[{"stem":"0.732를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"영 점 칠삼이","correct":true},{"t":"영 점 칠백삼십이","mis":"M4-2-u3-X02"},{"t":"영 점 이삼칠","mis":"M4-2-u3-X03"},{"t":"칠 점 삼이","mis":"M4-2-u3-X01"}],"explanation":["소수점 왼쪽은 자연수처럼 — 영.","소수점 오른쪽은 하나씩 — 칠삼이.","0.732는 「영 점 칠삼이」라고 읽어요."],"asset":null},{"stem":"0.573을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"영 점 오칠삼","correct":true},{"t":"영 점 오백칠십삼","mis":"M4-2-u3-X02"},{"t":"영 점 삼칠오","mis":"M4-2-u3-X03"},{"t":"오 점 칠삼","mis":"M4-2-u3-X01"}],"explanation":["소수점 왼쪽은 자연수처럼 — 영.","소수점 오른쪽은 하나씩 — 오칠삼.","0.573은 「영 점 오칠삼」이라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_basic#3','math',4,2,'u3','L03','g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',1,'sa','auto','자릿값 표에 1.643을 나타냈어요. 1.643의 소수 셋째 자리 숫자는 몇인가요?','{}'::text[],true,'{"seq":3,"concept":"M4-2-u3-C2","difficulty":1,"kind":"sa","stem":"자릿값 표에 1.643을 나타냈어요. 1.643의 소수 셋째 자리 숫자는 몇인가요?","answer":["3"],"explanation":["소수점 오른쪽 첫 번째 자리가 소수 첫째 자리, 두 번째가 소수 둘째 자리, 세 번째가 소수 셋째 자리예요.","1.643 — 일 자리 1, 소수 첫째 자리 6, 소수 둘째 자리 4, 소수 셋째 자리 3.","소수 셋째 자리 숫자는 3이에요."],"asset":{"type":"expr_grid","rows":[["일의 자리","소수 첫째","소수 둘째","소수 셋째"],["1","6","4","3"]]},"variant_rule":{"alt":[{"stem":"자릿값 표에 7.548을 나타냈어요. 7.548의 소수 셋째 자리 숫자는 몇인가요?","answer":["8"],"explanation":["소수점 오른쪽 첫 번째 자리가 소수 첫째 자리, 두 번째가 소수 둘째 자리, 세 번째가 소수 셋째 자리예요.","7.548 — 일 자리 7, 소수 첫째 자리 5, 소수 둘째 자리 4, 소수 셋째 자리 8.","소수 셋째 자리 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["일의 자리","소수 첫째","소수 둘째","소수 셋째"],["7","5","4","8"]]}},{"stem":"자릿값 표에 8.521을 나타냈어요. 8.521의 소수 둘째 자리 숫자는 몇인가요?","answer":["2"],"explanation":["소수점 오른쪽 첫 번째 자리가 소수 첫째 자리, 두 번째가 소수 둘째 자리, 세 번째가 소수 셋째 자리예요.","8.521 — 일 자리 8, 소수 첫째 자리 5, 소수 둘째 자리 2, 소수 셋째 자리 1.","소수 둘째 자리 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["일의 자리","소수 첫째","소수 둘째","소수 셋째"],["8","5","2","1"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_basic#4','math',4,2,'u3','L03','g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',1,'mc','auto','훈련사가 안내견과 함께 814 m를 걸었어요. 안내장에는 km 단위로 적어야 해요. 814 m는 몇 km인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":4,"concept":"M4-2-u3-C2","difficulty":1,"kind":"mc","stem":"훈련사가 안내견과 함께 814 m를 걸었어요. 안내장에는 km 단위로 적어야 해요. 814 m는 몇 km인가요?","options":[{"t":"0.814 km","correct":true},{"t":"8.14 km","mis":"M4-2-u3-X04"},{"t":"81.4 km","mis":"M4-2-u3-X04"},{"t":"814 km","mis":"M4-2-u3-X04"}],"explanation":["1 m는 1 km를 1000으로 나눈 하나 — 0.001 km예요.","814 m는 0.001 km가 814개예요.","814 m = 0.814 km."],"variant_rule":{"alt":[{"stem":"훈련사가 안내견과 함께 328 m를 걸었어요. 안내장에는 km 단위로 적어야 해요. 328 m는 몇 km인가요?","options":[{"t":"0.328 km","correct":true},{"t":"3.28 km","mis":"M4-2-u3-X04"},{"t":"32.8 km","mis":"M4-2-u3-X04"},{"t":"328 km","mis":"M4-2-u3-X04"}],"explanation":["1 m는 1 km를 1000으로 나눈 하나 — 0.001 km예요.","328 m는 0.001 km가 328개예요.","328 m = 0.328 km."],"asset":null},{"stem":"훈련사가 안내견과 함께 595 m를 걸었어요. 안내장에는 km 단위로 적어야 해요. 595 m는 몇 km인가요?","options":[{"t":"0.595 km","correct":true},{"t":"5.95 km","mis":"M4-2-u3-X04"},{"t":"59.5 km","mis":"M4-2-u3-X04"},{"t":"595 km","mis":"M4-2-u3-X04"}],"explanation":["1 m는 1 km를 1000으로 나눈 하나 — 0.001 km예요.","595 m는 0.001 km가 595개예요.","595 m = 0.595 km."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_basic#5','math',4,2,'u3','L03','g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',2,'mc','auto','4.275에서 소수 둘째 자리 숫자 7은 얼마를 나타내나요?',ARRAY['M4-2-u3-X03']::text[],true,'{"seq":5,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"4.275에서 소수 둘째 자리 숫자 7은 얼마를 나타내나요?","options":[{"t":"0.07","correct":true},{"t":"7","mis":"M4-2-u3-X03"},{"t":"0.7","mis":"M4-2-u3-X03"},{"t":"0.007","mis":"M4-2-u3-X03"}],"explanation":["소수 둘째 자리 한 칸은 0.01이에요.","숫자 7은 0.01이 7개 — 0.07을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"alt":[{"stem":"3.149에서 소수 셋째 자리 숫자 9는 얼마를 나타내나요?","options":[{"t":"0.009","correct":true},{"t":"9","mis":"M4-2-u3-X03"},{"t":"0.9","mis":"M4-2-u3-X03"},{"t":"0.09","mis":"M4-2-u3-X03"}],"explanation":["소수 셋째 자리 한 칸은 0.001이에요.","숫자 9는 0.001이 9개 — 0.009를 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"asset":null},{"stem":"4.875에서 소수 첫째 자리 숫자 8은 얼마를 나타내나요?","options":[{"t":"0.8","correct":true},{"t":"8","mis":"M4-2-u3-X03"},{"t":"0.08","mis":"M4-2-u3-X03"},{"t":"0.008","mis":"M4-2-u3-X03"}],"explanation":["소수 첫째 자리 한 칸은 0.1이에요.","숫자 8은 0.1이 8개 — 0.8을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_basic#6','math',4,2,'u3','L03','g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',2,'sa','auto','1인 모눈종이 2장과 0.001인 칸 275개를 색칠했어요. 이 수는 0.001이 모두 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u3-C2","difficulty":2,"kind":"sa","stem":"1인 모눈종이 2장과 0.001인 칸 275개를 색칠했어요. 이 수는 0.001이 모두 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2275"],"explanation":["1은 0.001이 1000개예요.","1이 2장이면 0.001이 2 × 1000 = 2000개.","2000 + 275 = 2275개 — 2.275예요."],"variant_rule":{"alt":[{"stem":"1인 모눈종이 2장과 0.001인 칸 276개를 색칠했어요. 이 수는 0.001이 모두 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2276"],"explanation":["1은 0.001이 1000개예요.","1이 2장이면 0.001이 2 × 1000 = 2000개.","2000 + 276 = 2276개 — 2.276이에요."],"asset":null},{"stem":"1인 모눈종이 2장과 0.001인 칸 439개를 색칠했어요. 이 수는 0.001이 모두 몇 개인 수인가요? 숫자로 쓰세요.","answer":["2439"],"explanation":["1은 0.001이 1000개예요.","1이 2장이면 0.001이 2 × 1000 = 2000개.","2000 + 439 = 2439개 — 2.439예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_basic#7','math',4,2,'u3','L03','g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',2,'mc','auto','수직선에서 작은 눈금 한 칸은 0.001이에요. 2.51에서 오른쪽으로 작은 눈금 9칸 더 간 곳의 수는 얼마인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X17']::text[],true,'{"seq":7,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"수직선에서 작은 눈금 한 칸은 0.001이에요. 2.51에서 오른쪽으로 작은 눈금 9칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"2.519","correct":true},{"t":"2.6","mis":"M4-2-u3-X01"},{"t":"2.501","mis":"M4-2-u3-X17"},{"t":"3.41","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.001 — 9칸은 0.009예요.","2.51 + 0.009 = 2.519.","0.01씩이 아니라 0.001씩 커져요."],"variant_rule":{"alt":[{"stem":"수직선에서 작은 눈금 한 칸은 0.001이에요. 1.35에서 오른쪽으로 작은 눈금 7칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"1.357","correct":true},{"t":"1.42","mis":"M4-2-u3-X01"},{"t":"1.343","mis":"M4-2-u3-X17"},{"t":"2.05","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.001 — 7칸은 0.007이에요.","1.35 + 0.007 = 1.357.","0.01씩이 아니라 0.001씩 커져요."],"asset":null},{"stem":"수직선에서 작은 눈금 한 칸은 0.001이에요. 1.98에서 오른쪽으로 작은 눈금 8칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"1.988","correct":true},{"t":"2.06","mis":"M4-2-u3-X01"},{"t":"1.972","mis":"M4-2-u3-X17"},{"t":"2.78","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.001 — 8칸은 0.008이에요.","1.98 + 0.008 = 1.988.","0.01씩이 아니라 0.001씩 커져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_basic#8','math',4,2,'u3','L03','g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',2,'mc','auto','반려동물 영양사가 간식에 섞을 영양제 39 g을 덜었어요. 이 양을 kg 단위로 쓰면 몇 kg인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":8,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"반려동물 영양사가 간식에 섞을 영양제 39 g을 덜었어요. 이 양을 kg 단위로 쓰면 몇 kg인가요?","options":[{"t":"0.039 kg","correct":true},{"t":"0.39 kg","mis":"M4-2-u3-X04"},{"t":"3.9 kg","mis":"M4-2-u3-X04"},{"t":"39 kg","mis":"M4-2-u3-X04"}],"explanation":["1 g은 1 kg을 1000으로 나눈 하나 — 0.001 kg이에요.","39 g은 0.001 kg이 39개예요.","39 g = 0.039 kg."],"variant_rule":{"alt":[{"stem":"반려동물 영양사가 간식에 섞을 영양제 686 g을 덜었어요. 이 양을 kg 단위로 쓰면 몇 kg인가요?","options":[{"t":"0.686 kg","correct":true},{"t":"6.86 kg","mis":"M4-2-u3-X04"},{"t":"68.6 kg","mis":"M4-2-u3-X04"},{"t":"686 kg","mis":"M4-2-u3-X04"}],"explanation":["1 g은 1 kg을 1000으로 나눈 하나 — 0.001 kg이에요.","686 g은 0.001 kg이 686개예요.","686 g = 0.686 kg."],"asset":null},{"stem":"반려동물 영양사가 간식에 섞을 영양제 291 g을 덜었어요. 이 양을 kg 단위로 쓰면 몇 kg인가요?","options":[{"t":"0.291 kg","correct":true},{"t":"2.91 kg","mis":"M4-2-u3-X04"},{"t":"29.1 kg","mis":"M4-2-u3-X04"},{"t":"291 kg","mis":"M4-2-u3-X04"}],"explanation":["1 g은 1 kg을 1000으로 나눈 하나 — 0.001 kg이에요.","291 g은 0.001 kg이 291개예요.","291 g = 0.291 kg."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_basic#9','math',4,2,'u3','L03','g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',2,'mc','auto','4 + 0.2 + 0.07 + 0.005를 소수로 나타내면 얼마인가요?',ARRAY['M4-2-u3-X03']::text[],true,'{"seq":9,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"4 + 0.2 + 0.07 + 0.005를 소수로 나타내면 얼마인가요?","options":[{"t":"4.275","correct":true},{"t":"4.257","mis":"M4-2-u3-X03"},{"t":"4.725","mis":"M4-2-u3-X03"},{"t":"4.572","mis":"M4-2-u3-X03"}],"explanation":["0.2 → 소수 첫째 자리 2, 0.07 → 소수 둘째 자리 7.","0.005 → 소수 셋째 자리 5.","모두 모으면 4.275."],"variant_rule":{"alt":[{"stem":"5 + 0.6 + 0.09 + 0.007을 소수로 나타내면 얼마인가요?","options":[{"t":"5.697","correct":true},{"t":"5.679","mis":"M4-2-u3-X03"},{"t":"5.967","mis":"M4-2-u3-X03"},{"t":"5.796","mis":"M4-2-u3-X03"}],"explanation":["0.6 → 소수 첫째 자리 6, 0.09 → 소수 둘째 자리 9.","0.007 → 소수 셋째 자리 7.","모두 모으면 5.697."],"asset":null},{"stem":"6 + 0.1 + 0.05 + 0.004를 소수로 나타내면 얼마인가요?","options":[{"t":"6.154","correct":true},{"t":"6.145","mis":"M4-2-u3-X03"},{"t":"6.514","mis":"M4-2-u3-X03"},{"t":"6.451","mis":"M4-2-u3-X03"}],"explanation":["0.1 → 소수 첫째 자리 1, 0.05 → 소수 둘째 자리 5.","0.004 → 소수 셋째 자리 4.","모두 모으면 6.154."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_basic#10','math',4,2,'u3','L03','g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',3,'error','auto','소수 3.194를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u3-X03','M4-2-u3-X17']::text[],true,'{"seq":10,"concept":"M4-2-u3-C2","difficulty":3,"kind":"error","stem":"소수 3.194를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「3.194의 소수 셋째 자리 숫자는 9」","correct":true,"mis_target":"M4-2-u3-X03"},{"t":"서윤 — 「3.194는 0.001이 3194개인 수」","mis":"M4-2-u3-X17"},{"t":"건우 — 「3.194에서 9는 0.09를 나타내요」","mis":"M4-2-u3-X17"},{"t":"도연 — 「3194 m는 3.194 km」","mis":"M4-2-u3-X17"}],"explanation":["3.194는 0.001이 3194개예요.","소수 첫째·둘째·셋째 자리 숫자는 1, 9, 4.","하윤의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"소수 2.215를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「2.215는 0.01이 2215개인 수」","correct":true,"mis_target":"M4-2-u3-X01"},{"t":"지훈 — 「2.215의 소수 셋째 자리 숫자는 5」","mis":"M4-2-u3-X17"},{"t":"준우 — 「2.215에서 1은 0.01을 나타내요」","mis":"M4-2-u3-X17"},{"t":"채원 — 「2215 m는 2.215 km」","mis":"M4-2-u3-X17"}],"explanation":["2.215는 0.001이 2215개예요.","소수 첫째·둘째·셋째 자리 숫자는 2, 1, 5.","은비의 말이 틀렸어요."],"asset":null},{"stem":"소수 5.861을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 「5.861에서 6은 0.6을 나타내요」","correct":true,"mis_target":"M4-2-u3-X03"},{"t":"서윤 — 「5.861은 0.001이 5861개인 수」","mis":"M4-2-u3-X17"},{"t":"서준 — 「5.861의 소수 셋째 자리 숫자는 1」","mis":"M4-2-u3-X17"},{"t":"은비 — 「5861 m는 5.861 km」","mis":"M4-2-u3-X17"}],"explanation":["5.861은 0.001이 5861개예요.","소수 첫째·둘째·셋째 자리 숫자는 8, 6, 1.","준우의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_challenge#1','math',4,2,'u3','L03','g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',2,'mc','auto','훈련사가 안내견과 함께 2576 m를 걸었어요. 안내장에는 km 단위로 적어야 해요. 2576 m는 몇 km인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":1,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"훈련사가 안내견과 함께 2576 m를 걸었어요. 안내장에는 km 단위로 적어야 해요. 2576 m는 몇 km인가요?","options":[{"t":"2.576 km","correct":true},{"t":"25.76 km","mis":"M4-2-u3-X04"},{"t":"257.6 km","mis":"M4-2-u3-X04"},{"t":"2576 km","mis":"M4-2-u3-X04"}],"explanation":["1 m는 1 km를 1000으로 나눈 하나 — 0.001 km예요.","2576 m는 0.001 km가 2576개예요.","2576 m = 2.576 km."],"variant_rule":{"alt":[{"stem":"훈련사가 안내견과 함께 2019 m를 걸었어요. 안내장에는 km 단위로 적어야 해요. 2019 m는 몇 km인가요?","options":[{"t":"2.019 km","correct":true},{"t":"20.19 km","mis":"M4-2-u3-X04"},{"t":"201.9 km","mis":"M4-2-u3-X04"},{"t":"2019 km","mis":"M4-2-u3-X04"}],"explanation":["1 m는 1 km를 1000으로 나눈 하나 — 0.001 km예요.","2019 m는 0.001 km가 2019개예요.","2019 m = 2.019 km."],"asset":null},{"stem":"훈련사가 안내견과 함께 2644 m를 걸었어요. 안내장에는 km 단위로 적어야 해요. 2644 m는 몇 km인가요?","options":[{"t":"2.644 km","correct":true},{"t":"26.44 km","mis":"M4-2-u3-X04"},{"t":"264.4 km","mis":"M4-2-u3-X04"},{"t":"2644 km","mis":"M4-2-u3-X04"}],"explanation":["1 m는 1 km를 1000으로 나눈 하나 — 0.001 km예요.","2644 m는 0.001 km가 2644개예요.","2644 m = 2.644 km."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_challenge#2','math',4,2,'u3','L03','g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',2,'mc','auto','3.572에서 소수 첫째 자리 숫자 5는 얼마를 나타내나요?',ARRAY['M4-2-u3-X03']::text[],true,'{"seq":2,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"3.572에서 소수 첫째 자리 숫자 5는 얼마를 나타내나요?","options":[{"t":"0.5","correct":true},{"t":"5","mis":"M4-2-u3-X03"},{"t":"0.05","mis":"M4-2-u3-X03"},{"t":"0.005","mis":"M4-2-u3-X03"}],"explanation":["소수 첫째 자리 한 칸은 0.1이에요.","숫자 5는 0.1이 5개 — 0.5를 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"alt":[{"stem":"7.234에서 소수 둘째 자리 숫자 3은 얼마를 나타내나요?","options":[{"t":"0.03","correct":true},{"t":"3","mis":"M4-2-u3-X03"},{"t":"0.3","mis":"M4-2-u3-X03"},{"t":"0.003","mis":"M4-2-u3-X03"}],"explanation":["소수 둘째 자리 한 칸은 0.01이에요.","숫자 3은 0.01이 3개 — 0.03을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"asset":null},{"stem":"7.163에서 소수 셋째 자리 숫자 3은 얼마를 나타내나요?","options":[{"t":"0.003","correct":true},{"t":"3","mis":"M4-2-u3-X03"},{"t":"0.3","mis":"M4-2-u3-X03"},{"t":"0.03","mis":"M4-2-u3-X03"}],"explanation":["소수 셋째 자리 한 칸은 0.001이에요.","숫자 3은 0.001이 3개 — 0.003을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
