INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_challenge#4','math',4,2,'u3','L03','g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',3,'mc','auto','1이 4개, 0.1이 9개, 0.01이 3개, 0.001이 8개인 수는 얼마인가요?',ARRAY['M4-2-u3-X03','M4-2-u3-X01']::text[],true,'{"seq":4,"concept":"M4-2-u3-C2","difficulty":3,"kind":"mc","stem":"1이 4개, 0.1이 9개, 0.01이 3개, 0.001이 8개인 수는 얼마인가요?","options":[{"t":"4.938","correct":true},{"t":"4.839","mis":"M4-2-u3-X03"},{"t":"4.398","mis":"M4-2-u3-X03"},{"t":"0.493","mis":"M4-2-u3-X01"}],"explanation":["1 → 일의 자리 4, 0.1 → 소수 첫째 자리 9.","0.01 → 소수 둘째 자리 3, 0.001 → 소수 셋째 자리 8.","4.938이에요."],"variant_rule":{"alt":[{"stem":"1이 1개, 0.1이 4개, 0.01이 5개, 0.001이 7개인 수는 얼마인가요?","options":[{"t":"1.457","correct":true},{"t":"1.754","mis":"M4-2-u3-X03"},{"t":"1.547","mis":"M4-2-u3-X03"},{"t":"0.145","mis":"M4-2-u3-X01"}],"explanation":["1 → 일의 자리 1, 0.1 → 소수 첫째 자리 4.","0.01 → 소수 둘째 자리 5, 0.001 → 소수 셋째 자리 7.","1.457이에요."],"asset":null},{"stem":"1이 5개, 0.1이 8개, 0.01이 1개, 0.001이 7개인 수는 얼마인가요?","options":[{"t":"5.817","correct":true},{"t":"5.718","mis":"M4-2-u3-X03"},{"t":"5.187","mis":"M4-2-u3-X03"},{"t":"0.581","mis":"M4-2-u3-X01"}],"explanation":["1 → 일의 자리 5, 0.1 → 소수 첫째 자리 8.","0.01 → 소수 둘째 자리 1, 0.001 → 소수 셋째 자리 7.","5.817이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_challenge#5','math',4,2,'u3','L03','g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',3,'mc','auto','수직선에서 작은 눈금 한 칸은 0.001이에요. 6.12에서 오른쪽으로 작은 눈금 5칸 더 간 곳의 수는 얼마인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X17']::text[],true,'{"seq":5,"concept":"M4-2-u3-C2","difficulty":3,"kind":"mc","stem":"수직선에서 작은 눈금 한 칸은 0.001이에요. 6.12에서 오른쪽으로 작은 눈금 5칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"6.125","correct":true},{"t":"6.17","mis":"M4-2-u3-X01"},{"t":"6.115","mis":"M4-2-u3-X17"},{"t":"6.62","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.001 — 5칸은 0.005예요.","6.12 + 0.005 = 6.125.","0.01씩이 아니라 0.001씩 커져요."],"variant_rule":{"alt":[{"stem":"수직선에서 작은 눈금 한 칸은 0.001이에요. 8.74에서 오른쪽으로 작은 눈금 5칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"8.745","correct":true},{"t":"8.79","mis":"M4-2-u3-X01"},{"t":"8.735","mis":"M4-2-u3-X17"},{"t":"9.24","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.001 — 5칸은 0.005예요.","8.74 + 0.005 = 8.745.","0.01씩이 아니라 0.001씩 커져요."],"asset":null},{"stem":"수직선에서 작은 눈금 한 칸은 0.001이에요. 8.45에서 오른쪽으로 작은 눈금 9칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"8.459","correct":true},{"t":"8.54","mis":"M4-2-u3-X01"},{"t":"8.441","mis":"M4-2-u3-X17"},{"t":"9.35","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.001 — 9칸은 0.009예요.","8.45 + 0.009 = 8.459.","0.01씩이 아니라 0.001씩 커져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_challenge#6','math',4,2,'u3','L03','g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',3,'ox','auto','건우가 「0.697은 영 점 육백구십칠이라고 읽어.」라고 했어요. 바르게 말했어요.',ARRAY['M4-2-u3-X02']::text[],true,'{"seq":6,"concept":"M4-2-u3-C2","difficulty":3,"kind":"ox","stem":"건우가 「0.697은 영 점 육백구십칠이라고 읽어.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"소수점 오른쪽은 숫자를 하나씩 읽어야 해서","correct":true},{"t":"소수점 오른쪽이 세 자리면 백 단위로 읽어서","mis":"M4-2-u3-X02"}],"mis":"M4-2-u3-X02","explanation":["소수점 오른쪽은 하나씩 읽어요.","0.697은 「영 점 육구칠」.","건우의 말은 틀렸어요 ×."],"variant_rule":{"alt":[{"stem":"하윤이 「816 m는 8.16 km야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"1 m는 0.001 km라서 816 m는 0.816 km여서","correct":true},{"t":"1 m는 0.01 km라서","mis":"M4-2-u3-X04"}],"explanation":["1 km = 1000 m — 1 m = 0.001 km.","816 m = 0.001 km × 816 = 0.816 km.","하윤의 말은 틀렸어요 ×."],"asset":null},{"stem":"서윤이 「698 m는 6.98 km야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"1 m는 0.001 km라서 698 m는 0.698 km여서","correct":true},{"t":"1 m는 0.01 km라서","mis":"M4-2-u3-X04"}],"explanation":["1 km = 1000 m — 1 m = 0.001 km.","698 m = 0.001 km × 698 = 0.698 km.","서윤의 말은 틀렸어요 ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_challenge#7','math',4,2,'u3','L03','g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',3,'mc','auto','안내견 훈련 길이 2 km 57 m예요. 몇 km인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":7,"concept":"M4-2-u3-C2","difficulty":3,"kind":"mc","stem":"안내견 훈련 길이 2 km 57 m예요. 몇 km인가요?","options":[{"t":"2.057 km","correct":true},{"t":"2.57 km","mis":"M4-2-u3-X04"},{"t":"2.507 km","mis":"M4-2-u3-X04"},{"t":"20.57 km","mis":"M4-2-u3-X04"}],"explanation":["57 m = 0.057 km — 0.001 km가 57개예요.","2 km + 0.057 km = 2.057 km.","빈 자리에는 0을 써요 — 2.057."],"variant_rule":{"alt":[{"stem":"안내견 훈련 길이 1 km 76 m예요. 몇 km인가요?","options":[{"t":"1.076 km","correct":true},{"t":"1.76 km","mis":"M4-2-u3-X04"},{"t":"1.706 km","mis":"M4-2-u3-X04"},{"t":"10.76 km","mis":"M4-2-u3-X04"}],"explanation":["76 m = 0.076 km — 0.001 km가 76개예요.","1 km + 0.076 km = 1.076 km.","빈 자리에는 0을 써요 — 1.076."],"asset":null},{"stem":"안내견 훈련 길이 2 km 21 m예요. 몇 km인가요?","options":[{"t":"2.021 km","correct":true},{"t":"2.21 km","mis":"M4-2-u3-X04"},{"t":"2.201 km","mis":"M4-2-u3-X04"},{"t":"20.21 km","mis":"M4-2-u3-X04"}],"explanation":["21 m = 0.021 km — 0.001 km가 21개예요.","2 km + 0.021 km = 2.021 km.","빈 자리에는 0을 써요 — 2.021."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_challenge#8','math',4,2,'u3','L03','g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',4,'essay','teacher','훈련사와 안내견이 걸은 거리 814 m를 km 단위로 나타내고, 1 km를 1000으로 나눈 것과 관련지어 그렇게 나타낸 까닭을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C2","difficulty":4,"kind":"essay","stem":"훈련사와 안내견이 걸은 거리 814 m를 km 단위로 나타내고, 1 km를 1000으로 나눈 것과 관련지어 그렇게 나타낸 까닭을 써 보세요.","answer_guide":{"answer":"예: 1 m는 1 km를 1000으로 나눈 것 중 하나이므로 0.001 km이다. 814 m는 0.001 km가 814개이므로 0.814 km이다. 0.814는 영 점 팔일사라고 읽는다.","scoring_points":["0.814 km라고 답했는가","1 m = 0.001 km라고 썼는가","0.001이 814개라는 까닭을 썼는가"]},"explanation":["1 m = 0.001 km.","0.001 km가 814개.","0.814 km."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_challenge#9','math',4,2,'u3','L03','g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',4,'essay','teacher','서윤이는 「2 km 57 m는 2.57 km야.」라고 했어요. 서윤이의 말이 맞는지 판단하고, 바르게 나타낸 뒤 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C2","difficulty":4,"kind":"essay","stem":"서윤이는 「2 km 57 m는 2.57 km야.」라고 했어요. 서윤이의 말이 맞는지 판단하고, 바르게 나타낸 뒤 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 57 m는 0.001 km가 57개이므로 0.057 km이다. 그래서 2 km 57 m = 2.057 km이다. 2.57 km는 2 km 570 m이다. 소수 첫째 자리가 비어 있으므로 0을 써야 한다.","scoring_points":["서윤이의 말이 틀렸다고 판단했는가","2.057 km로 바르게 나타냈는가","57 m = 0.057 km(빈 자리 0)라고 설명했는가"]},"explanation":["57 m = 0.057 km.","2.057 km.","2.57 km는 2 km 570 m."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L03_challenge#10','math',4,2,'u3','L03','g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',4,'mc','auto','안내견 훈련 길이 5 km 44 m예요. 몇 km인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":10,"concept":"M4-2-u3-C2","difficulty":4,"kind":"mc","stem":"안내견 훈련 길이 5 km 44 m예요. 몇 km인가요?","options":[{"t":"5.044 km","correct":true},{"t":"5.44 km","mis":"M4-2-u3-X04"},{"t":"5.404 km","mis":"M4-2-u3-X04"},{"t":"50.44 km","mis":"M4-2-u3-X04"}],"explanation":["44 m = 0.044 km — 0.001 km가 44개예요.","5 km + 0.044 km = 5.044 km.","빈 자리에는 0을 써요 — 5.044."],"variant_rule":{"alt":[{"stem":"안내견 훈련 길이 1 km 73 m예요. 몇 km인가요?","options":[{"t":"1.073 km","correct":true},{"t":"1.73 km","mis":"M4-2-u3-X04"},{"t":"1.703 km","mis":"M4-2-u3-X04"},{"t":"10.73 km","mis":"M4-2-u3-X04"}],"explanation":["73 m = 0.073 km — 0.001 km가 73개예요.","1 km + 0.073 km = 1.073 km.","빈 자리에는 0을 써요 — 1.073."],"asset":null},{"stem":"안내견 훈련 길이 3 km 6 m예요. 몇 km인가요?","options":[{"t":"3.006 km","correct":true},{"t":"3.6 km","mis":"M4-2-u3-X04"},{"t":"3.06 km","mis":"M4-2-u3-X04"},{"t":"3006 km","mis":"M4-2-u3-X04"}],"explanation":["6 m = 0.006 km — 0.001 km가 6개예요.","3 km + 0.006 km = 3.006 km.","빈 자리에는 0을 써요 — 3.006."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_basic#1','math',4,2,'u3','L04','g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',1,'mc','auto','0.01의 10배는 얼마인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],true,'{"seq":1,"concept":"M4-2-u3-C3","difficulty":1,"kind":"mc","stem":"0.01의 10배는 얼마인가요?","options":[{"t":"0.1","correct":true},{"t":"0.001","mis":"M4-2-u3-X05"},{"t":"1","mis":"M4-2-u3-X06"},{"t":"0.01","mis":"M4-2-u3-X06"}],"explanation":["1 → 0.1 → 0.01 → 0.001 — 오른쪽으로 갈수록 10분의 1씩 작아져요.","0.01의 10배 — 숫자가 왼쪽으로 한 자리.","0.1이에요."],"variant_rule":{"alt":[{"stem":"1의 10분의 1은 얼마인가요?","options":[{"t":"0.1","correct":true},{"t":"10","mis":"M4-2-u3-X05"},{"t":"0.01","mis":"M4-2-u3-X06"},{"t":"1","mis":"M4-2-u3-X06"}],"explanation":["1 → 0.1 → 0.01 → 0.001 — 오른쪽으로 갈수록 10분의 1씩 작아져요.","1의 10분의 1 — 숫자가 오른쪽으로 한 자리.","0.1이에요."],"asset":null},{"stem":"0.01의 10분의 1은 얼마인가요?","options":[{"t":"0.001","correct":true},{"t":"0.1","mis":"M4-2-u3-X05"},{"t":"0.01","mis":"M4-2-u3-X06"},{"t":"10","mis":"M4-2-u3-X06"}],"explanation":["1 → 0.1 → 0.01 → 0.001 — 오른쪽으로 갈수록 10분의 1씩 작아져요.","0.01의 10분의 1 — 숫자가 오른쪽으로 한 자리.","0.001이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_basic#2','math',4,2,'u3','L04','g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',1,'mc','auto','1은 0.1의 몇 배인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":2,"concept":"M4-2-u3-C3","difficulty":1,"kind":"mc","stem":"1은 0.1의 몇 배인가요?","options":[{"t":"10배","correct":true},{"t":"100배","mis":"M4-2-u3-X06"},{"t":"1000배","mis":"M4-2-u3-X06"},{"t":"1배","mis":"M4-2-u3-X05"}],"explanation":["한 자리 옮길 때마다 10배예요.","0.1 → 1은 1자리 차이.","1은 0.1의 10배예요."],"variant_rule":{"alt":[{"stem":"1은 0.01의 몇 배인가요?","options":[{"t":"100배","correct":true},{"t":"10배","mis":"M4-2-u3-X06"},{"t":"1000배","mis":"M4-2-u3-X06"},{"t":"1배","mis":"M4-2-u3-X05"}],"explanation":["한 자리 옮길 때마다 10배예요.","0.01 → 1은 2자리 차이.","1은 0.01의 100배예요."],"asset":null},{"stem":"0.1은 0.001의 몇 배인가요?","options":[{"t":"100배","correct":true},{"t":"10배","mis":"M4-2-u3-X06"},{"t":"1000배","mis":"M4-2-u3-X06"},{"t":"1배","mis":"M4-2-u3-X05"}],"explanation":["한 자리 옮길 때마다 10배예요.","0.001 → 0.1은 2자리 차이.","0.1은 0.001의 100배예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_basic#3','math',4,2,'u3','L04','g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',1,'sa','auto','0.001의 몇 배가 0.1인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u3-C3","difficulty":1,"kind":"sa","stem":"0.001의 몇 배가 0.1인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["0.001을 10배 하면 0.01.","2번 10배 하면 0.1 — 10을 2번 곱해요.","100배예요."],"variant_rule":{"alt":[{"stem":"0.001의 몇 배가 0.01인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["0.001을 10배 하면 0.01.","1번 10배 하면 0.01 — 10을 1번 곱해요.","10배예요."],"asset":null},{"stem":"0.01의 몇 배가 1인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["0.01을 10배 하면 0.1.","2번 10배 하면 1 — 10을 2번 곱해요.","100배예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_basic#4','math',4,2,'u3','L04','g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',1,'sa','auto','5.4초의 100분의 1은 0.054초예요. 0.054는 0.001이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u3-C3","difficulty":1,"kind":"sa","stem":"5.4초의 100분의 1은 0.054초예요. 0.054는 0.001이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["백분의 1을 하면 숫자가 오른쪽으로 두 자리 옮겨 가요.","5.4의 100분의 1 = 0.054.","0.054는 0.001이 54개예요."],"variant_rule":{"alt":[{"stem":"7.3 kg의 100분의 1은 0.073 kg이에요. 0.073은 0.001이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["73"],"explanation":["백분의 1을 하면 숫자가 오른쪽으로 두 자리 옮겨 가요.","7.3의 100분의 1 = 0.073.","0.073은 0.001이 73개예요."],"asset":null},{"stem":"8.9초의 100분의 1은 0.089초예요. 0.089는 0.001이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["89"],"explanation":["백분의 1을 하면 숫자가 오른쪽으로 두 자리 옮겨 가요.","8.9의 100분의 1 = 0.089.","0.089는 0.001이 89개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_basic#5','math',4,2,'u3','L04','g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',2,'mc','auto','0.65의 10배는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":5,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"0.65의 10배는 얼마인가요?","options":[{"t":"6.5","correct":true},{"t":"65","mis":"M4-2-u3-X06"},{"t":"0.065","mis":"M4-2-u3-X05"},{"t":"650","mis":"M4-2-u3-X06"}],"explanation":["10배 하면 숫자가 왼쪽으로 한 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","0.65의 10배 → 6.5."],"variant_rule":{"alt":[{"stem":"53.6의 100배는 얼마인가요?","options":[{"t":"5360","correct":true},{"t":"536","mis":"M4-2-u3-X06"},{"t":"5.36","mis":"M4-2-u3-X05"},{"t":"0.536","mis":"M4-2-u3-X05"}],"explanation":["100배 하면 숫자가 왼쪽으로 두 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","53.6의 100배 → 5360."],"asset":null},{"stem":"60.9의 10배는 얼마인가요?","options":[{"t":"609","correct":true},{"t":"6090","mis":"M4-2-u3-X06"},{"t":"6.09","mis":"M4-2-u3-X05"},{"t":"0.609","mis":"M4-2-u3-X05"}],"explanation":["10배 하면 숫자가 왼쪽으로 한 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","60.9의 10배 → 609."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_basic#6','math',4,2,'u3','L04','g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',2,'mc','auto','0.065를 10배 하면 숫자는 어느 쪽으로 몇 자리 옮겨 가나요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],true,'{"seq":6,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"0.065를 10배 하면 숫자는 어느 쪽으로 몇 자리 옮겨 가나요?","options":[{"t":"왼쪽으로 한 자리","correct":true},{"t":"오른쪽으로 한 자리","mis":"M4-2-u3-X05"},{"t":"왼쪽으로 두 자리","mis":"M4-2-u3-X06"},{"t":"오른쪽으로 두 자리","mis":"M4-2-u3-X05"}],"explanation":["10배·100배는 커지니까 왼쪽으로, 10분의 1·100분의 1은 작아지니까 오른쪽으로.","0이 하나면 한 자리, 둘이면 두 자리.","0.065의 10배 → 0.65 — 왼쪽으로 한 자리."],"variant_rule":{"alt":[{"stem":"25.1을 10분의 1 하면 숫자는 어느 쪽으로 몇 자리 옮겨 가나요?","options":[{"t":"오른쪽으로 한 자리","correct":true},{"t":"왼쪽으로 한 자리","mis":"M4-2-u3-X05"},{"t":"왼쪽으로 두 자리","mis":"M4-2-u3-X05"},{"t":"오른쪽으로 두 자리","mis":"M4-2-u3-X06"}],"explanation":["10배·100배는 커지니까 왼쪽으로, 10분의 1·100분의 1은 작아지니까 오른쪽으로.","0이 하나면 한 자리, 둘이면 두 자리.","25.1의 10분의 1 → 2.51 — 오른쪽으로 한 자리."],"asset":null},{"stem":"68.5를 10분의 1 하면 숫자는 어느 쪽으로 몇 자리 옮겨 가나요?","options":[{"t":"오른쪽으로 한 자리","correct":true},{"t":"왼쪽으로 한 자리","mis":"M4-2-u3-X05"},{"t":"왼쪽으로 두 자리","mis":"M4-2-u3-X05"},{"t":"오른쪽으로 두 자리","mis":"M4-2-u3-X06"}],"explanation":["10배·100배는 커지니까 왼쪽으로, 10분의 1·100분의 1은 작아지니까 오른쪽으로.","0이 하나면 한 자리, 둘이면 두 자리.","68.5의 10분의 1 → 6.85 — 오른쪽으로 한 자리."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_basic#7','math',4,2,'u3','L04','g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',2,'sa','auto','0.001을 10배 하고, 그 수를 또 10배 하고, 마지막으로 한 번 더 10배 했어요. 마지막 수는 처음 수의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u3-C3","difficulty":2,"kind":"sa","stem":"0.001을 10배 하고, 그 수를 또 10배 하고, 마지막으로 한 번 더 10배 했어요. 마지막 수는 처음 수의 몇 배인가요? 숫자로 쓰세요.","answer":["1000"],"explanation":["0.001 → … → 1.","10배를 3번 — 10을 3번 곱해요.","1000배예요."],"variant_rule":{"alt":[{"stem":"1의 10분의 1을 구하고, 그 수의 10분의 1을 또 구하고, 마지막으로 한 번 더 10분의 1을 구했어요. 처음 수는 마지막 수의 몇 배인가요? 숫자로 쓰세요.","answer":["1000"],"explanation":["1 → … → 0.001.","10분의 1을 3번 — 거꾸로 보면 10배를 3번.","1000배예요."],"asset":null},{"stem":"1의 10분의 1을 구하고, 마지막으로 한 번 더 10분의 1을 구했어요. 처음 수는 마지막 수의 몇 배인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["1 → … → 0.01.","10분의 1을 2번 — 거꾸로 보면 10배를 2번.","100배예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
