INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_basic#9','math',4,2,'u3','L04','g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',2,'ox','auto','서준이 「99.5의 10분의 1은 995야.」라고 했어요. 바르게 말했어요.',ARRAY['M4-2-u3-X05']::text[],true,'{"seq":9,"concept":"M4-2-u3-C3","difficulty":2,"kind":"ox","stem":"서준이 「99.5의 10분의 1은 995야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"10분의 1 하면 숫자가 오른쪽으로 옮겨 가야 해서","correct":true},{"t":"숫자가 왼쪽으로 옮겨 가서","mis":"M4-2-u3-X05"}],"mis":"M4-2-u3-X05","explanation":["10분의 1 → 숫자가 오른쪽으로.","99.5의 10분의 1 = 9.95.","서준의 말은 틀렸어요 ×."],"variant_rule":{"alt":[{"stem":"도연이 「5.35의 10배는 0.535야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"10배 하면 숫자가 왼쪽으로 옮겨 가야 해서","correct":true},{"t":"숫자가 오른쪽으로 옮겨 가서","mis":"M4-2-u3-X05"}],"explanation":["10배 → 숫자가 왼쪽으로.","5.35의 10배 = 53.5.","도연의 말은 틀렸어요 ×."],"asset":null},{"stem":"민서가 「9.9의 10배는 0.99야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"10배 하면 숫자가 왼쪽으로 옮겨 가야 해서","correct":true},{"t":"숫자가 오른쪽으로 옮겨 가서","mis":"M4-2-u3-X05"}],"explanation":["10배 → 숫자가 왼쪽으로.","9.9의 10배 = 99.","민서의 말은 틀렸어요 ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
