INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_challenge#2','math',4,2,'u3','L04','g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',2,'mc','auto','87.8은 8.78의 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":2,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"87.8은 8.78의 얼마인가요?","options":[{"t":"10배","correct":true},{"t":"100배","mis":"M4-2-u3-X06"},{"t":"10분의 1","mis":"M4-2-u3-X05"},{"t":"100분의 1","mis":"M4-2-u3-X05"}],"explanation":["8.78 → 87.8 — 숫자가 왼쪽으로 한 자리 옮겨 갔어요.","왼쪽으로 옮겨 가면 커져요(배).","87.8은 8.78의 10배예요."],"variant_rule":{"alt":[{"stem":"9.76은 97.6의 얼마인가요?","options":[{"t":"10분의 1","correct":true},{"t":"10배","mis":"M4-2-u3-X05"},{"t":"100배","mis":"M4-2-u3-X05"},{"t":"100분의 1","mis":"M4-2-u3-X06"}],"explanation":["97.6 → 9.76 — 숫자가 오른쪽으로 한 자리 옮겨 갔어요.","오른쪽으로 옮겨 가면 작아져요(분의 1).","9.76은 97.6의 10분의 1이에요."],"asset":null},{"stem":"650은 6.5의 얼마인가요?","options":[{"t":"100배","correct":true},{"t":"10배","mis":"M4-2-u3-X06"},{"t":"10분의 1","mis":"M4-2-u3-X05"},{"t":"100분의 1","mis":"M4-2-u3-X05"}],"explanation":["6.5 → 650 — 숫자가 왼쪽으로 두 자리 옮겨 갔어요.","왼쪽으로 옮겨 가면 커져요(배).","650은 6.5의 100배예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_challenge#3','math',4,2,'u3','L04','g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',3,'mc','auto','어떤 수의 10배는 996이에요. 어떤 수는 얼마인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],true,'{"seq":3,"concept":"M4-2-u3-C3","difficulty":3,"kind":"mc","stem":"어떤 수의 10배는 996이에요. 어떤 수는 얼마인가요?","options":[{"t":"99.6","correct":true},{"t":"9960","mis":"M4-2-u3-X05"},{"t":"99600","mis":"M4-2-u3-X06"},{"t":"9.96","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 10배 → 996.","거꾸로 996의 10분의 1을 구해요.","어떤 수 = 99.6."],"variant_rule":{"alt":[{"stem":"어떤 수의 100분의 1은 0.046이에요. 어떤 수는 얼마인가요?","options":[{"t":"4.6","correct":true},{"t":"0.46","mis":"M4-2-u3-X06"},{"t":"0.046","mis":"M4-2-u3-X05"},{"t":"46","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 100분의 1 → 0.046.","거꾸로 0.046의 100배를 구해요.","어떤 수 = 4.6."],"asset":null},{"stem":"어떤 수의 100배는 743이에요. 어떤 수는 얼마인가요?","options":[{"t":"7.43","correct":true},{"t":"7430","mis":"M4-2-u3-X06"},{"t":"74300","mis":"M4-2-u3-X05"},{"t":"74.3","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 100배 → 743.","거꾸로 743의 100분의 1을 구해요.","어떤 수 = 7.43."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_challenge#4','math',4,2,'u3','L04','g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',3,'error','auto','9.9를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],true,'{"seq":4,"concept":"M4-2-u3-C3","difficulty":3,"kind":"error","stem":"9.9를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「9.9의 100배는 0.099」","correct":true,"mis_target":"M4-2-u3-X05"},{"t":"건우 — 「9.9의 10배는 99」","mis":"M4-2-u3-X06"},{"t":"지훈 — 「9.9의 10분의 1은 0.99」","mis":"M4-2-u3-X06"},{"t":"서윤 — 「9.9의 100분의 1은 0.099」","mis":"M4-2-u3-X06"}],"explanation":["10배·100배는 숫자가 왼쪽으로 한·두 자리.","10분의 1·100분의 1은 오른쪽으로 한·두 자리.","9.9의 100배 → 990 — 지유의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"8.8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「8.8의 100분의 1은 880」","correct":true,"mis_target":"M4-2-u3-X05"},{"t":"건우 — 「8.8의 10배는 88」","mis":"M4-2-u3-X06"},{"t":"준우 — 「8.8의 100배는 880」","mis":"M4-2-u3-X06"},{"t":"하윤 — 「8.8의 10분의 1은 0.88」","mis":"M4-2-u3-X06"}],"explanation":["10배·100배는 숫자가 왼쪽으로 한·두 자리.","10분의 1·100분의 1은 오른쪽으로 한·두 자리.","8.8의 100분의 1 → 0.088 — 지유의 말이 틀렸어요."],"asset":null},{"stem":"3.4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「3.4의 100분의 1은 340」","correct":true,"mis_target":"M4-2-u3-X05"},{"t":"은비 — 「3.4의 10배는 34」","mis":"M4-2-u3-X06"},{"t":"건우 — 「3.4의 100배는 340」","mis":"M4-2-u3-X06"},{"t":"준우 — 「3.4의 10분의 1은 0.34」","mis":"M4-2-u3-X06"}],"explanation":["10배·100배는 숫자가 왼쪽으로 한·두 자리.","10분의 1·100분의 1은 오른쪽으로 한·두 자리.","3.4의 100분의 1 → 0.034 — 서준의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_challenge#5','math',4,2,'u3','L04','g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',3,'sa','auto','반려동물 영양사가 영양제를 0.01 kg씩 덜어 간식에 섞어요. 0.1 kg이 되려면 0.01 kg씩 몇 번 덜어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u3-C3","difficulty":3,"kind":"sa","stem":"반려동물 영양사가 영양제를 0.01 kg씩 덜어 간식에 섞어요. 0.1 kg이 되려면 0.01 kg씩 몇 번 덜어야 하나요? 숫자로 쓰세요.","answer":["10"],"explanation":["0.1 kg은 0.01 kg의 몇 배인지 구하면 돼요.","0.01 → 0.1은 10배.","10번 덜어야 해요."],"variant_rule":{"alt":[{"stem":"반려동물 영양사가 영양제를 0.001 kg씩 덜어 간식에 섞어요. 0.1 kg이 되려면 0.001 kg씩 몇 번 덜어야 하나요? 숫자로 쓰세요.","answer":["100"],"explanation":["0.1 kg은 0.001 kg의 몇 배인지 구하면 돼요.","0.001 → 0.1은 100배.","100번 덜어야 해요."],"asset":null},{"stem":"반려동물 영양사가 영양제를 0.01 kg씩 덜어 간식에 섞어요. 1 kg이 되려면 0.01 kg씩 몇 번 덜어야 하나요? 숫자로 쓰세요.","answer":["100"],"explanation":["1 kg은 0.01 kg의 몇 배인지 구하면 돼요.","0.01 → 1은 100배.","100번 덜어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_challenge#6','math',4,2,'u3','L04','g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',3,'sa','auto','1의 10분의 1을 구하고, 그 수의 10분의 1을 또 구하고, 마지막으로 한 번 더 10분의 1을 구했어요. 처음 수는 마지막 수의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u3-C3","difficulty":3,"kind":"sa","stem":"1의 10분의 1을 구하고, 그 수의 10분의 1을 또 구하고, 마지막으로 한 번 더 10분의 1을 구했어요. 처음 수는 마지막 수의 몇 배인가요? 숫자로 쓰세요.","answer":["1000"],"explanation":["1 → … → 0.001.","10분의 1을 3번 — 거꾸로 보면 10배를 3번.","1000배예요."],"variant_rule":{"alt":[{"stem":"0.001을 10배 하고, 마지막으로 한 번 더 10배 했어요. 마지막 수는 처음 수의 몇 배인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["0.001 → … → 0.1.","10배를 2번 — 10을 2번 곱해요.","100배예요."],"asset":null},{"stem":"1의 10분의 1을 구하고, 마지막으로 한 번 더 10분의 1을 구했어요. 처음 수는 마지막 수의 몇 배인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["1 → … → 0.01.","10분의 1을 2번 — 거꾸로 보면 10배를 2번.","100배예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_challenge#7','math',4,2,'u3','L04','g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',3,'mc','auto','8.64 kg의 10분의 1은 몇 kg인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],true,'{"seq":7,"concept":"M4-2-u3-C3","difficulty":3,"kind":"mc","stem":"8.64 kg의 10분의 1은 몇 kg인가요?","options":[{"t":"0.864 kg","correct":true},{"t":"86.4 kg","mis":"M4-2-u3-X05"},{"t":"864 kg","mis":"M4-2-u3-X05"},{"t":"8640 kg","mis":"M4-2-u3-X06"}],"explanation":["10분의 1 하면 숫자가 오른쪽으로 한 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","8.64 kg의 10분의 1 → 0.864 kg."],"variant_rule":{"alt":[{"stem":"8.9 kg의 10분의 1은 몇 kg인가요?","options":[{"t":"0.89 kg","correct":true},{"t":"89 kg","mis":"M4-2-u3-X05"},{"t":"890 kg","mis":"M4-2-u3-X05"},{"t":"0.089 kg","mis":"M4-2-u3-X06"}],"explanation":["10분의 1 하면 숫자가 오른쪽으로 한 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","8.9 kg의 10분의 1 → 0.89 kg."],"asset":null},{"stem":"27.7 kg의 100분의 1은 몇 kg인가요?","options":[{"t":"0.277 kg","correct":true},{"t":"277 kg","mis":"M4-2-u3-X05"},{"t":"2770 kg","mis":"M4-2-u3-X05"},{"t":"2.77 kg","mis":"M4-2-u3-X06"}],"explanation":["100분의 1 하면 숫자가 오른쪽으로 두 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","27.7 kg의 100분의 1 → 0.277 kg."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_challenge#8','math',4,2,'u3','L04','g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',4,'essay','teacher','은비는 「2.4의 10분의 1을 하면 소수점이 왼쪽으로 옮겨 가서 0.24가 돼.」라고 했어요. 자릿값 표를 생각하며 무엇이 옮겨 가는지 바르게 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C3","difficulty":4,"kind":"essay","stem":"은비는 「2.4의 10분의 1을 하면 소수점이 왼쪽으로 옮겨 가서 0.24가 돼.」라고 했어요. 자릿값 표를 생각하며 무엇이 옮겨 가는지 바르게 설명해 보세요.","answer_guide":{"answer":"예: 2.4의 10분의 1은 0.24이다. 자릿값 표에서 보면 소수점은 늘 일의 자리 오른쪽에 그대로 있고, 숫자 2와 4가 오른쪽으로 한 자리씩 옮겨 간다. 2는 일의 자리에서 소수 첫째 자리로 가서 0.2를, 4는 소수 둘째 자리로 가서 0.04를 나타낸다.","scoring_points":["0.24라고 답했는가","숫자가 오른쪽으로 한 자리 옮겨 간다고 썼는가","소수점은 제자리에 있다고 설명했는가"]},"explanation":["2.4 → 0.24.","숫자가 오른쪽으로 한 자리.","소수점은 그대로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_challenge#9','math',4,2,'u3','L04','g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',4,'essay','teacher','반려동물 영양사가 1 kg짜리 영양제를 0.1 kg, 0.01 kg, 0.001 kg씩 덜어 쓰려고 해요. 1 kg은 0.001 kg의 몇 배인지 구하고, 1, 0.1, 0.01, 0.001 사이의 관계를 써서 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C3","difficulty":4,"kind":"essay","stem":"반려동물 영양사가 1 kg짜리 영양제를 0.1 kg, 0.01 kg, 0.001 kg씩 덜어 쓰려고 해요. 1 kg은 0.001 kg의 몇 배인지 구하고, 1, 0.1, 0.01, 0.001 사이의 관계를 써서 설명해 보세요.","answer_guide":{"answer":"예: 0.001을 10배 하면 0.01, 0.01을 10배 하면 0.1, 0.1을 10배 하면 1이다. 10배를 세 번 했으므로 1은 0.001의 1000배이다. 1 kg은 0.001 kg의 1000배이다.","scoring_points":["1000배라고 답했는가","0.001 → 0.01 → 0.1 → 1이 10배씩이라고 썼는가","10배를 세 번 했다고 설명했는가"]},"explanation":["10배씩 세 번.","10 × 10 × 10 = 1000.","1000배."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L04_challenge#10','math',4,2,'u3','L04','g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',4,'mc','auto','어떤 수의 100배는 807이에요. 어떤 수는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":10,"concept":"M4-2-u3-C3","difficulty":4,"kind":"mc","stem":"어떤 수의 100배는 807이에요. 어떤 수는 얼마인가요?","options":[{"t":"8.07","correct":true},{"t":"8070","mis":"M4-2-u3-X06"},{"t":"80700","mis":"M4-2-u3-X05"},{"t":"80.7","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 100배 → 807.","거꾸로 807의 100분의 1을 구해요.","어떤 수 = 8.07."],"variant_rule":{"alt":[{"stem":"어떤 수의 100배는 913이에요. 어떤 수는 얼마인가요?","options":[{"t":"9.13","correct":true},{"t":"9130","mis":"M4-2-u3-X06"},{"t":"91300","mis":"M4-2-u3-X05"},{"t":"91.3","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 100배 → 913.","거꾸로 913의 100분의 1을 구해요.","어떤 수 = 9.13."],"asset":null},{"stem":"어떤 수의 10배는 226이에요. 어떤 수는 얼마인가요?","options":[{"t":"22.6","correct":true},{"t":"2260","mis":"M4-2-u3-X05"},{"t":"22600","mis":"M4-2-u3-X06"},{"t":"2.26","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 10배 → 226.","거꾸로 226의 10분의 1을 구해요.","어떤 수 = 22.6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L05_basic#1','math',4,2,'u3','L05','g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',1,'mc','auto','0.47과 0.5 중 더 큰 수는 어느 것인가요?',ARRAY['M4-2-u3-X08','M4-2-u3-X18']::text[],true,'{"seq":1,"concept":"M4-2-u3-C4","difficulty":1,"kind":"mc","stem":"0.47과 0.5 중 더 큰 수는 어느 것인가요?","options":[{"t":"0.5","correct":true},{"t":"0.47","mis":"M4-2-u3-X08"},{"t":"두 수는 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어요 — 0.47, 0.50.","큰 자리부터 차례로 견주어요.","더 큰 수는 0.5예요."],"variant_rule":{"alt":[{"stem":"0.6과 0.55 중 더 큰 수는 어느 것인가요?","options":[{"t":"0.6","correct":true},{"t":"0.55","mis":"M4-2-u3-X08"},{"t":"두 수는 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어요 — 0.60, 0.55.","큰 자리부터 차례로 견주어요.","더 큰 수는 0.6이에요."],"asset":null},{"stem":"0.65와 0.7 중 더 큰 수는 어느 것인가요?","options":[{"t":"0.7","correct":true},{"t":"0.65","mis":"M4-2-u3-X08"},{"t":"두 수는 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어요 — 0.65, 0.70.","큰 자리부터 차례로 견주어요.","더 큰 수는 0.7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L05_basic#2','math',4,2,'u3','L05','g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',1,'mc','auto','0.5와 0.50의 크기는 어떤가요?',ARRAY['M4-2-u3-X09','M4-2-u3-X18']::text[],true,'{"seq":2,"concept":"M4-2-u3-C4","difficulty":1,"kind":"mc","stem":"0.5와 0.50의 크기는 어떤가요?","options":[{"t":"두 수는 같아요","correct":true},{"t":"0.5가 더 커요","mis":"M4-2-u3-X09"},{"t":"0.50이 더 커요","mis":"M4-2-u3-X09"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["0.50은 0.5 — 끝자리에 0을 붙인 수예요.","모눈에 나타내면 색칠한 넓이가 같아요.","소수는 오른쪽 끝자리에 0을 붙여도 크기가 같아요."],"variant_rule":{"alt":[{"stem":"4.7과 4.70의 크기는 어떤가요?","options":[{"t":"두 수는 같아요","correct":true},{"t":"4.7이 더 커요","mis":"M4-2-u3-X09"},{"t":"4.70이 더 커요","mis":"M4-2-u3-X09"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["4.70은 4.7 — 끝자리에 0을 붙인 수예요.","모눈에 나타내면 색칠한 넓이가 같아요.","소수는 오른쪽 끝자리에 0을 붙여도 크기가 같아요."],"asset":null},{"stem":"0.42와 0.420의 크기는 어떤가요?","options":[{"t":"두 수는 같아요","correct":true},{"t":"0.42가 더 커요","mis":"M4-2-u3-X09"},{"t":"0.420이 더 커요","mis":"M4-2-u3-X09"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["0.420은 0.42 — 끝자리에 0을 붙인 수예요.","모눈에 나타내면 색칠한 넓이가 같아요.","소수는 오른쪽 끝자리에 0을 붙여도 크기가 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L05_basic#3','math',4,2,'u3','L05','g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',1,'sa','auto','0.5를 100칸 모눈종이에 나타내려고 해요. 색칠할 칸은 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u3-C4","difficulty":1,"kind":"sa","stem":"0.5를 100칸 모눈종이에 나타내려고 해요. 색칠할 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["100칸 모눈 한 칸이 0.01이에요.","0.5 = 0.50 — 0.01이 50개.","50칸을 색칠해요."],"variant_rule":{"alt":[{"stem":"0.1을 100칸 모눈종이에 나타내려고 해요. 색칠할 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["100칸 모눈 한 칸이 0.01이에요.","0.1 = 0.10 — 0.01이 10개.","10칸을 색칠해요."],"asset":null},{"stem":"0.7을 100칸 모눈종이에 나타내려고 해요. 색칠할 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["100칸 모눈 한 칸이 0.01이에요.","0.7 = 0.70 — 0.01이 70개.","70칸을 색칠해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
