INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L05_basic#6','math',4,2,'u3','L05','g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',2,'mc','auto','1.8, 1.888, 1.6을 큰 수부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X03']::text[],true,'{"seq":6,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"1.8, 1.888, 1.6을 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"1.888, 1.8, 1.6","correct":true},{"t":"1.6, 1.8, 1.888","mis":"M4-2-u3-X17"},{"t":"1.888, 1.6, 1.8","mis":"M4-2-u3-X03"},{"t":"1.8, 1.6, 1.888","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 1.888, 1.8, 1.6."],"variant_rule":{"alt":[{"stem":"2.891, 2.7, 2.73을 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"2.891, 2.73, 2.7","correct":true},{"t":"2.7, 2.73, 2.891","mis":"M4-2-u3-X17"},{"t":"2.73, 2.891, 2.7","mis":"M4-2-u3-X03"},{"t":"2.73, 2.7, 2.891","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 2.891, 2.73, 2.7."],"asset":null},{"stem":"3.5, 3.777, 3.96을 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"3.96, 3.777, 3.5","correct":true},{"t":"3.5, 3.777, 3.96","mis":"M4-2-u3-X17"},{"t":"3.777, 3.96, 3.5","mis":"M4-2-u3-X07"},{"t":"3.96, 3.5, 3.777","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 3.96, 3.777, 3.5."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L05_basic#7','math',4,2,'u3','L05','g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',2,'sa','auto','0.563과 0.561 중 더 큰 수의 소수 셋째 자리 숫자는 몇인가요?','{}'::text[],true,'{"seq":7,"concept":"M4-2-u3-C4","difficulty":2,"kind":"sa","stem":"0.563과 0.561 중 더 큰 수의 소수 셋째 자리 숫자는 몇인가요?","answer":["3"],"explanation":["일의 자리·소수 첫째·둘째 자리가 같아요.","소수 셋째 자리 3과 1을 견주어요.","더 큰 수는 0.563 — 소수 셋째 자리 숫자 3."],"variant_rule":{"alt":[{"stem":"3.622와 3.623 중 더 큰 수의 소수 셋째 자리 숫자는 몇인가요?","answer":["3"],"explanation":["일의 자리·소수 첫째·둘째 자리가 같아요.","소수 셋째 자리 2와 3을 견주어요.","더 큰 수는 3.623 — 소수 셋째 자리 숫자 3."],"asset":null},{"stem":"2.543과 2.544 중 더 큰 수의 소수 셋째 자리 숫자는 몇인가요?","answer":["4"],"explanation":["일의 자리·소수 첫째·둘째 자리가 같아요.","소수 셋째 자리 3과 4를 견주어요.","더 큰 수는 2.544 — 소수 셋째 자리 숫자 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L05_basic#8','math',4,2,'u3','L05','g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',2,'ox','auto','지유가 「47이 5보다 크니까 0.47이 0.5보다 더 커.」라고 했어요. 바르게 말했어요.',ARRAY['M4-2-u3-X08']::text[],true,'{"seq":8,"concept":"M4-2-u3-C4","difficulty":2,"kind":"ox","stem":"지유가 「47이 5보다 크니까 0.47이 0.5보다 더 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"0.5 = 0.50라서 0.01이 47개와 50개로 견주어야 해서","correct":true},{"t":"소수점 오른쪽 수가 클수록 큰 수라서","mis":"M4-2-u3-X08"}],"mis":"M4-2-u3-X08","explanation":["0.5 = 0.50 — 자리를 맞추어요.","0.01이 47개 < 50개.","0.47 < 0.5 — 지유의 말은 틀렸어요 ×."],"variant_rule":{"alt":[{"stem":"은비가 「16이 2보다 크니까 0.16이 0.2보다 더 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"0.2 = 0.20라서 0.01이 16개와 20개로 견주어야 해서","correct":true},{"t":"소수점 오른쪽 수가 클수록 큰 수라서","mis":"M4-2-u3-X08"}],"explanation":["0.2 = 0.20 — 자리를 맞추어요.","0.01이 16개 < 20개.","0.16 < 0.2 — 은비의 말은 틀렸어요 ×."],"asset":null},{"stem":"지훈이 「36이 4보다 크니까 0.36이 0.4보다 더 커.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"0.4 = 0.40라서 0.01이 36개와 40개로 견주어야 해서","correct":true},{"t":"소수점 오른쪽 수가 클수록 큰 수라서","mis":"M4-2-u3-X08"}],"explanation":["0.4 = 0.40 — 자리를 맞추어요.","0.01이 36개 < 40개.","0.36 < 0.4 — 지훈의 말은 틀렸어요 ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L05_basic#9','math',4,2,'u3','L05','g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',2,'mc','auto','사육사가 수달 두 마리의 키를 재었어요. 가는 0.76 m, 나는 68 cm예요. 키가 더 큰 쪽은 어느 쪽인가요?',ARRAY['M4-2-u3-X04','M4-2-u3-X18']::text[],true,'{"seq":9,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"사육사가 수달 두 마리의 키를 재었어요. 가는 0.76 m, 나는 68 cm예요. 키가 더 큰 쪽은 어느 쪽인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M4-2-u3-X04"},{"t":"두 마리가 같아요","mis":"M4-2-u3-X18"},{"t":"단위가 달라 견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["68 cm = 0.68 m.","0.76 m > 0.68 m.","키가 더 큰 쪽은 가예요."],"variant_rule":{"alt":[{"stem":"사육사가 홍학 두 마리의 키를 재었어요. 가는 0.97 m, 나는 96 cm예요. 키가 더 큰 쪽은 어느 쪽인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M4-2-u3-X04"},{"t":"두 마리가 같아요","mis":"M4-2-u3-X18"},{"t":"단위가 달라 견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["96 cm = 0.96 m.","0.97 m > 0.96 m.","키가 더 큰 쪽은 가예요."],"asset":null},{"stem":"사육사가 물개 두 마리의 키를 재었어요. 가는 0.65 m, 나는 63 cm예요. 키가 더 큰 쪽은 어느 쪽인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M4-2-u3-X04"},{"t":"두 마리가 같아요","mis":"M4-2-u3-X18"},{"t":"단위가 달라 견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["63 cm = 0.63 m.","0.65 m > 0.63 m.","키가 더 큰 쪽은 가예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
