INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L05_challenge#8','math',4,2,'u3','L05','g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',4,'essay','teacher','은비가 「47이 5보다 크니까 0.47이 0.5보다 더 커.」라고 했어요. 은비의 생각이 맞는지 판단하고, 두 가지 방법(0.01의 개수, 자릿값)으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C4","difficulty":4,"kind":"essay","stem":"은비가 「47이 5보다 크니까 0.47이 0.5보다 더 커.」라고 했어요. 은비의 생각이 맞는지 판단하고, 두 가지 방법(0.01의 개수, 자릿값)으로 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 0.5 = 0.50이므로 0.01이 50개이고 0.47은 0.01이 47개라 0.5가 더 크다. 자릿값으로 보면 소수 첫째 자리 숫자가 4와 5이고 4 < 5이므로 0.5가 더 크다. 소수점 오른쪽 수를 자연수처럼 견주면 안 된다.","scoring_points":["은비의 생각이 틀렸다고 판단했는가","0.5 = 0.50으로 0.01의 개수로 견주었는가","소수 첫째 자리부터 견주는 방법을 썼는가"]},"explanation":["0.5 = 0.50.","0.01이 47개 < 50개.","소수 첫째 자리 4 < 5."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L05_challenge#9','math',4,2,'u3','L05','g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',4,'essay','teacher','0.003과 0.02 중 어느 수가 더 큰지 쓰고, 「자리 수가 많은 수가 더 크다」는 생각이 왜 틀렸는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C4","difficulty":4,"kind":"essay","stem":"0.003과 0.02 중 어느 수가 더 큰지 쓰고, 「자리 수가 많은 수가 더 크다」는 생각이 왜 틀렸는지 설명해 보세요.","answer_guide":{"answer":"예: 0.02가 더 크다. 0.02 = 0.020이므로 0.001이 20개이고, 0.003은 0.001이 3개이다. 자연수는 자리 수가 많으면 크지만 소수는 소수점을 기준으로 자리를 맞추고 큰 자리부터 견주어야 한다. 소수 둘째 자리에서 2 > 0이다.","scoring_points":["0.02가 더 크다고 답했는가","0.001의 개수 또는 자리를 맞추어 견주었는가","수의 길이로 견주면 안 되는 까닭을 썼는가"]},"explanation":["0.02 = 0.020.","0.001이 20개 > 3개.","길이로 견주지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L05_challenge#10','math',4,2,'u3','L05','g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',4,'sa','auto','2.29□ < 2.296일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u3-C4","difficulty":4,"kind":"sa","stem":"2.29□ < 2.296일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 0, 1, 2, 3, 4, 5.","모두 6개 — 같아지는 수·경계의 수를 확인해요."],"variant_rule":{"alt":[{"stem":"2.1□6 < 2.142일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 0, 1, 2, 3.","모두 4개 — 같아지는 수·경계의 수를 확인해요."],"asset":null},{"stem":"2.8□3 < 2.857일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 0, 1, 2, 3, 4, 5.","모두 6개 — 같아지는 수·경계의 수를 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
