INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L06_basic#4','math',4,2,'u3','L06','g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',1,'sa','auto','수직선에서 1.7에서 오른쪽으로 0.6만큼 더 갔어요. 도착한 수는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u3-C5","difficulty":1,"kind":"sa","stem":"수직선에서 1.7에서 오른쪽으로 0.6만큼 더 갔어요. 도착한 수는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.1이 17개 + 6개 = 23개 — 0.1이 10개 모이면 윗자리 1로 받아올림해요.","1.7 + 0.6 = 2.3."],"variant_rule":{"alt":[{"stem":"수직선에서 3.5에서 오른쪽으로 2.8만큼 더 갔어요. 도착한 수는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.1이 35개 + 28개 = 63개 — 0.1이 10개 모이면 윗자리 1로 받아올림해요.","3.5 + 2.8 = 6.3."],"asset":null},{"stem":"수직선에서 2.9에서 오른쪽으로 2.5만큼 더 갔어요. 도착한 수는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.1이 29개 + 25개 = 54개 — 0.1이 10개 모이면 윗자리 1로 받아올림해요.","2.9 + 2.5 = 5.4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
