INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L06_basic#7','math',4,2,'u3','L06','g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',2,'mc','auto','동물 보건사가 고양이들에게 오전에 사료 1.7 kg, 오후에 2.5 kg을 주었어요. 하루에 준 사료는 모두 몇 kg인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],true,'{"seq":7,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"동물 보건사가 고양이들에게 오전에 사료 1.7 kg, 오후에 2.5 kg을 주었어요. 하루에 준 사료는 모두 몇 kg인가요?","options":[{"t":"4.2 kg","correct":true},{"t":"3.2 kg","mis":"M4-2-u3-X11"},{"t":"3.12 kg","mis":"M4-2-u3-X10"},{"t":"0.8 kg","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","1.7 + 2.5 = 4.2 — 소수점을 맞추어 더해요.","4.2 kg이에요."],"variant_rule":{"alt":[{"stem":"집에서 동물 병원까지 0.7 km, 동물 병원에서 동물원까지 0.7 km예요. 집에서 동물 병원을 지나 동물원까지 간 거리는 몇 km인가요?","options":[{"t":"1.4 km","correct":true},{"t":"0.4 km","mis":"M4-2-u3-X11"},{"t":"0.14 km","mis":"M4-2-u3-X10"},{"t":"0 km","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","0.7 + 0.7 = 1.4 — 소수점을 맞추어 더해요.","1.4 km예요."],"asset":null},{"stem":"동물 보건사가 고양이들에게 오전에 사료 2.9 kg, 오후에 2.5 kg을 주었어요. 하루에 준 사료는 모두 몇 kg인가요?","options":[{"t":"5.4 kg","correct":true},{"t":"4.4 kg","mis":"M4-2-u3-X11"},{"t":"4.14 kg","mis":"M4-2-u3-X10"},{"t":"0.4 kg","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","2.9 + 2.5 = 5.4 — 소수점을 맞추어 더해요.","5.4 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L06_basic#8','math',4,2,'u3','L06','g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',2,'mc','auto','7.8 + 1.9를 계산해 8.7이라고 썼어요. 바르게 고친 값은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],true,'{"seq":8,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"7.8 + 1.9를 계산해 8.7이라고 썼어요. 바르게 고친 값은 얼마인가요?","options":[{"t":"9.7","correct":true},{"t":"8.7","mis":"M4-2-u3-X11"},{"t":"8.17","mis":"M4-2-u3-X10"},{"t":"5.9","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.1이 78개 + 19개 = 97개 — 0.1이 10개 모이면 윗자리 1로 받아올림해요.","7.8 + 1.9 = 9.7."],"variant_rule":{"alt":[{"stem":"0.5 + 1.8을 계산해 1.3이라고 썼어요. 바르게 고친 값은 얼마인가요?","options":[{"t":"2.3","correct":true},{"t":"1.3","mis":"M4-2-u3-X11"},{"t":"1.13","mis":"M4-2-u3-X10"},{"t":"0.23","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.1이 5개 + 18개 = 23개 — 0.1이 10개 모이면 윗자리 1로 받아올림해요.","0.5 + 1.8 = 2.3."],"asset":null},{"stem":"8.9 + 4.5를 계산해 2.4라고 썼어요. 바르게 고친 값은 얼마인가요?","options":[{"t":"13.4","correct":true},{"t":"2.4","mis":"M4-2-u3-X11"},{"t":"12.14","mis":"M4-2-u3-X10"},{"t":"12.4","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.1이 89개 + 45개 = 134개 — 0.1이 10개 모이면 윗자리 1로 받아올림해요.","8.9 + 4.5 = 13.4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L06_basic#9','math',4,2,'u3','L06','g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',2,'ox','auto','건우가 「6.6 + 5.7 = 11.13이야.」라고 했어요. 바르게 계산했어요.',ARRAY['M4-2-u3-X10']::text[],true,'{"seq":9,"concept":"M4-2-u3-C5","difficulty":2,"kind":"ox","stem":"건우가 「6.6 + 5.7 = 11.13이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"0.1이 10개면 1로 받아올림해야 해서","correct":true},{"t":"받아올림은 하지 않아도 되어서","mis":"M4-2-u3-X10"}],"mis":"M4-2-u3-X10","explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.1이 66개 + 57개 = 123개 — 0.1이 10개 모이면 윗자리 1로 받아올림해요.","6.6 + 5.7 = 12.3."],"variant_rule":{"alt":[{"stem":"도연이 「4.9 + 2.6 = 7.5야.」라고 했어요. 바르게 계산했어요.","answer":"O","reason_options":[{"t":"소수점을 맞추어 같은 자리끼리 더하고 받아올림했어서","correct":true},{"t":"받아올림은 하지 않아도 되어서","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.1이 49개 + 26개 = 75개 — 0.1이 10개 모이면 윗자리 1로 받아올림해요.","4.9 + 2.6 = 7.5."],"asset":null},{"stem":"은비가 「1.9 + 4.6 = 5.15야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"0.1이 10개면 1로 받아올림해야 해서","correct":true},{"t":"받아올림은 하지 않아도 되어서","mis":"M4-2-u3-X10"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.1이 19개 + 46개 = 65개 — 0.1이 10개 모이면 윗자리 1로 받아올림해요.","1.9 + 4.6 = 6.5."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L06_basic#10','math',4,2,'u3','L06','g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',3,'mc','auto','□ + 0.6 = 4.3일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X13','M4-2-u3-X14']::text[],true,'{"seq":10,"concept":"M4-2-u3-C5","difficulty":3,"kind":"mc","stem":"□ + 0.6 = 4.3일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"3.7","correct":true},{"t":"4.9","mis":"M4-2-u3-X16"},{"t":"4.3","mis":"M4-2-u3-X13"},{"t":"4.7","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","4.3 − 0.6 = 3.7.","확인: 3.7 + 0.6 = 4.3."],"variant_rule":{"alt":[{"stem":"□ + 3.5 = 10.4일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"6.9","correct":true},{"t":"13.9","mis":"M4-2-u3-X16"},{"t":"13.1","mis":"M4-2-u3-X13"},{"t":"17.9","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","10.4 − 3.5 = 6.9.","확인: 6.9 + 3.5 = 10.4."],"asset":null},{"stem":"□ + 2.6 = 8.1일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"5.5","correct":true},{"t":"10.7","mis":"M4-2-u3-X16"},{"t":"6.5","mis":"M4-2-u3-X13"},{"t":"4.5","mis":"M4-2-u3-X11"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","8.1 − 2.6 = 5.5.","확인: 5.5 + 2.6 = 8.1."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
