INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L07_basic#7','math',4,2,'u3','L07','g4_2_math_u3_L07_basic','lesson_basic','M4-2-u3-C6',2,'mc','auto','사육사가 원숭이 놀이터에 밧줄 0.47 m와 2.57 m를 이어 달았어요(겹친 곳 없음). 이은 밧줄은 모두 몇 m인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X16']::text[],true,'{"seq":7,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"사육사가 원숭이 놀이터에 밧줄 0.47 m와 2.57 m를 이어 달았어요(겹친 곳 없음). 이은 밧줄은 모두 몇 m인가요?","options":[{"t":"3.04 m","correct":true},{"t":"2.94 m","mis":"M4-2-u3-X11"},{"t":"2.04 m","mis":"M4-2-u3-X11"},{"t":"2.1 m","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","0.47 + 2.57 = 3.04 — 소수점을 맞추어 더해요.","3.04 m예요."],"variant_rule":{"alt":[{"stem":"수산 질병 관리사가 물이 0.18 L 들어 있는 수조에 물을 3.83 L 더 넣었어요. 수조의 물은 모두 몇 L인가요?","options":[{"t":"4.01 L","correct":true},{"t":"3.91 L","mis":"M4-2-u3-X11"},{"t":"3.01 L","mis":"M4-2-u3-X11"},{"t":"3.65 L","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","0.18 + 3.83 = 4.01 — 소수점을 맞추어 더해요.","4.01 L예요."],"asset":null},{"stem":"사육사가 원숭이 놀이터에 밧줄 2.25 m와 2.65 m를 이어 달았어요(겹친 곳 없음). 이은 밧줄은 모두 몇 m인가요?","options":[{"t":"4.9 m","correct":true},{"t":"4.8 m","mis":"M4-2-u3-X11"},{"t":"0.4 m","mis":"M4-2-u3-X16"},{"t":"0.49 m","mis":"M4-2-u3-X01"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","2.25 + 2.65 = 4.9 — 소수점을 맞추어 더해요.","4.9 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
