INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L07_basic#9','math',4,2,'u3','L07','g4_2_math_u3_L07_basic','lesson_basic','M4-2-u3-C6',2,'ox','auto','은비가 「1.51 + 2.5 = 3.01이야.」라고 했어요. 바르게 계산했어요.',ARRAY['M4-2-u3-X11']::text[],true,'{"seq":9,"concept":"M4-2-u3-C6","difficulty":2,"kind":"ox","stem":"은비가 「1.51 + 2.5 = 3.01이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더해야 해서","correct":true},{"t":"받아올림은 하지 않아도 되어서","mis":"M4-2-u3-X11"}],"mis":"M4-2-u3-X11","explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 2.5 = 2.50으로 보면 자리가 맞아요.","0.01이 151개 + 250개 = 401개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","1.51 + 2.5 = 4.01."],"variant_rule":{"alt":[{"stem":"건우가 「0.98 + 1.2 = 1.18이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"받아올림한 1을 윗자리에 더해야 해서","correct":true},{"t":"받아올림은 하지 않아도 되어서","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 1.2 = 1.20으로 보면 자리가 맞아요.","0.01이 98개 + 120개 = 218개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","0.98 + 1.2 = 2.18."],"asset":null},{"stem":"도연이 「4.52 + 4.7 = 9.22야.」라고 했어요. 바르게 계산했어요.","answer":"O","reason_options":[{"t":"소수점을 맞추어 같은 자리끼리 더하고 받아올림했어서","correct":true},{"t":"받아올림은 하지 않아도 되어서","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 4.7 = 4.70으로 보면 자리가 맞아요.","0.01이 452개 + 470개 = 922개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","4.52 + 4.7 = 9.22."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
