INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L07_challenge#1','math',4,2,'u3','L07','g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',2,'mc','auto','7.6 + 2.41은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X12']::text[],true,'{"seq":1,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"7.6 + 2.41은 얼마인가요?","options":[{"t":"10.01","correct":true},{"t":"9.01","mis":"M4-2-u3-X11"},{"t":"3.17","mis":"M4-2-u3-X12"},{"t":"0.01","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 7.6 = 7.60으로 보면 자리가 맞아요.","0.01이 760개 + 241개 = 1001개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","7.6 + 2.41 = 10.01."],"variant_rule":{"alt":[{"stem":"0.9 + 6.41은 얼마인가요?","options":[{"t":"7.31","correct":true},{"t":"6.31","mis":"M4-2-u3-X11"},{"t":"6.5","mis":"M4-2-u3-X12"},{"t":"5.51","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 0.9 = 0.90으로 보면 자리가 맞아요.","0.01이 90개 + 641개 = 731개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","0.9 + 6.41 = 7.31."],"asset":null},{"stem":"3.5 + 9.65는 얼마인가요?","options":[{"t":"13.15","correct":true},{"t":"2.15","mis":"M4-2-u3-X11"},{"t":"10","mis":"M4-2-u3-X12"},{"t":"12.15","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 3.5 = 3.50으로 보면 자리가 맞아요.","0.01이 350개 + 965개 = 1315개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","3.5 + 9.65 = 13.15."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L07_challenge#2','math',4,2,'u3','L07','g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',2,'mc','auto','사육사가 원숭이 놀이터에 밧줄 0.48 m와 0.6 m를 이어 달았어요(겹친 곳 없음). 이은 밧줄은 모두 몇 m인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X12','M4-2-u3-X16']::text[],true,'{"seq":2,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"사육사가 원숭이 놀이터에 밧줄 0.48 m와 0.6 m를 이어 달았어요(겹친 곳 없음). 이은 밧줄은 모두 몇 m인가요?","options":[{"t":"1.08 m","correct":true},{"t":"0.08 m","mis":"M4-2-u3-X11"},{"t":"0.54 m","mis":"M4-2-u3-X12"},{"t":"0.12 m","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","0.48 + 0.6 = 1.08 — 소수점을 맞추어 더해요.","1.08 m예요."],"variant_rule":{"alt":[{"stem":"수산 질병 관리사가 물이 1.58 L 들어 있는 수조에 물을 0.7 L 더 넣었어요. 수조의 물은 모두 몇 L인가요?","options":[{"t":"2.28 L","correct":true},{"t":"1.28 L","mis":"M4-2-u3-X11"},{"t":"1.65 L","mis":"M4-2-u3-X12"},{"t":"0.88 L","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","1.58 + 0.7 = 2.28 — 소수점을 맞추어 더해요.","2.28 L예요."],"asset":null},{"stem":"사육사가 원숭이 놀이터에 밧줄 6.45 m와 6.9 m를 이어 달았어요(겹친 곳 없음). 이은 밧줄은 모두 몇 m인가요?","options":[{"t":"13.35 m","correct":true},{"t":"2.35 m","mis":"M4-2-u3-X11"},{"t":"7.14 m","mis":"M4-2-u3-X12"},{"t":"12.35 m","mis":"M4-2-u3-X11"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","6.45 + 6.9 = 13.35 — 소수점을 맞추어 더해요.","13.35 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
