INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L07_challenge#7','math',4,2,'u3','L07','g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',3,'mc','auto','3.74 + 1.35 + 3.04는 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X20','M4-2-u3-X16']::text[],true,'{"seq":7,"concept":"M4-2-u3-C6","difficulty":3,"kind":"mc","stem":"3.74 + 1.35 + 3.04는 얼마인가요?","options":[{"t":"8.13","correct":true},{"t":"7.03","mis":"M4-2-u3-X11"},{"t":"5.09","mis":"M4-2-u3-X20"},{"t":"2.05","mis":"M4-2-u3-X16"}],"explanation":["앞에서부터 차례로 — 3.74 + 1.35 = 5.09.","5.09 + 3.04 = 8.13.","더할 때마다 소수점을 맞추어요."],"variant_rule":{"alt":[{"stem":"0.24 + 2.99 + 1.99는 얼마인가요?","options":[{"t":"5.22","correct":true},{"t":"3.02","mis":"M4-2-u3-X11"},{"t":"3.23","mis":"M4-2-u3-X20"},{"t":"1.24","mis":"M4-2-u3-X16"}],"explanation":["앞에서부터 차례로 — 0.24 + 2.99 = 3.23.","3.23 + 1.99 = 5.22.","더할 때마다 소수점을 맞추어요."],"asset":null},{"stem":"1.83 + 0.25 + 1.26은 얼마인가요?","options":[{"t":"3.34","correct":true},{"t":"2.24","mis":"M4-2-u3-X11"},{"t":"2.08","mis":"M4-2-u3-X20"},{"t":"0.82","mis":"M4-2-u3-X16"}],"explanation":["앞에서부터 차례로 — 1.83 + 0.25 = 2.08.","2.08 + 1.26 = 3.34.","더할 때마다 소수점을 맞추어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L07_challenge#8','math',4,2,'u3','L07','g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',4,'essay','teacher','건우는 5.1 + 4.26을 오른쪽 끝에 맞추어 써서 4.77이라고 답했어요. 왜 이런 답이 나왔는지 설명하고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C6","difficulty":4,"kind":"essay","stem":"건우는 5.1 + 4.26을 오른쪽 끝에 맞추어 써서 4.77이라고 답했어요. 왜 이런 답이 나왔는지 설명하고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: 오른쪽 끝을 맞추면 5.1의 1(소수 첫째 자리)이 4.26의 6(소수 둘째 자리)과 같은 칸에 놓여 자릿값이 다른 숫자끼리 더하게 된다. 소수점을 맞추어 5.10 + 4.26으로 쓰면 9.36이다.","scoring_points":["9.36이라고 바르게 계산했는가","자릿값이 다른 숫자끼리 더했다고 설명했는가","소수점을 맞추어야 한다고 썼는가"]},"explanation":["5.1 = 5.10.","소수점을 맞추어 더해요.","9.36."],"asset":{"type":"expr_grid","rows":[["","5",".","1",""],["+","4",".","2","6"],["","9",".","3","6"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L07_challenge#9','math',4,2,'u3','L07','g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',4,'essay','teacher','수산 질병 관리사가 물이 0.84 L 든 수조에 물을 0.3 L 더 넣었어요. 수조의 물의 양을 구하고, 0.3을 어느 자리에 맞추어 써야 하는지 까닭과 함께 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C6","difficulty":4,"kind":"essay","stem":"수산 질병 관리사가 물이 0.84 L 든 수조에 물을 0.3 L 더 넣었어요. 수조의 물의 양을 구하고, 0.3을 어느 자리에 맞추어 써야 하는지 까닭과 함께 설명해 보세요.","answer_guide":{"answer":"예: 0.3의 3은 소수 첫째 자리 숫자이므로 0.84의 8 아래에 맞추어 쓴다(0.3 = 0.30). 소수 첫째 자리에서 8 + 3 = 11이므로 1을 일의 자리로 받아올림하여 0.84 + 0.3 = 1.14 L이다.","scoring_points":["1.14 L라고 답했는가","0.3의 3을 소수 첫째 자리(8 아래)에 맞추었는가","받아올림을 바르게 했는가"]},"explanation":["0.3 = 0.30.","8 + 3 = 11 → 받아올림.","1.14 L."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L07_challenge#10','math',4,2,'u3','L07','g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',4,'mc','auto','9.8 + □ = 13.63일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X13','M4-2-u3-X14']::text[],true,'{"seq":10,"concept":"M4-2-u3-C6","difficulty":4,"kind":"mc","stem":"9.8 + □ = 13.63일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"3.83","correct":true},{"t":"23.43","mis":"M4-2-u3-X16"},{"t":"16.23","mis":"M4-2-u3-X13"},{"t":"14.83","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","13.63 − 9.8 = 3.83.","확인: 9.8 + 3.83 = 13.63."],"variant_rule":{"alt":[{"stem":"9.3 + □ = 13.19일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"3.89","correct":true},{"t":"22.49","mis":"M4-2-u3-X16"},{"t":"16.29","mis":"M4-2-u3-X13"},{"t":"14.89","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","13.19 − 9.3 = 3.89.","확인: 9.3 + 3.89 = 13.19."],"asset":null},{"stem":"4.9 + □ = 13.85일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"8.95","correct":true},{"t":"18.75","mis":"M4-2-u3-X16"},{"t":"11.15","mis":"M4-2-u3-X13"},{"t":"19.95","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","13.85 − 4.9 = 8.95.","확인: 4.9 + 8.95 = 13.85."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
