INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L08_basic#6','math',4,2,'u3','L08','g4_2_math_u3_L08_basic','lesson_basic','M4-2-u3-C7',2,'mc','auto','참외가 든 바구니의 무게는 3.7 kg이고 빈 바구니는 0.9 kg이에요. 참외만의 무게는 몇 kg인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],true,'{"seq":6,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"참외가 든 바구니의 무게는 3.7 kg이고 빈 바구니는 0.9 kg이에요. 참외만의 무게는 몇 kg인가요?","options":[{"t":"2.8 kg","correct":true},{"t":"3.2 kg","mis":"M4-2-u3-X13"},{"t":"3.8 kg","mis":"M4-2-u3-X14"},{"t":"4.6 kg","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","3.7 − 0.9 = 2.8 — 소수점을 맞추어 빼요.","2.8 kg이에요."],"variant_rule":{"alt":[{"stem":"수의사가 소독약 3.2 L 가운데 1.4 L를 썼어요. 남은 소독약은 몇 L인가요?","options":[{"t":"1.8 L","correct":true},{"t":"2.2 L","mis":"M4-2-u3-X13"},{"t":"2.8 L","mis":"M4-2-u3-X14"},{"t":"4.6 L","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","3.2 − 1.4 = 1.8 — 소수점을 맞추어 빼요.","1.8 L예요."],"asset":null},{"stem":"참외가 든 바구니의 무게는 4.2 kg이고 빈 바구니는 3.6 kg이에요. 참외만의 무게는 몇 kg인가요?","options":[{"t":"0.6 kg","correct":true},{"t":"1.4 kg","mis":"M4-2-u3-X13"},{"t":"1.6 kg","mis":"M4-2-u3-X14"},{"t":"7.8 kg","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","4.2 − 3.6 = 0.6 — 소수점을 맞추어 빼요.","0.6 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
