INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L08_challenge#2','math',4,2,'u3','L08','g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',2,'mc','auto','수의사가 소독약 6.1 L 가운데 5.9 L를 썼어요. 남은 소독약은 몇 L인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],true,'{"seq":2,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"수의사가 소독약 6.1 L 가운데 5.9 L를 썼어요. 남은 소독약은 몇 L인가요?","options":[{"t":"0.2 L","correct":true},{"t":"1.8 L","mis":"M4-2-u3-X13"},{"t":"1.2 L","mis":"M4-2-u3-X14"},{"t":"12 L","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","6.1 − 5.9 = 0.2 — 소수점을 맞추어 빼요.","0.2 L예요."],"variant_rule":{"alt":[{"stem":"참외가 든 바구니의 무게는 6.1 kg이고 빈 바구니는 4.2 kg이에요. 참외만의 무게는 몇 kg인가요?","options":[{"t":"1.9 kg","correct":true},{"t":"2.1 kg","mis":"M4-2-u3-X13"},{"t":"2.9 kg","mis":"M4-2-u3-X14"},{"t":"10.3 kg","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","6.1 − 4.2 = 1.9 — 소수점을 맞추어 빼요.","1.9 kg이에요."],"asset":null},{"stem":"수의사가 소독약 3.1 L 가운데 2.9 L를 썼어요. 남은 소독약은 몇 L인가요?","options":[{"t":"0.2 L","correct":true},{"t":"1.8 L","mis":"M4-2-u3-X13"},{"t":"1.2 L","mis":"M4-2-u3-X14"},{"t":"6 L","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","3.1 − 2.9 = 0.2 — 소수점을 맞추어 빼요.","0.2 L예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
