INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L08_challenge#4','math',4,2,'u3','L08','g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',3,'error','auto','친구들이 소수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X17']::text[],true,'{"seq":4,"concept":"M4-2-u3-C7","difficulty":3,"kind":"error","stem":"친구들이 소수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"건우 — 7.7 − 5.8 = 2.1","correct":true,"mis_target":"M4-2-u3-X13"},{"t":"지훈 — 4.2 − 2.3 = 1.9","mis":"M4-2-u3-X17"},{"t":"지유 — 8.1 − 6.9 = 1.2","mis":"M4-2-u3-X17"},{"t":"하윤 — 7.4 − 7.3 = 0.1","mis":"M4-2-u3-X17"}],"explanation":["소수점을 맞추어 같은 자리끼리 빼요.","7.7 − 5.8 = 1.9.","건우의 계산이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 친구들이 소수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은비 — 6.1 − 5.2 = 1.1","correct":true,"mis_target":"M4-2-u3-X13"},{"t":"도연 — 5.7 − 4.4 = 1.3","mis":"M4-2-u3-X17"},{"t":"준우 — 1.8 − 1.7 = 0.1","mis":"M4-2-u3-X17"},{"t":"하윤 — 7.7 − 5.5 = 2.2","mis":"M4-2-u3-X17"}],"explanation":["소수점을 맞추어 같은 자리끼리 빼요.","6.1 − 5.2 = 0.9.","은비의 계산이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 친구들이 소수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"준우 — 6.2 − 5.6 = 1.4","correct":true,"mis_target":"M4-2-u3-X13"},{"t":"민서 — 5.4 − 4.3 = 1.1","mis":"M4-2-u3-X17"},{"t":"지훈 — 6.4 − 3.8 = 2.6","mis":"M4-2-u3-X17"},{"t":"도연 — 9.3 − 5.8 = 3.5","mis":"M4-2-u3-X17"}],"explanation":["소수점을 맞추어 같은 자리끼리 빼요.","6.2 − 5.6 = 0.6.","준우의 계산이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L08_challenge#5','math',4,2,'u3','L08','g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',3,'sa','auto','세로셈의 ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u3-C7","difficulty":3,"kind":"sa","stem":"세로셈의 ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.1이 192개 − 145개 = 47개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.1이 10개).","19.2 − 14.5 = 4.7."],"asset":{"type":"expr_grid","rows":[["","1","9",".","2"],["−","1","4",".","5"],["","","4",".","?"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 세로셈의 ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.1이 198개 − 129개 = 69개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.1이 10개).","19.8 − 12.9 = 6.9."],"asset":{"type":"expr_grid","rows":[["","1","9",".","8"],["−","1","2",".","9"],["","","?",".","9"]]}},{"stem":"이번에는 다른 문제예요. 세로셈의 ?에 알맞은 숫자를 쓰세요.","answer":["9"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.1이 198개 − 79개 = 119개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.1이 10개).","19.8 − 7.9 = 11.9."],"asset":{"type":"expr_grid","rows":[["","1","9",".","8"],["−","","7",".","9"],["","1","1",".","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L08_challenge#6','math',4,2,'u3','L08','g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',3,'mc','auto','5.3 − 2.5 ○ 5.7 − 2.8 — ○ 안에 알맞은 것은 무엇인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X18']::text[],true,'{"seq":6,"concept":"M4-2-u3-C7","difficulty":3,"kind":"mc","stem":"5.3 − 2.5 ○ 5.7 − 2.8 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u3-X13"},{"t":"=","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["왼쪽 5.3 − 2.5 = 2.8.","오른쪽 5.7 − 2.8 = 2.9.","2.8 < 2.9."],"variant_rule":{"alt":[{"stem":"4.8 − 0.9 ○ 8.1 − 4.4 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u3-X13"},{"t":"=","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["왼쪽 4.8 − 0.9 = 3.9.","오른쪽 8.1 − 4.4 = 3.7.","3.9 > 3.7."],"asset":null},{"stem":"8.1 − 6.3 ○ 5.9 − 4.2 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u3-X13"},{"t":"=","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["왼쪽 8.1 − 6.3 = 1.8.","오른쪽 5.9 − 4.2 = 1.7.","1.8 > 1.7."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L08_challenge#7','math',4,2,'u3','L08','g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',3,'mc','auto','8.4 − 1.9를 계산해 7.5라고 썼어요. 바르게 고친 값은 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":7,"concept":"M4-2-u3-C7","difficulty":3,"kind":"mc","stem":"8.4 − 1.9를 계산해 7.5라고 썼어요. 바르게 고친 값은 얼마인가요?","options":[{"t":"6.5","correct":true},{"t":"7.5","mis":"M4-2-u3-X13"},{"t":"10.3","mis":"M4-2-u3-X16"},{"t":"0.65","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.1이 84개 − 19개 = 65개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.1이 10개).","8.4 − 1.9 = 6.5."],"variant_rule":{"alt":[{"stem":"4.5 − 3.6을 계산해 1.1이라고 썼어요. 바르게 고친 값은 얼마인가요?","options":[{"t":"0.9","correct":true},{"t":"1.1","mis":"M4-2-u3-X13"},{"t":"1.9","mis":"M4-2-u3-X14"},{"t":"8.1","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.1이 45개 − 36개 = 9개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.1이 10개).","4.5 − 3.6 = 0.9."],"asset":null},{"stem":"6.5 − 4.9를 계산해 2.4라고 썼어요. 바르게 고친 값은 얼마인가요?","options":[{"t":"1.6","correct":true},{"t":"2.4","mis":"M4-2-u3-X13"},{"t":"2.6","mis":"M4-2-u3-X14"},{"t":"11.4","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.1이 65개 − 49개 = 16개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.1이 10개).","6.5 − 4.9 = 1.6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L08_challenge#8','math',4,2,'u3','L08','g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',4,'essay','teacher','2.4 − 1.8을 세로로 계산할 때 받아내림을 하면 소수 첫째 자리의 4가 14가 돼요. 왜 14가 되는지 「0.1이 몇 개」로 설명하고 답을 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C7","difficulty":4,"kind":"essay","stem":"2.4 − 1.8을 세로로 계산할 때 받아내림을 하면 소수 첫째 자리의 4가 14가 돼요. 왜 14가 되는지 「0.1이 몇 개」로 설명하고 답을 구해 보세요.","answer_guide":{"answer":"예: 소수 첫째 자리에서 4에서 8을 뺄 수 없으므로 일의 자리에서 1을 받아내림한다. 1은 0.1이 10개이므로 0.1이 4개에 10개가 더해져 14개가 된다. 14 − 8 = 6, 일의 자리는 1 − 1 = 0이므로 0.6이다.","scoring_points":["0.6이라고 답했는가","1 = 0.1이 10개라고 썼는가","일의 자리에서 1을 뺐다고 썼는가"]},"explanation":["1 = 0.1이 10개.","14 − 8 = 6.","0.6."],"asset":{"type":"expr_grid","rows":[["","2",".","4"],["−","1",".","8"],["","?",".","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L08_challenge#9','math',4,2,'u3','L08','g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',4,'essay','teacher','참외가 든 바구니의 무게는 3.2 kg이고 빈 바구니는 0.3 kg이에요. 참외의 무게를 구하는 식을 쓰고, 덧셈이 아니라 뺄셈을 고른 까닭과 계산 과정을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C7","difficulty":4,"kind":"essay","stem":"참외가 든 바구니의 무게는 3.2 kg이고 빈 바구니는 0.3 kg이에요. 참외의 무게를 구하는 식을 쓰고, 덧셈이 아니라 뺄셈을 고른 까닭과 계산 과정을 써 보세요.","answer_guide":{"answer":"예: 참외의 무게 = 바구니째 무게 − 빈 바구니 무게이므로 3.2 − 0.3을 계산한다. 소수 첫째 자리에서 2에서 3을 뺄 수 없어 받아내림하면 12 − 3 = 9, 일의 자리 3 − 1 = 2이므로 2.9 kg이다.","scoring_points":["3.2 − 0.3이라는 식을 세웠는가","빈 바구니 무게를 덜어 낸다는 까닭을 썼는가","2.9 kg이라고 답했는가"]},"explanation":["바구니째 − 빈 바구니.","3.2 − 0.3 = 2.9.","2.9 kg."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L08_challenge#10','math',4,2,'u3','L08','g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',4,'mc','auto','□ − 5.8 = 11.6일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X11']::text[],true,'{"seq":10,"concept":"M4-2-u3-C7","difficulty":4,"kind":"mc","stem":"□ − 5.8 = 11.6일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"17.4","correct":true},{"t":"5.8","mis":"M4-2-u3-X16"},{"t":"16.4","mis":"M4-2-u3-X11"},{"t":"18.4","mis":"M4-2-u3-X11"}],"explanation":["□ − 5.8 = 11.6 — 덧셈으로 되돌려요.","□ = 17.4.","확인: 17.4 − 5.8 = 11.6."],"variant_rule":{"alt":[{"stem":"□ − 10.6 = 5.6일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"16.2","correct":true},{"t":"5","mis":"M4-2-u3-X16"},{"t":"15.2","mis":"M4-2-u3-X11"},{"t":"17.2","mis":"M4-2-u3-X11"}],"explanation":["□ − 10.6 = 5.6 — 덧셈으로 되돌려요.","□ = 16.2.","확인: 16.2 − 10.6 = 5.6."],"asset":null},{"stem":"□ − 8.8 = 4.5일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"13.3","correct":true},{"t":"4.3","mis":"M4-2-u3-X16"},{"t":"2.3","mis":"M4-2-u3-X11"},{"t":"14.3","mis":"M4-2-u3-X11"}],"explanation":["□ − 8.8 = 4.5 — 덧셈으로 되돌려요.","□ = 13.3.","확인: 13.3 − 8.8 = 4.5."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
