INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_basic#6','math',4,2,'u3','L09','g4_2_math_u3_L09_basic','lesson_basic','M4-2-u3-C8',2,'mc','auto','35.7 − 11.92를 세로로 계산하려고 해요. 가장 먼저 해야 할 일은 무엇인가요?',ARRAY['M4-2-u3-X12','M4-2-u3-X15']::text[],true,'{"seq":6,"concept":"M4-2-u3-C8","difficulty":2,"kind":"mc","stem":"35.7 − 11.92를 세로로 계산하려고 해요. 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"35.7을 35.70으로 보고 소수점의 위치를 맞추어 써요","correct":true},{"t":"오른쪽 끝을 맞추어 써요","mis":"M4-2-u3-X12"},{"t":"11.92를 11.9로 고쳐요","mis":"M4-2-u3-X15"},{"t":"자연수 부분만 먼저 빼요","mis":"M4-2-u3-X15"}],"explanation":["빼지는 수 35.7은 소수 둘째 자리가 비어 있어요.","35.7 = 35.70 — 끝자리에 0을 붙여도 크기는 같아요.","자리를 맞추면 받아내림이 필요한 자리가 보여요."],"variant_rule":{"alt":[{"stem":"38.1 − 27.23을 세로로 계산하려고 해요. 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"38.1을 38.10으로 보고 소수점의 위치를 맞추어 써요","correct":true},{"t":"오른쪽 끝을 맞추어 써요","mis":"M4-2-u3-X12"},{"t":"27.23을 27.2로 고쳐요","mis":"M4-2-u3-X15"},{"t":"자연수 부분만 먼저 빼요","mis":"M4-2-u3-X15"}],"explanation":["빼지는 수 38.1은 소수 둘째 자리가 비어 있어요.","38.1 = 38.10 — 끝자리에 0을 붙여도 크기는 같아요.","자리를 맞추면 받아내림이 필요한 자리가 보여요."],"asset":null},{"stem":"27.5 − 22.58을 세로로 계산하려고 해요. 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"27.5를 27.50으로 보고 소수점의 위치를 맞추어 써요","correct":true},{"t":"오른쪽 끝을 맞추어 써요","mis":"M4-2-u3-X12"},{"t":"22.58을 22.5로 고쳐요","mis":"M4-2-u3-X15"},{"t":"자연수 부분만 먼저 빼요","mis":"M4-2-u3-X15"}],"explanation":["빼지는 수 27.5는 소수 둘째 자리가 비어 있어요.","27.5 = 27.50 — 끝자리에 0을 붙여도 크기는 같아요.","자리를 맞추면 받아내림이 필요한 자리가 보여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_basic#7','math',4,2,'u3','L09','g4_2_math_u3_L09_basic','lesson_basic','M4-2-u3-C8',2,'mc','auto','재활 중인 참수리가 오늘은 2.46 m, 어제는 1.67 m를 날아올랐어요. 오늘은 어제보다 몇 m 더 높이 날아올랐나요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],true,'{"seq":7,"concept":"M4-2-u3-C8","difficulty":2,"kind":"mc","stem":"재활 중인 참수리가 오늘은 2.46 m, 어제는 1.67 m를 날아올랐어요. 오늘은 어제보다 몇 m 더 높이 날아올랐나요?","options":[{"t":"0.79 m","correct":true},{"t":"1.21 m","mis":"M4-2-u3-X13"},{"t":"1.89 m","mis":"M4-2-u3-X14"},{"t":"4.13 m","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","2.46 − 1.67 = 0.79 — 소수점을 맞추어 빼요.","0.79 m예요."],"variant_rule":{"alt":[{"stem":"동물 보건사가 사료 3.74 kg 가운데 0.89 kg을 덜어 주었어요. 남은 사료는 몇 kg인가요?","options":[{"t":"2.85 kg","correct":true},{"t":"3.15 kg","mis":"M4-2-u3-X13"},{"t":"3.95 kg","mis":"M4-2-u3-X14"},{"t":"4.63 kg","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","3.74 − 0.89 = 2.85 — 소수점을 맞추어 빼요.","2.85 kg이에요."],"asset":null},{"stem":"재활 중인 참수리가 오늘은 3.25 m, 어제는 0.07 m를 날아올랐어요. 오늘은 어제보다 몇 m 더 높이 날아올랐나요?","options":[{"t":"3.18 m","correct":true},{"t":"3.22 m","mis":"M4-2-u3-X13"},{"t":"3.28 m","mis":"M4-2-u3-X14"},{"t":"3.32 m","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","3.25 − 0.07 = 3.18 — 소수점을 맞추어 빼요.","3.18 m예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
