INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_basic#10','math',4,2,'u3','L09','g4_2_math_u3_L09_basic','lesson_basic','M4-2-u3-C8',3,'mc','auto','4.11 − □ = 1.4일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X13','M4-2-u3-X14']::text[],true,'{"seq":10,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"4.11 − □ = 1.4일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"2.71","correct":true},{"t":"5.51","mis":"M4-2-u3-X16"},{"t":"3.31","mis":"M4-2-u3-X13"},{"t":"3.71","mis":"M4-2-u3-X14"}],"explanation":["4.11에서 □를 빼서 1.4 — □ = 4.11 − 1.4.","□ = 2.71.","확인: 4.11 − 2.71 = 1.4."],"variant_rule":{"alt":[{"stem":"8.18 − □ = 1.94일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"6.24","correct":true},{"t":"10.12","mis":"M4-2-u3-X16"},{"t":"7.84","mis":"M4-2-u3-X13"},{"t":"7.24","mis":"M4-2-u3-X14"}],"explanation":["8.18에서 □를 빼서 1.94 — □ = 8.18 − 1.94.","□ = 6.24.","확인: 8.18 − 6.24 = 1.94."],"asset":null},{"stem":"4.46 − □ = 2.65일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"1.81","correct":true},{"t":"7.11","mis":"M4-2-u3-X16"},{"t":"2.21","mis":"M4-2-u3-X13"},{"t":"2.81","mis":"M4-2-u3-X14"}],"explanation":["4.46에서 □를 빼서 2.65 — □ = 4.46 − 2.65.","□ = 1.81.","확인: 4.46 − 1.81 = 2.65."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_challenge#1','math',4,2,'u3','L09','g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',2,'mc','auto','7.1 − 2.99는 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X15']::text[],true,'{"seq":1,"concept":"M4-2-u3-C8","difficulty":2,"kind":"mc","stem":"7.1 − 2.99는 얼마인가요?","options":[{"t":"4.11","correct":true},{"t":"5.89","mis":"M4-2-u3-X13"},{"t":"5.21","mis":"M4-2-u3-X14"},{"t":"4.29","mis":"M4-2-u3-X15"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요 — 7.1을 7.10으로 보면 빈 자리가 0이에요.","0.01이 710개 − 299개 = 411개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","7.1 − 2.99 = 4.11."],"variant_rule":{"alt":[{"stem":"8.6 − 2.84는 얼마인가요?","options":[{"t":"5.76","correct":true},{"t":"6.24","mis":"M4-2-u3-X13"},{"t":"6.86","mis":"M4-2-u3-X14"},{"t":"5.84","mis":"M4-2-u3-X15"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요 — 8.6을 8.60으로 보면 빈 자리가 0이에요.","0.01이 860개 − 284개 = 576개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","8.6 − 2.84 = 5.76."],"asset":null},{"stem":"6.8 − 5.15는 얼마인가요?","options":[{"t":"1.65","correct":true},{"t":"1.75","mis":"M4-2-u3-X13"},{"t":"11.95","mis":"M4-2-u3-X16"},{"t":"16.5","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요 — 6.8을 6.80으로 보면 빈 자리가 0이에요.","0.01이 680개 − 515개 = 165개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","6.8 − 5.15 = 1.65."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_challenge#2','math',4,2,'u3','L09','g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',2,'mc','auto','동물 보건사가 사료 4.8 kg 가운데 1.01 kg을 덜어 주었어요. 남은 사료는 몇 kg인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],true,'{"seq":2,"concept":"M4-2-u3-C8","difficulty":2,"kind":"mc","stem":"동물 보건사가 사료 4.8 kg 가운데 1.01 kg을 덜어 주었어요. 남은 사료는 몇 kg인가요?","options":[{"t":"3.79 kg","correct":true},{"t":"3.81 kg","mis":"M4-2-u3-X13"},{"t":"3.89 kg","mis":"M4-2-u3-X14"},{"t":"5.81 kg","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","4.8 − 1.01 = 3.79 — 소수점을 맞추어 빼요.","3.79 kg이에요."],"variant_rule":{"alt":[{"stem":"재활 중인 참수리가 오늘은 2.3 m, 어제는 1.23 m를 날아올랐어요. 오늘은 어제보다 몇 m 더 높이 날아올랐나요?","options":[{"t":"1.07 m","correct":true},{"t":"1.13 m","mis":"M4-2-u3-X13"},{"t":"1.17 m","mis":"M4-2-u3-X14"},{"t":"3.53 m","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","2.3 − 1.23 = 1.07 — 소수점을 맞추어 빼요.","1.07 m예요."],"asset":null},{"stem":"동물 보건사가 사료 1.7 kg 가운데 1.58 kg을 덜어 주었어요. 남은 사료는 몇 kg인가요?","options":[{"t":"0.12 kg","correct":true},{"t":"0.28 kg","mis":"M4-2-u3-X13"},{"t":"0.22 kg","mis":"M4-2-u3-X14"},{"t":"3.28 kg","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","1.7 − 1.58 = 0.12 — 소수점을 맞추어 빼요.","0.12 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
