INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_challenge#4','math',4,2,'u3','L09','g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',3,'error','auto','친구들이 소수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-2-u3-X14','M4-2-u3-X17']::text[],true,'{"seq":4,"concept":"M4-2-u3-C8","difficulty":3,"kind":"error","stem":"친구들이 소수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도연 — 9.37 − 3.38 = 6.09","correct":true,"mis_target":"M4-2-u3-X14"},{"t":"서준 — 5.21 − 3.53 = 1.68","mis":"M4-2-u3-X17"},{"t":"지훈 — 6.67 − 1.42 = 5.25","mis":"M4-2-u3-X17"},{"t":"은비 — 5.83 − 0.72 = 5.11","mis":"M4-2-u3-X17"}],"explanation":["소수점을 맞추어 같은 자리끼리 빼요.","9.37 − 3.38 = 5.99.","도연의 계산이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 친구들이 소수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"채원 — 6.62 − 6.28 = 0.44","correct":true,"mis_target":"M4-2-u3-X14"},{"t":"지훈 — 8.63 − 4.01 = 4.62","mis":"M4-2-u3-X17"},{"t":"지유 — 3.48 − 2.45 = 1.03","mis":"M4-2-u3-X17"},{"t":"서준 — 2.93 − 0.19 = 2.74","mis":"M4-2-u3-X17"}],"explanation":["소수점을 맞추어 같은 자리끼리 빼요.","6.62 − 6.28 = 0.34.","채원의 계산이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 친구들이 소수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"서준 — 6.58 − 0.68 = 6.9","correct":true,"mis_target":"M4-2-u3-X14"},{"t":"은비 — 4.98 − 3.37 = 1.61","mis":"M4-2-u3-X17"},{"t":"지훈 — 7.17 − 1.78 = 5.39","mis":"M4-2-u3-X17"},{"t":"도연 — 8.83 − 8.29 = 0.54","mis":"M4-2-u3-X17"}],"explanation":["소수점을 맞추어 같은 자리끼리 빼요.","6.58 − 0.68 = 5.9.","서준의 계산이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_challenge#5','math',4,2,'u3','L09','g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',3,'sa','auto','세로셈의 ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u3-C8","difficulty":3,"kind":"sa","stem":"세로셈의 ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.01이 547개 − 186개 = 361개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","5.47 − 1.86 = 3.61."],"asset":{"type":"expr_grid","rows":[["","5",".","4","7"],["−","1",".","8","6"],["","3",".","?","1"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 세로셈의 ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.01이 875개 − 798개 = 77개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","8.75 − 7.98 = 0.77."],"asset":{"type":"expr_grid","rows":[["","8",".","7","5"],["−","7",".","9","8"],["","0",".","7","?"]]}},{"stem":"이번에는 다른 문제예요. 세로셈의 ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.01이 945개 − 293개 = 652개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","9.45 − 2.93 = 6.52."],"asset":{"type":"expr_grid","rows":[["","9",".","4","5"],["−","2",".","9","3"],["","?",".","5","2"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_challenge#6','math',4,2,'u3','L09','g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',3,'mc','auto','8.39 − 0.5를 계산해 8.34라고 썼어요. 바르게 고친 값은 얼마인가요?',ARRAY['M4-2-u3-X12','M4-2-u3-X13','M4-2-u3-X14']::text[],true,'{"seq":6,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"8.39 − 0.5를 계산해 8.34라고 썼어요. 바르게 고친 값은 얼마인가요?","options":[{"t":"7.89","correct":true},{"t":"8.34","mis":"M4-2-u3-X12"},{"t":"8.29","mis":"M4-2-u3-X13"},{"t":"8.89","mis":"M4-2-u3-X14"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요 — 빼는 수 0.5 = 0.50.","0.01이 839개 − 50개 = 789개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","8.39 − 0.5 = 7.89."],"variant_rule":{"alt":[{"stem":"7.13 − 5.3을 계산해 6.6이라고 썼어요. 바르게 고친 값은 얼마인가요?","options":[{"t":"1.83","correct":true},{"t":"6.6","mis":"M4-2-u3-X12"},{"t":"2.23","mis":"M4-2-u3-X13"},{"t":"2.83","mis":"M4-2-u3-X14"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요 — 빼는 수 5.3 = 5.30.","0.01이 713개 − 530개 = 183개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","7.13 − 5.3 = 1.83."],"asset":null},{"stem":"7.09 − 3.6을 계산해 6.73이라고 썼어요. 바르게 고친 값은 얼마인가요?","options":[{"t":"3.49","correct":true},{"t":"6.73","mis":"M4-2-u3-X12"},{"t":"4.69","mis":"M4-2-u3-X13"},{"t":"4.49","mis":"M4-2-u3-X14"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요 — 빼는 수 3.6 = 3.60.","0.01이 709개 − 360개 = 349개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","7.09 − 3.6 = 3.49."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_challenge#7','math',4,2,'u3','L09','g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',3,'mc','auto','□ − 5.78 = 1.82일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X11']::text[],true,'{"seq":7,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"□ − 5.78 = 1.82일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"7.6","correct":true},{"t":"3.96","mis":"M4-2-u3-X16"},{"t":"6.5","mis":"M4-2-u3-X11"},{"t":"7.7","mis":"M4-2-u3-X11"}],"explanation":["□ − 5.78 = 1.82 — 덧셈으로 되돌려요.","□ = 7.6.","확인: 7.6 − 5.78 = 1.82."],"variant_rule":{"alt":[{"stem":"□ − 0.77 = 4.33일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"5.1","correct":true},{"t":"3.56","mis":"M4-2-u3-X16"},{"t":"4","mis":"M4-2-u3-X11"},{"t":"5.2","mis":"M4-2-u3-X11"}],"explanation":["□ − 0.77 = 4.33 — 덧셈으로 되돌려요.","□ = 5.1.","확인: 5.1 − 0.77 = 4.33."],"asset":null},{"stem":"□ − 8.05 = 0.25일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"8.3","correct":true},{"t":"7.8","mis":"M4-2-u3-X16"},{"t":"8.2","mis":"M4-2-u3-X11"},{"t":"8.4","mis":"M4-2-u3-X11"}],"explanation":["□ − 8.05 = 0.25 — 덧셈으로 되돌려요.","□ = 8.3.","확인: 8.3 − 8.05 = 0.25."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_challenge#8','math',4,2,'u3','L09','g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',4,'essay','teacher','35.7 − 11.92를 계산하려고 해요. 35.7을 35.70으로 보면 무엇이 좋은지 설명하고, 받아내림 과정을 써서 답을 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C8","difficulty":4,"kind":"essay","stem":"35.7 − 11.92를 계산하려고 해요. 35.7을 35.70으로 보면 무엇이 좋은지 설명하고, 받아내림 과정을 써서 답을 구해 보세요.","answer_guide":{"answer":"예: 35.70으로 보면 소수 둘째 자리가 0이 되어 두 수의 자리가 딱 맞고, 0에서 2를 뺄 수 없어 받아내림이 필요하다는 것이 보인다. 끝자리 0은 크기를 바꾸지 않는다. 소수 둘째 자리 10 − 2 = 8, 소수 첫째 자리 6 − 9를 할 수 없어 받아내림하여 16 − 9 = 7, 일의 자리 4 − 1 = 3, 십의 자리 3 − 1 = 2 — 23.78이다.","scoring_points":["23.78이라고 답했는가","35.70으로 보면 자리가 맞는다고 썼는가","두 번 받아내림한 과정을 썼는가"]},"explanation":["35.7 = 35.70.","받아내림 두 번.","23.78."],"asset":{"type":"expr_grid","rows":[["","3","5",".","7",""],["−","1","1",".","9","2"],["","?","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_challenge#9','math',4,2,'u3','L09','g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',4,'essay','teacher','도연이는 1.2 − 0.36을 0.96이라고 계산했어요. 도연이가 무엇을 잘못했는지 찾아 설명하고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C8","difficulty":4,"kind":"essay","stem":"도연이는 1.2 − 0.36을 0.96이라고 계산했어요. 도연이가 무엇을 잘못했는지 찾아 설명하고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 1.2의 소수 둘째 자리가 비어 있는데 도연이는 그 자리를 0으로 보지 않고 빼는 수의 6을 그대로 내려 썼다. 1.2 = 1.20으로 보고 0에서 6을 뺄 수 없으므로 받아내림하면 10 − 6 = 4, 소수 첫째 자리 11 − 3 = 8, 일의 자리 0 — 0.84이다.","scoring_points":["0.84라고 답했는가","빈 자리를 0으로 보지 않은 잘못을 짚었는가","1.2 = 1.20으로 보고 받아내림했는가"]},"explanation":["1.2 = 1.20.","빈 자리는 0.","0.84."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L09_challenge#10','math',4,2,'u3','L09','g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',4,'mc','auto','6.7 − □ = 5.48일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X13','M4-2-u3-X14']::text[],true,'{"seq":10,"concept":"M4-2-u3-C8","difficulty":4,"kind":"mc","stem":"6.7 − □ = 5.48일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"1.22","correct":true},{"t":"12.18","mis":"M4-2-u3-X16"},{"t":"1.38","mis":"M4-2-u3-X13"},{"t":"1.32","mis":"M4-2-u3-X14"}],"explanation":["6.7에서 □를 빼서 5.48 — □ = 6.7 − 5.48.","□ = 1.22.","확인: 6.7 − 1.22 = 5.48."],"variant_rule":{"alt":[{"stem":"9.7 − □ = 0.21일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"9.49","correct":true},{"t":"9.91","mis":"M4-2-u3-X16"},{"t":"9.51","mis":"M4-2-u3-X13"},{"t":"9.59","mis":"M4-2-u3-X14"}],"explanation":["9.7에서 □를 빼서 0.21 — □ = 9.7 − 0.21.","□ = 9.49.","확인: 9.7 − 9.49 = 0.21."],"asset":null},{"stem":"9.8 − □ = 5.02일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"4.78","correct":true},{"t":"14.82","mis":"M4-2-u3-X16"},{"t":"4.82","mis":"M4-2-u3-X13"},{"t":"4.88","mis":"M4-2-u3-X14"}],"explanation":["9.8에서 □를 빼서 5.02 — □ = 9.8 − 5.02.","□ = 4.78.","확인: 9.8 − 4.78 = 5.02."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_basic#1','math',4,2,'u3','L10','g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',1,'mc','auto','혼계영 200 m에서 돌고래 팀의 기록은 148.89초, 아기 상어 팀의 기록은 150.21초예요. 더 빠른 팀은 어느 팀인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X18']::text[],true,'{"seq":1,"concept":"M4-2-u3-C9","difficulty":1,"kind":"mc","stem":"혼계영 200 m에서 돌고래 팀의 기록은 148.89초, 아기 상어 팀의 기록은 150.21초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"돌고래 팀","correct":true},{"t":"아기 상어 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","148.89 < 150.21.","더 빠른 팀은 돌고래 팀이에요."],"variant_rule":{"alt":[{"stem":"혼계영 200 m에서 수달 팀의 기록은 153.67초, 펭귄 팀의 기록은 149.87초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"펭귄 팀","correct":true},{"t":"수달 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","153.67 > 149.87.","더 빠른 팀은 펭귄 팀이에요."],"asset":null},{"stem":"혼계영 200 m에서 바다거북 팀의 기록은 145.23초, 물개 팀의 기록은 145.84초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"바다거북 팀","correct":true},{"t":"물개 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","145.23 < 145.84.","더 빠른 팀은 바다거북 팀이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_basic#2','math',4,2,'u3','L10','g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',1,'sa','auto','돌고래 팀의 기록은 148.89초, 아기 상어 팀의 기록은 150.21초예요. 두 팀 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u3-C9","difficulty":1,"kind":"sa","stem":"돌고래 팀의 기록은 148.89초, 아기 상어 팀의 기록은 150.21초예요. 두 팀 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["132"],"explanation":["큰 기록에서 작은 기록을 빼요.","150.21 − 148.89 = 1.32.","1.32는 0.01이 132개예요."],"asset":{"type":"expr_grid","rows":[["","1","5","0",".","2","1"],["−","1","4","8",".","8","9"],["","","","?",".","?","?"]]},"variant_rule":{"alt":[{"stem":"수달 팀의 기록은 153.92초, 펭귄 팀의 기록은 150.16초예요. 두 팀 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["376"],"explanation":["큰 기록에서 작은 기록을 빼요.","153.92 − 150.16 = 3.76.","3.76은 0.01이 376개예요."],"asset":{"type":"expr_grid","rows":[["","1","5","3",".","9","2"],["−","1","5","0",".","1","6"],["","","","?",".","?","?"]]}},{"stem":"바다거북 팀의 기록은 151.16초, 물개 팀의 기록은 147.36초예요. 두 팀 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["380"],"explanation":["큰 기록에서 작은 기록을 빼요.","151.16 − 147.36 = 3.8.","3.8은 0.01이 380개예요."],"asset":{"type":"expr_grid","rows":[["","1","5","1",".","1","6"],["−","1","4","7",".","3","6"],["","","","?",".","?","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_basic#3','math',4,2,'u3','L10','g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C10',1,'mc','auto','혼계영 선수들의 영법별 기록표예요(단위: 초). 평영에서 기록이 가장 빠른 선수는 누구인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X18']::text[],true,'{"seq":3,"concept":"M4-2-u3-C10","difficulty":1,"kind":"mc","stem":"혼계영 선수들의 영법별 기록표예요(단위: 초). 평영에서 기록이 가장 빠른 선수는 누구인가요?","options":[{"t":"채원","correct":true},{"t":"지유","mis":"M4-2-u3-X17"},{"t":"서준","mis":"M4-2-u3-X18"},{"t":"건우","mis":"M4-2-u3-X17"}],"explanation":["기록은 작을수록 빠른 거예요.","평영 기록 — 서준 36.51초, 지유 39.59초, 채원 34.32초, 건우 36.97초.","가장 작은 기록은 채원의 34.32초."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","33.11","36.51","39.14","33.78"],["지유","35.00","39.59","39.65","35.90"],["채원","35.33","34.32","35.64","34.47"],["건우","38.67","36.97","39.20","36.31"]]},"variant_rule":{"alt":[{"stem":"혼계영 선수들의 영법별 기록표예요(단위: 초). 자유형에서 기록이 가장 빠른 선수는 누구인가요?","options":[{"t":"건우","correct":true},{"t":"지유","mis":"M4-2-u3-X17"},{"t":"서준","mis":"M4-2-u3-X18"},{"t":"채원","mis":"M4-2-u3-X17"}],"explanation":["기록은 작을수록 빠른 거예요.","자유형 기록 — 서준 37.23초, 지유 39.83초, 채원 37.35초, 건우 34.86초.","가장 작은 기록은 건우의 34.86초."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.52","35.79","36.13","37.23"],["지유","34.98","34.17","35.50","39.83"],["채원","39.05","37.02","39.47","37.35"],["건우","39.95","38.89","36.54","34.86"]]}},{"stem":"이번에는 다른 문제예요. 혼계영 선수들의 영법별 기록표예요(단위: 초). 평영에서 기록이 가장 빠른 선수는 누구인가요?","options":[{"t":"채원","correct":true},{"t":"서준","mis":"M4-2-u3-X17"},{"t":"건우","mis":"M4-2-u3-X18"},{"t":"지유","mis":"M4-2-u3-X17"}],"explanation":["기록은 작을수록 빠른 거예요.","평영 기록 — 서준 37.98초, 지유 37.90초, 채원 35.21초, 건우 35.29초.","가장 작은 기록은 채원의 35.21초."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","36.17","37.98","34.68","33.61"],["지유","34.44","37.9