INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_basic#5','math',4,2,'u3','L10','g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',2,'mc','auto','채원 선수가 혼자 배영·평영·접영·자유형을 모두 헤엄쳤어요. 영법별 기록이 37.19초, 35.24초, 36.33초, 34.70초일 때 네 기록의 합은 몇 초인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X20']::text[],true,'{"seq":5,"concept":"M4-2-u3-C9","difficulty":2,"kind":"mc","stem":"채원 선수가 혼자 배영·평영·접영·자유형을 모두 헤엄쳤어요. 영법별 기록이 37.19초, 35.24초, 36.33초, 34.70초일 때 네 기록의 합은 몇 초인가요?","options":[{"t":"143.46초","correct":true},{"t":"22.36초","mis":"M4-2-u3-X11"},{"t":"108.76초","mis":"M4-2-u3-X20"},{"t":"142.46초","mis":"M4-2-u3-X11"}],"explanation":["앞에서부터 차례로 더해요 — 37.19 + 35.24 = 72.43.","72.43 + 36.33 = 108.76, 108.76 + 34.70 = 143.46.","더할 때마다 소수점을 맞추어요."],"variant_rule":{"alt":[{"stem":"지유 선수가 혼자 배영·평영·접영·자유형을 모두 헤엄쳤어요. 영법별 기록이 37.08초, 37.15초, 39.65초, 38.43초일 때 네 기록의 합은 몇 초인가요?","options":[{"t":"152.31초","correct":true},{"t":"21.11초","mis":"M4-2-u3-X11"},{"t":"113.88초","mis":"M4-2-u3-X20"},{"t":"151.31초","mis":"M4-2-u3-X11"}],"explanation":["앞에서부터 차례로 더해요 — 37.08 + 37.15 = 74.23.","74.23 + 39.65 = 113.88, 113.88 + 38.43 = 152.31.","더할 때마다 소수점을 맞추어요."],"asset":null},{"stem":"지유 선수가 혼자 배영·평영·접영·자유형을 모두 헤엄쳤어요. 영법별 기록이 33.15초, 39.89초, 38.62초, 38.18초일 때 네 기록의 합은 몇 초인가요?","options":[{"t":"149.84초","correct":true},{"t":"28.64초","mis":"M4-2-u3-X11"},{"t":"111.66초","mis":"M4-2-u3-X20"},{"t":"148.84초","mis":"M4-2-u3-X11"}],"explanation":["앞에서부터 차례로 더해요 — 33.15 + 39.89 = 73.04.","73.04 + 38.62 = 111.66, 111.66 + 38.18 = 149.84.","더할 때마다 소수점을 맞추어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_