INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_basic#6','math',4,2,'u3','L10','g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',2,'sa','auto','개인 혼영에서 채원의 기록은 176.89초, 준우의 기록은 175.69초예요. 두 사람의 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u3-C9","difficulty":2,"kind":"sa","stem":"개인 혼영에서 채원의 기록은 176.89초, 준우의 기록은 175.69초예요. 두 사람의 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["큰 기록에서 작은 기록을 빼요 — 소수점을 맞추어요.","176.89 − 175.69 = 1.2.","1.2는 0.01이 120개 — 준우가 더 빨라요."],"variant_rule":{"alt":[{"stem":"개인 혼영에서 준우의 기록은 175.32초, 서윤의 기록은 173.58초예요. 두 사람의 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["174"],"explanation":["큰 기록에서 작은 기록을 빼요 — 소수점을 맞추어요.","175.32 − 173.58 = 1.74.","1.74는 0.01이 174개 — 서윤이 더 빨라요."],"asset":null},{"stem":"개인 혼영에서 서준의 기록은 176.01초, 하윤의 기록은 174.21초예요. 두 사람의 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["큰 기록에서 작은 기록을 빼요 — 소수점을 맞추어요.","176.01 − 174.21 = 1.8.","1.8은 0.01이 180개 — 하윤이 더 빨라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_basic#7','math',4,2,'u3','L10','g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',2,'mc','auto','하윤의 지난주 자유형 50 m 기록은 49.29초였어요. 이번 주에는 2.33초를 줄였어요. 이번 주 기록은 몇 초인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],true,'{"seq":7,"concept":"M4-2-u3-C9","difficulty":2,"kind":"mc","stem":"하윤의 지난주 자유형 50 m 기록은 49.29초였어요. 이번 주에는 2.33초를 줄였어요. 이번 주 기록은 몇 초인가요?","options":[{"t":"46.96초","correct":true},{"t":"47.16초","mis":"M4-2-u3-X13"},{"t":"47.96초","mis":"M4-2-u3-X14"},{"t":"51.62초","mis":"M4-2-u3-X16"}],"explanation":["기록을 「줄였다」는 덜어 내는 뺄셈이에요.","49.29 − 2.33 = 46.96.","이번 주 기록은 46.96초예요."],"variant_rule":{"alt":[{"stem":"서윤의 지난주 자유형 50 m 기록은 41.79초였어요. 이번 주에는 0.83초를 줄였어요. 이번 주 기록은 몇 초인가요?","options":[{"t":"40.96초","correct":true},{"t":"41.16초","mis":"M4-2-u3-X13"},{"t":"41.96초","mis":"M4-2-u3-X14"},{"t":"42.62초","mis":"M4-2-u3-X16"}],"explanation":["기록을 「줄였다」는 덜어 내는 뺄셈이에요.","41.79 − 0.83 = 40.96.","이번 주 기록은 40.96초예요."],"asset":null},{"stem":"채원의 지난주 자유형 50 m 기록은 44.15초였어요. 이번 주에는 0.92초를 줄였어요. 이번 주 기록은 몇 초인가요?","options":[{"t":"43.23초","correct":true},{"t":"44.83초","mis":"M4-2-u3-X13"},{"t":"44.23초","mis":"M4-2-u3-X14"},{"t":"45.07초","mis":"M4-2-u3-X16"}],"explanation":["기록을 「줄였다」는 덜어 내는 뺄셈이에요.","44.15 − 0.92 = 43.23.","이번 주 기록은 43.23초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_basic#8','math',4,2,'u3','L10','g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',2,'ox','auto','준우가 「수달 팀 기록이 더 큰 수니까 수달 팀이 더 빨라.」라고 했어요. 바르게 말했어요.',ARRAY['M4-2-u3-X17']::text[],true,'{"seq":8,"concept":"M4-2-u3-C9","difficulty":2,"kind":"ox","stem":"준우가 「수달 팀 기록이 더 큰 수니까 수달 팀이 더 빨라.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"기록은 걸린 시간이라 작을수록 빨라서","correct":true},{"t":"큰 수일수록 빠른 기록이라서","mis":"M4-2-u3-X17"}],"mis":"M4-2-u3-X17","explanation":["수달 팀 148.81초, 펭귄 팀 145.24초.","기록은 작을수록 빨라요.","수달 팀이 더 느려요 — 준우의 말은 틀렸어요 ×."],"variant_rule":{"alt":[{"stem":"서윤이 「수달 팀 기록이 더 큰 수니까 수달 팀이 더 빨라.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"기록은 걸린 시간이라 작을수록 빨라서","correct":true},{"t":"큰 수일수록 빠른 기록이라서","mis":"M4-2-u3-X17"}],"explanation":["수달 팀 148.98초, 펭귄 팀 147.16초.","기록은 작을수록 빨라요.","수달 팀이 더 느려요 — 서윤의 말은 틀렸어요 ×."],"asset":null},{"stem":"은비가 「물개 팀 기록이 더 큰 수니까 물개 팀이 더 빨라.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"기록은 걸린 시간이라 작을수록 빨라서","correct":true},{"t":"큰 수일수록 빠른 기록이라서","mis":"M4-2-u3-X17"}],"explanation":["바다거북 팀 148.69초, 물개 팀 150.73초.","기록은 작을수록 빨라요.","물개 팀이 더 느려요 — 은비의 말은 틀렸어요 ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
