INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_challenge#3','math',4,2,'u3','L10','g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C10',3,'mc','auto','한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?',ARRAY['M4-2-u3-X19','M4-2-u3-X17','M4-2-u3-X18']::text[],true,'{"seq":3,"concept":"M4-2-u3-C10","difficulty":3,"kind":"mc","stem":"한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배영 채원 · 평영 서준 · 접영 지유 · 자유형 건우","correct":true},{"t":"배영 채원 · 평영 채원 · 접영 서준 · 자유형 건우","mis":"M4-2-u3-X19"},{"t":"배영 서준 · 평영 지유 · 접영 건우 · 자유형 채원","mis":"M4-2-u3-X17"},{"t":"배영 지유 · 평영 채원 · 접영 서준 · 자유형 건우","mis":"M4-2-u3-X18"}],"explanation":["영법마다 가장 빠른 선수만 고르면 채원이 두 영법을 맡게 되어 안 돼요.","겹치는 영법은 두 번째로 빠른 선수와 짝지어 합을 견주어요.","가장 작은 합은 137.98초 — 배영 채원 · 평영 서준 · 접영 지유 · 자유형 건우."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","37.57","34.71","34.42","36.76"],["지유","39.45","39.93","36.38","39.43"],["채원","33.75","33.23","34.61","38.42"],["건우","34.95","34.53","37.54","33.14"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배영 지유 · 평영 건우 · 접영 서준 · 자유형 채원","correct":true},{"t":"배영 건우 · 평영 건우 · 접영 서준 · 자유형 채원","mis":"M4-2-u3-X19"},{"t":"배영 서준 · 평영 채원 · 접영 건우 · 자유형 지유","mis":"M4-2-u3-X17"},{"t":"배영 지유 · 평영 건우 · 접영 채원 · 자유형 서준","mis":"M4-2-u3-X18"}],"explanation":["영법마다 가장 빠른 선수만 고르면 건우가 두 영법을 맡게 되어 안 돼요.","겹치는 영법은 두 번째로 빠른 선수와 짝지어 합을 견주어요.","가장 작은 합은 143.97초 — 배영 지유 · 평영 건우 · 접영 서준 · 자유형 채원."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","36.38","38.40","35.16","37.78"],["지유","34.61","39.87","36.26","39.67"],["채원","34.68","38.03","35.89","37.57"],["건우","34.16","36.63","39.43","37.90"]]}},{"stem":"이번에는 다른 문제예요. 한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배