INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_challenge#4','math',4,2,'u3','L10','g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C10',3,'sa','auto','한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 135.28초예요. 예선 통과 기준 136초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u3-C10","difficulty":3,"kind":"sa","stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 135.28초예요. 예선 통과 기준 136초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["72"],"explanation":["기준에서 우리 기록을 빼요.","136 − 135.28 = 0.72.","0.72는 0.01이 72개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","36.15","39.81","33.11","35.72"],["지유","36.28","35.61","39.09","33.94"],["채원","37.09","34.83","33.10","36.23"],["건우","33.40","34.38","35.72","37.70"]]},"variant_rule":{"alt":[{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 137.11초예요. 예선 통과 기준 139초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["189"],"explanation":["기준에서 우리 기록을 빼요.","139 − 137.11 = 1.89.","1.89는 0.01이 189개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","35.39","35.87","34.89","34.42"],["지유","33.88","35.64","36.04","36.51"],["채원","33.65","33.96","37.62","35.50"],["건우","37.51","34.33","34.85","34.98"]]}},{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 142.36초예요. 예선 통과 기준 143초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["64"],"explanation":["기준에서 우리 기록을 빼요.","143 − 142.36 = 0.64.","0.64는 0.01이 64개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","38.62","37.11","39.90","35.33"],["지유","39.78","38.53","34.19","37.11"],["채원","39.40","38.52","33.25","39.21"],["건우","38.73","34.00","35.50","38.04"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconcept