INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_challenge#5','math',4,2,'u3','L10','g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C9',3,'sa','auto','개인 혼영에서 서윤의 기록은 175.98초, 민서의 기록은 180.67초예요. 두 사람의 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u3-C9","difficulty":3,"kind":"sa","stem":"개인 혼영에서 서윤의 기록은 175.98초, 민서의 기록은 180.67초예요. 두 사람의 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["469"],"explanation":["큰 기록에서 작은 기록을 빼요 — 소수점을 맞추어요.","180.67 − 175.98 = 4.69.","4.69는 0.01이 469개 — 서윤이 더 빨라요."],"variant_rule":{"alt":[{"stem":"개인 혼영에서 채원의 기록은 177.14초, 건우의 기록은 176.54초예요. 두 사람의 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["큰 기록에서 작은 기록을 빼요 — 소수점을 맞추어요.","177.14 − 176.54 = 0.6.","0.6은 0.01이 60개 — 건우가 더 빨라요."],"asset":null},{"stem":"개인 혼영에서 준우의 기록은 172.22초, 도연의 기록은 173.09초예요. 두 사람의 기록의 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["87"],"explanation":["큰 기록에서 작은 기록을 빼요 — 소수점을 맞추어요.","173.09 − 172.22 = 0.87.","0.87은 0.01이 87개 — 준우가 더 빨라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_challenge#6','math',4,2,'u3','L10','g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C9',3,'mc','auto','민서의 지난주 자유형 50 m 기록은 49.21초였어요. 이번 주에는 0.93초를 줄였어요. 이번 주 기록은 몇 초인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],true,'{"seq":6,"concept":"M4-2-u3-C9","difficulty":3,"kind":"mc","stem":"민서의 지난주 자유형 50 m 기록은 49.21초였어요. 이번 주에는 0.93초를 줄였어요. 이번 주 기록은 몇 초인가요?","options":[{"t":"48.28초","correct":true},{"t":"49.72초","mis":"M4-2-u3-X13"},{"t":"49.38초","mis":"M4-2-u3-X14"},{"t":"50.14초","mis":"M4-2-u3-X16"}],"explanation":["기록을 「줄였다」는 덜어 내는 뺄셈이에요.","49.21 − 0.93 = 48.28.","이번 주 기록은 48.28초예요."],"variant_rule":{"alt":[{"stem":"서윤의 지난주 자유형 50 m 기록은 47.16초였어요. 이번 주에는 1.75초를 줄였어요. 이번 주 기록은 몇 초인가요?","options":[{"t":"45.41초","correct":true},{"t":"46.61초","mis":"M4-2-u3-X13"},{"t":"46.41초","mis":"M4-2-u3-X14"},{"t":"48.91초","mis":"M4-2-u3-X16"}],"explanation":["기록을 「줄였다」는 덜어 내는 뺄셈이에요.","47.16 − 1.75 = 45.41.","이번 주 기록은 45.41초예요."],"asset":null},{"stem":"준우의 지난주 자유형 50 m 기록은 42.26초였어요. 이번 주에는 0.65초를 줄였어요. 이번 주 기록은 몇 초인가요?","options":[{"t":"41.61초","correct":true},{"t":"42.41초","mis":"M4-2-u3-X13"},{"t":"42.61초","mis":"M4-2-u3-X14"},{"t":"42.91초","mis":"M4-2-u3-X16"}],"explanation":["기록을 「줄였다」는 덜어 내는 뺄셈이에요.","42.26 − 0.65 = 41.61.","이번 주 기록은 41.61초예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_challenge#7','math',4,2,'u3','L10','g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C9',3,'mc','auto','2.88 + 0.98 + 1.29는 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X20','M4-2-u3-X16']::text[],true,'{"seq":7,"concept":"M4-2-u3-C9","difficulty":3,"kind":"mc","stem":"2.88 + 0.98 + 1.29는 얼마인가요?","options":[{"t":"5.15","correct":true},{"t":"3.95","mis":"M4-2-u3-X11"},{"t":"3.86","mis":"M4-2-u3-X20"},{"t":"2.57","mis":"M4-2-u3-X16"}],"explanation":["앞에서부터 차례로 — 2.88 + 0.98 = 3.86.","3.86 + 1.29 = 5.15.","더할 때마다 소수점을 맞추어요."],"variant_rule":{"alt":[{"stem":"4.84 + 2.84 + 1.27은 얼마인가요?","options":[{"t":"8.95","correct":true},{"t":"7.85","mis":"M4-2-u3-X11"},{"t":"7.68","mis":"M4-2-u3-X20"},{"t":"6.41","mis":"M4-2-u3-X16"}],"explanation":["앞에서부터 차례로 — 4.84 + 2.84 = 7.68.","7.68 + 1.27 = 8.95.","더할 때마다 소수점을 맞추어요."],"asset":null},{"stem":"1.48 + 2.37 + 4.57은 얼마인가요?","options":[{"t":"8.42","correct":true},{"t":"7.22","mis":"M4-2-u3-X11"},{"t":"3.85","mis":"M4-2-u3-X20"},{"t":"8.52","mis":"M4-2-u3-X11"}],"explanation":["앞에서부터 차례로 — 1.48 + 2.37 = 3.85.","3.85 + 4.57 = 8.42.","더할 때마다 소수점을 맞추어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_challenge#8','math',4,2,'u3','L10','g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C10',4,'essay','teacher','배영과 평영 기록이 다음과 같아요. 채원: 배영 35.20초, 평영 38.10초 / 서준: 배영 35.90초, 평영 39.60초. 한 선수는 한 영법만 맡을 때, 두 사람의 기록 합이 더 작은 짝을 찾고 「영법마다 가장 빠른 선수를 고르면 된다」는 생각이 왜 안 되는지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C10","difficulty":4,"kind":"essay","stem":"배영과 평영 기록이 다음과 같아요. 채원: 배영 35.20초, 평영 38.10초 / 서준: 배영 35.90초, 평영 39.60초. 한 선수는 한 영법만 맡을 때, 두 사람의 기록 합이 더 작은 짝을 찾고 「영법마다 가장 빠른 선수를 고르면 된다」는 생각이 왜 안 되는지 써 보세요.","answer_guide":{"answer":"예: 채원이가 배영과 평영 모두 가장 빠르지만 한 선수는 한 영법만 맡을 수 있다. 배영 채원·평영 서준은 35.2 + 39.6 = 74.8초, 배영 서준·평영 채원은 35.9 + 38.1 = 74초이다. 74 < 74.8이므로 배영 서준·평영 채원이 더 좋다. 가장 빠른 것만 고르면 조건을 어기고, 두 짝의 합을 견주어야 한다.","scoring_points":["배영 서준·평영 채원을 골랐는가","두 짝의 합 74.8초와 74초를 구했는가","한 선수 한 영법 조건 때문에 합을 견주어야 한다고 썼는가"]},"explanation":["35.2 + 39.6 = 74.8.","35.9 + 38.1 = 74.","배영 서준·평영 채원."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_challenge#9','math',4,2,'u3','L10','g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C9',4,'essay','teacher','돌고래 팀의 기록은 148.89초, 아기 상어 팀의 기록은 150.21초예요. 어느 팀이 몇 초 더 빠른지 구하고, 기록의 크기 비교가 왜 「반대로 읽힌다」고 하는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C9","difficulty":4,"kind":"essay","stem":"돌고래 팀의 기록은 148.89초, 아기 상어 팀의 기록은 150.21초예요. 어느 팀이 몇 초 더 빠른지 구하고, 기록의 크기 비교가 왜 「반대로 읽힌다」고 하는지 설명해 보세요.","answer_guide":{"answer":"예: 기록은 결승점까지 걸린 시간이므로 작을수록 빠르다. 148.89 < 150.21이므로 돌고래 팀이 더 빠르다. 150.21 − 148.89 = 1.32이므로 1.32초 더 빠르다. 수가 크다고 좋은 기록이 아니라서 크기 비교가 반대로 읽힌다.","scoring_points":["돌고래 팀이 더 빠르다고 답했는가","1.32초를 구했는가","기록은 작을수록 빠르다고 설명했는가"]},"explanation":["148.89 < 150.21.","150.21 − 148.89 = 1.32.","돌고래 팀이 1.32초 더 빨라요."],"asset":{"type":"expr_grid","rows":[["","1","5","0",".","2","1"],["−","1","4","8",".","8","9"],["","","","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_L10_challenge#10','math',4,2,'u3','L10','g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C10',4,'sa','auto','한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 135.61초예요. 예선 통과 기준 137초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u3-C10","difficulty":4,"kind":"sa","stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 135.61초예요. 예선 통과 기준 137초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["139"],"explanation":["기준에서 우리 기록을 빼요.","137 − 135.61 = 1.39.","1.39는 0.01이 139개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","36.98","33.83","35.76","39.25"],["지유","33.57","37.20","37.59","35.01"],["채원","35.41","33.74","33.89","37.97"],["건우","37.46","37.17","36.12","34.32"]]},"variant_rule":{"alt":[{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 136.73초예요. 예선 통과 기준 137초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["27"],"explanation":["기준에서 우리 기록을 빼요.","137 − 136.73 = 0.27.","0.27은 0.01이 27개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","33.70","35.62","35.87","38.63"],["지유","34.18","39.10","33.19","34.63"],["채원","33.07","34.07","35.76","36.19"],["건우","37.75","39.85","34.33","37.88"]]}},{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 139.77초예요. 예선 통과 기준 141초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["123"],"explanation":["기준에서 우리 기록을 빼요.","141 − 139.77 = 1.23.","1.23은 0.01이 123개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","35.57","39.93","35.70","34.95"],["지유","36.08","35.02","34.50","36.99"],["채원","38.37","37.51","34.78","35.70"],["건우","35.50","34.00","33.53","39.02"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.miscon