INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#7','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C7',1,'mc','auto','8.5 − 7.4는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01','M4-2-u3-X14']::text[],true,'{"seq":7,"concept":"M4-2-u3-C7","difficulty":1,"kind":"mc","stem":"8.5 − 7.4는 얼마인가요?","options":[{"t":"1.1","correct":true},{"t":"15.9","mis":"M4-2-u3-X16"},{"t":"0.11","mis":"M4-2-u3-X01"},{"t":"2.1","mis":"M4-2-u3-X14"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.1이 85개 − 74개 = 11개.","8.5 − 7.4 = 1.1."],"variant_rule":{"alt":[{"stem":"8.8 − 6.7은 얼마인가요?","options":[{"t":"2.1","correct":true},{"t":"15.5","mis":"M4-2-u3-X16"},{"t":"0.21","mis":"M4-2-u3-X01"},{"t":"3.1","mis":"M4-2-u3-X14"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.1이 88개 − 67개 = 21개.","8.8 − 6.7 = 2.1."],"asset":null},{"stem":"2.9 − 2.5는 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"5.4","mis":"M4-2-u3-X16"},{"t":"0.04","mis":"M4-2-u3-X01"},{"t":"1.4","mis":"M4-2-u3-X14"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.1이 29개 − 25개 = 4개.","2.9 − 2.5 = 0.4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#8','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C8',1,'sa','auto','1.06 − 0.47을 세로로 계산했어요. 그 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u3-C8","difficulty":1,"kind":"sa","stem":"1.06 − 0.47을 세로로 계산했어요. 그 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["59"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.01이 106개 − 47개 = 59개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","1.06 − 0.47 = 0.59."],"asset":{"type":"expr_grid","rows":[["","1",".","0","6"],["−","0",".","4","7"],["","?",".","?","?"]]},"variant_rule":{"alt":[{"stem":"3.23 − 0.24를 세로로 계산했어요. 그 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["299"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.01이 323개 − 24개 = 299개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","3.23 − 0.24 = 2.99."],"asset":{"type":"expr_grid","rows":[["","3",".","2","3"],["−","0",".","2","4"],["","?",".","?","?"]]}},{"stem":"0.86 − 0.49를 세로로 계산했어요. 그 차는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 빼요.","0.01이 86개 − 49개 = 37개 — 뺄 수 없는 자리는 윗자리에서 1을 받아내림해요(0.01이 10개).","0.86 − 0.49 = 0.37."],"asset":{"type":"expr_grid","rows":[["","0",".","8","6"],["−","0",".","4","9"],["","?",".","?","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#9','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C1',2,'mc','auto','사육사가 펭귄의 키를 재어 보니 246 cm였어요. 안내판에는 m 단위로 적어야 해요. 246 cm는 몇 m인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":9,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"사육사가 펭귄의 키를 재어 보니 246 cm였어요. 안내판에는 m 단위로 적어야 해요. 246 cm는 몇 m인가요?","options":[{"t":"2.46 m","correct":true},{"t":"24.6 m","mis":"M4-2-u3-X04"},{"t":"0.246 m","mis":"M4-2-u3-X04"},{"t":"246 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","246 cm는 0.01 m가 246개예요.","246 cm = 2.46 m."],"variant_rule":{"alt":[{"stem":"사육사가 기린 우리 문의 폭을 재어 보니 332 cm였어요. 안내판에는 m 단위로 적어야 해요. 332 cm는 몇 m인가요?","options":[{"t":"3.32 m","correct":true},{"t":"33.2 m","mis":"M4-2-u3-X04"},{"t":"0.332 m","mis":"M4-2-u3-X04"},{"t":"332 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","332 cm는 0.01 m가 332개예요.","332 cm = 3.32 m."],"asset":null},{"stem":"사육사가 바다사자 먹이통의 높이를 재어 보니 364 cm였어요. 안내판에는 m 단위로 적어야 해요. 364 cm는 몇 m인가요?","options":[{"t":"3.64 m","correct":true},{"t":"36.4 m","mis":"M4-2-u3-X04"},{"t":"0.364 m","mis":"M4-2-u3-X04"},{"t":"364 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","364 cm는 0.01 m가 364개예요.","364 cm = 3.64 m."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
