INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#11','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C3',2,'mc','auto','65.8의 100배는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":11,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"65.8의 100배는 얼마인가요?","options":[{"t":"6580","correct":true},{"t":"658","mis":"M4-2-u3-X06"},{"t":"6.58","mis":"M4-2-u3-X05"},{"t":"0.658","mis":"M4-2-u3-X05"}],"explanation":["100배 하면 숫자가 왼쪽으로 두 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","65.8의 100배 → 6580."],"variant_rule":{"alt":[{"stem":"64.6의 10배는 얼마인가요?","options":[{"t":"646","correct":true},{"t":"6460","mis":"M4-2-u3-X06"},{"t":"6.46","mis":"M4-2-u3-X05"},{"t":"0.646","mis":"M4-2-u3-X05"}],"explanation":["10배 하면 숫자가 왼쪽으로 한 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","64.6의 10배 → 646."],"asset":null},{"stem":"0.92의 100배는 얼마인가요?","options":[{"t":"92","correct":true},{"t":"9.2","mis":"M4-2-u3-X06"},{"t":"0.092","mis":"M4-2-u3-X05"},{"t":"920","mis":"M4-2-u3-X06"}],"explanation":["100배 하면 숫자가 왼쪽으로 두 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","0.92의 100배 → 92."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#12','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C4',2,'mc','auto','3.6, 3.44, 3.835를 큰 수부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X07','M4-2-u3-X03']::text[],true,'{"seq":12,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"3.6, 3.44, 3.835를 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"3.835, 3.6, 3.44","correct":true},{"t":"3.44, 3.6, 3.835","mis":"M4-2-u3-X17"},{"t":"3.835, 3.44, 3.6","mis":"M4-2-u3-X07"},{"t":"3.6, 3.835, 3.44","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 3.835, 3.6, 3.44."],"variant_rule":{"alt":[{"stem":"3.4, 3.764, 3.02를 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"3.764, 3.4, 3.02","correct":true},{"t":"3.02, 3.4, 3.764","mis":"M4-2-u3-X17"},{"t":"3.764, 3.02, 3.4","mis":"M4-2-u3-X07"},{"t":"3.02, 3.764, 3.4","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 3.764, 3.4, 3.02."],"asset":null},{"stem":"0.975, 0.1, 0.83을 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"0.975, 0.83, 0.1","correct":true},{"t":"0.1, 0.83, 0.975","mis":"M4-2-u3-X17"},{"t":"0.975, 0.1, 0.83","mis":"M4-2-u3-X03"},{"t":"0.83, 0.975, 0.1","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 0.975, 0.83, 0.1."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#13','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C5',2,'mc','auto','동물 보건사가 고양이들에게 오전에 사료 0.8 kg, 오후에 0.5 kg을 주었어요. 하루에 준 사료는 모두 몇 kg인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X01']::text[],true,'{"seq":13,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"동물 보건사가 고양이들에게 오전에 사료 0.8 kg, 오후에 0.5 kg을 주었어요. 하루에 준 사료는 모두 몇 kg인가요?","options":[{"t":"1.3 kg","correct":true},{"t":"0.3 kg","mis":"M4-2-u3-X11"},{"t":"0.13 kg","mis":"M4-2-u3-X10"},{"t":"13 kg","mis":"M4-2-u3-X01"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","0.8 + 0.5 = 1.3 — 소수점을 맞추어 더해요.","1.3 kg이에요."],"variant_rule":{"alt":[{"stem":"집에서 동물 병원까지 4.8 km, 동물 병원에서 동물원까지 1.3 km예요. 집에서 동물 병원을 지나 동물원까지 간 거리는 몇 km인가요?","options":[{"t":"6.1 km","correct":true},{"t":"5.1 km","mis":"M4-2-u3-X11"},{"t":"5.11 km","mis":"M4-2-u3-X10"},{"t":"3.5 km","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","4.8 + 1.3 = 6.1 — 소수점을 맞추어 더해요.","6.1 km예요."],"asset":null},{"stem":"동물 보건사가 고양이들에게 오전에 사료 0.9 kg, 오후에 3.9 kg을 주었어요. 하루에 준 사료는 모두 몇 kg인가요?","options":[{"t":"4.8 kg","correct":true},{"t":"3.8 kg","mis":"M4-2-u3-X11"},{"t":"3.18 kg","mis":"M4-2-u3-X10"},{"t":"3 kg","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","0.9 + 3.9 = 4.8 — 소수점을 맞추어 더해요.","4.8 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#14','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C6',2,'mc','auto','4.64 + 3.98은 얼마인가요?',ARRAY['M4-2-u3-X11']::text[],true,'{"seq":14,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"4.64 + 3.98은 얼마인가요?","options":[{"t":"8.62","correct":true},{"t":"7.52","mis":"M4-2-u3-X11"},{"t":"8.52","mis":"M4-2-u3-X11"},{"t":"7.62","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 464개 + 398개 = 862개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","4.64 + 3.98 = 8.62."],"variant_rule":{"alt":[{"stem":"2.37 + 4.53은 얼마인가요?","options":[{"t":"6.9","correct":true},{"t":"6.8","mis":"M4-2-u3-X11"},{"t":"2.16","mis":"M4-2-u3-X16"},{"t":"0.69","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 237개 + 453개 = 690개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","2.37 + 4.53 = 6.9."],"asset":null},{"stem":"1.76 + 4.53은 얼마인가요?","options":[{"t":"6.29","correct":true},{"t":"5.29","mis":"M4-2-u3-X11"},{"t":"2.77","mis":"M4-2-u3-X16"},{"t":"62.9","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 176개 + 453개 = 629개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","1.76 + 4.53 = 6.29."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#15','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C7',2,'mc','auto','수의사가 소독약 5.2 L 가운데 1.7 L를 썼어요. 남은 소독약은 몇 L인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":15,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"수의사가 소독약 5.2 L 가운데 1.7 L를 썼어요. 남은 소독약은 몇 L인가요?","options":[{"t":"3.5 L","correct":true},{"t":"4.5 L","mis":"M4-2-u3-X13"},{"t":"6.9 L","mis":"M4-2-u3-X16"},{"t":"0.35 L","mis":"M4-2-u3-X01"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","5.2 − 1.7 = 3.5 — 소수점을 맞추어 빼요.","3.5 L예요."],"variant_rule":{"alt":[{"stem":"참외가 든 바구니의 무게는 3.4 kg이고 빈 바구니는 1.5 kg이에요. 참외만의 무게는 몇 kg인가요?","options":[{"t":"1.9 kg","correct":true},{"t":"2.1 kg","mis":"M4-2-u3-X13"},{"t":"2.9 kg","mis":"M4-2-u3-X14"},{"t":"4.9 kg","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","3.4 − 1.5 = 1.9 — 소수점을 맞추어 빼요.","1.9 kg이에요."],"asset":null},{"stem":"수의사가 소독약 4.2 L 가운데 1.9 L를 썼어요. 남은 소독약은 몇 L인가요?","options":[{"t":"2.3 L","correct":true},{"t":"3.7 L","mis":"M4-2-u3-X13"},{"t":"3.3 L","mis":"M4-2-u3-X14"},{"t":"6.1 L","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","4.2 − 1.9 = 2.3 — 소수점을 맞추어 빼요.","2.3 L예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#16','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C9',2,'mc','auto','혼계영 200 m에서 수달 팀의 기록은 147.74초, 펭귄 팀의 기록은 150.24초예요. 더 빠른 팀은 어느 팀인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X18']::text[],true,'{"seq":16,"concept":"M4-2-u3-C9","difficulty":2,"kind":"mc","stem":"혼계영 200 m에서 수달 팀의 기록은 147.74초, 펭귄 팀의 기록은 150.24초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"수달 팀","correct":true},{"t":"펭귄 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","147.74 < 150.24.","더 빠른 팀은 수달 팀이에요."],"variant_rule":{"alt":[{"stem":"혼계영 200 m에서 돌고래 팀의 기록은 149.57초, 아기 상어 팀의 기록은 150.82초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"돌고래 팀","correct":true},{"t":"아기 상어 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","149.57 < 150.82.","더 빠른 팀은 돌고래 팀이에요."],"asset":null},{"stem":"혼계영 200 m에서 수달 팀의 기록은 149.46초, 펭귄 팀의 기록은 148.08초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"펭귄 팀","correct":true},{"t":"수달 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","149.46 > 148.08.","더 빠른 팀은 펭귄 팀이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#17','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C1',3,'mc','auto','수직선에서 작은 눈금 한 칸은 0.01이에요. 2.1에서 오른쪽으로 작은 눈금 9칸 더 간 곳의 수는 얼마인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X17']::text[],true,'{"seq":17,"concept":"M4-2-u3-C1","difficulty":3,"kind":"mc","stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 2.1에서 오른쪽으로 작은 눈금 9칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"2.19","correct":true},{"t":"3","mis":"M4-2-u3-X01"},{"t":"2.01","mis":"M4-2-u3-X17"},{"t":"11.1","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 9칸은 0.09예요.","2.1 + 0.09 = 2.19.","0.1씩이 아니라 0.01씩 커져요."],"variant_rule":{"alt":[{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 9.1에서 오른쪽으로 작은 눈금 4칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"9.14","correct":true},{"t":"9.5","mis":"M4-2-u3-X01"},{"t":"9.06","mis":"M4-2-u3-X17"},{"t":"13.1","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 4칸은 0.04예요.","9.1 + 0.04 = 9.14.","0.1씩이 아니라 0.01씩 커져요."],"asset":null},{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 7.6에서 오른쪽으로 작은 눈금 3칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"7.63","correct":true},{"t":"7.9","mis":"M4-2-u3-X01"},{"t":"7.57","mis":"M4-2-u3-X17"},{"t":"10.6","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 3칸은 0.03이에요.","7.6 + 0.03 = 7.63.","0.1씩이 아니라 0.01씩 커져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#18','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C4',3,'sa','auto','2.5□5 < 2.549일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u3-C4","difficulty":3,"kind":"sa","stem":"2.5□5 < 2.549일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 0, 1, 2, 3, 4.","모두 5개 — 같아지는 수·경계의 수를 확인해요."],"variant_rule":{"alt":[{"stem":"1.74□ < 1.743일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 0, 1, 2.","모두 3개 — 같아지는 수·경계의 수를 확인해요."],"asset":null},{"stem":"0.5□3 < 0.545일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 0, 1, 2, 3, 4.","모두 5개 — 같아지는 수·경계의 수를 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#19','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C6',3,'error','auto','3.9 + 0.15를 세로로 계산해 0.54라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M4-2-u3-X12','M4-2-u3-X11','M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":19,"concept":"M4-2-u3-C6","difficulty":3,"kind":"error","stem":"3.9 + 0.15를 세로로 계산해 0.54라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 3.9 = 3.90으로 보면 자리가 맞아요.","0.01이 390개 + 15개 = 405개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","3.9 + 0.15 = 4.05."],"variant_rule":{"alt":[{"stem":"4.2 + 5.85를 세로로 계산해 6.27이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 4.2 = 4.20으로 보면 자리가 맞아요.","0.01이 420개 + 585개 = 1005개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","4.2 + 5.85 = 10.05."],"asset":null},{"stem":"4.27 + 4.1을 세로로 계산해 4.68이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 4.1 = 4.10으로 보면 자리가 맞아요.","0.01이 427개 + 410개 = 837개.","4.27 + 4.1 = 8.37."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#20','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C8',3,'mc','auto','5.3 − □ = 3.76일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X13','M4-2-u3-X14']::text[],true,'{"seq":20,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"5.3 − □ = 3.76일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"1.54","correct":true},{"t":"9.06","mis":"M4-2-u3-X16"},{"t":"2.46","mis":"M4-2-u3-X13"},{"t":"2.64","mis":"M4-2-u3-X14"}],"explanation":["5.3에서 □를 빼서 3.76 — □ = 5.3 − 3.76.","□ = 1.54.","확인: 5.3 − 1.54 = 3.76."],"variant_rule":{"alt":[{"stem":"7.2 − □ = 5.22일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"1.98","correct":true},{"t":"12.42","mis":"M4-2-u3-X16"},{"t":"2.02","mis":"M4-2-u3-X13"},{"t":"2.08","mis":"M4-2-u3-X14"}],"explanation":["7.2에서 □를 빼서 5.22 — □ = 7.2 − 5.22.","□ = 1.98.","확인: 7.2 − 1.98 = 5.22."],"asset":null},{"stem":"7.7 − □ = 1.55일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"6.15","correct":true},{"t":"9.25","mis":"M4-2-u3-X16"},{"t":"6.25","mis":"M4-2-u3-X13"},{"t":"6.05","mis":"M4-2-u3-X14"}],"explanation":["7.7에서 □를 빼서 1.55 — □ = 7.7 − 1.55.","□ = 6.15.","확인: 7.7 − 6.15 = 1.55."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#21','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C10',3,'mc','auto','한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?',ARRAY['M4-2-u3-X19','M4-2-u3-X17','M4-2-u3-X18']::text[],true,'{"seq":21,"concept":"M4-2-u3-C10","difficulty":3,"kind":"mc","stem":"한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배영 건우 · 평영 서준 · 접영 지유 · 자유형 채원","correct":true},{"t":"배영 건우 · 평영 서준 · 접영 건우 · 자유형 건우","mis":"M4-2-u3-X19"},{"t":"배영 지유 · 평영 건우 · 접영 채원 · 자유형 서준","mis":"M4-2-u3-X17"},{"t":"배영 채원 · 평영 서준 · 접영 지유 · 자유형 건우","mis":"M4-2-u3-X18"}],"explanation":["영법마다 가장 빠른 선수만 고르면 건우가 두 영법을 맡게 되어 안 돼요.","겹치는 영법은 두 번째로 빠른 선수와 짝지어 합을 견주어요.","가장 작은 합은 139.98초 — 배영 건우 · 평영 서준 · 접영 지유 · 자유형 채원."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","37.77","35.56","38.14","39.92"],["지유","37.03","36.36","33.92","39.16"],["채원","37.28","38.82","38.14","36.64"],["건우","33.86","39.22","33.04","35.08"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배영 지유 · 평영 서준 · 접영 채원 · 자유형 건우","correct":true},{"t":"배영 지유 · 평영 지유 · 접영 채원 · 자유형 지유","mis":"M4-2-u3-X19"},{"t":"배영 서준 · 평영 건우 · 접영 지유 · 자유형 채원","mis":"M4-2-u3-X17"},{"t":"배영 서준 · 평영 지유 · 접영 채원 · 자유형 건우","mis":"M4-2-u3-X18"}],"explanation":["영법마다 가장 빠른 선수만 고르면 지유가 두 영법을 맡게 되어 안 돼요.","겹치는 영법은 두 번째로 빠른 선수와 짝지어 합을 견주어요.","가장 작은 합은 143.3초 — 배영 지유 · 평영 서준 · 접영 채원 · 자유형 건우."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","38.96","38.25","38.36","38.07"],["지유","34.34","34.82","38.05","34.17"],["채원","37.09","38.55","35.57","39.04"],["건우","37.17","36.76","39.19","35.14"]]}},{"stem":"이번에는 다른 문제예요. 한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배영 지유 · 평영 건우 · 접영