INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#22','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C3',3,'mc','auto','어떤 수의 10분의 1은 0.109예요. 어떤 수는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":22,"concept":"M4-2-u3-C3","difficulty":3,"kind":"mc","stem":"어떤 수의 10분의 1은 0.109예요. 어떤 수는 얼마인가요?","options":[{"t":"1.09","correct":true},{"t":"10.9","mis":"M4-2-u3-X06"},{"t":"0.109","mis":"M4-2-u3-X05"},{"t":"109","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 10분의 1 → 0.109.","거꾸로 0.109의 10배를 구해요.","어떤 수 = 1.09."],"variant_rule":{"alt":[{"stem":"어떤 수의 10배는 25예요. 어떤 수는 얼마인가요?","options":[{"t":"2.5","correct":true},{"t":"250","mis":"M4-2-u3-X05"},{"t":"2500","mis":"M4-2-u3-X06"},{"t":"0.25","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 10배 → 25.","거꾸로 25의 10분의 1을 구해요.","어떤 수 = 2.5."],"asset":null},{"stem":"어떤 수의 100분의 1은 0.337이에요. 어떤 수는 얼마인가요?","options":[{"t":"33.7","correct":true},{"t":"3.37","mis":"M4-2-u3-X06"},{"t":"0.337","mis":"M4-2-u3-X05"},{"t":"337","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 100분의 1 → 0.337.","거꾸로 0.337의 100배를 구해요.","어떤 수 = 33.7."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#23','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C6',4,'mc','auto','5.8 + □ = 7.43일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X13','M4-2-u3-X14']::text[],true,'{"seq":23,"concept":"M4-2-u3-C6","difficulty":4,"kind":"mc","stem":"5.8 + □ = 7.43일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"1.63","correct":true},{"t":"13.23","mis":"M4-2-u3-X16"},{"t":"2.43","mis":"M4-2-u3-X13"},{"t":"2.63","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","7.43 − 5.8 = 1.63.","확인: 5.8 + 1.63 = 7.43."],"variant_rule":{"alt":[{"stem":"3.5 + □ = 12.32일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"8.82","correct":true},{"t":"15.82","mis":"M4-2-u3-X16"},{"t":"11.22","mis":"M4-2-u3-X13"},{"t":"19.82","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","12.32 − 3.5 = 8.82.","확인: 3.5 + 8.82 = 12.32."],"asset":null},{"stem":"8.6 + □ = 14.27일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"5.67","correct":true},{"t":"22.87","mis":"M4-2-u3-X16"},{"t":"14.47","mis":"M4-2-u3-X13"},{"t":"16.67","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","14.27 − 8.6 = 5.67.","확인: 8.6 + 5.67 = 14.27."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_a#24','math',4,2,'u3','','g4_2_math_u3_review_a','unit_review','M4-2-u3-C10',4,'sa','auto','한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 139.87초예요. 예선 통과 기준 141초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u3-C10","difficulty":4,"kind":"sa","stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 139.87초예요. 예선 통과 기준 141초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["113"],"explanation":["기준에서 우리 기록을 빼요.","141 − 139.87 = 1.13.","1.13은 0.01이 113개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","34.98","38.10","39.38","39.50"],["지유","35.88","36.01","33.79","39.80"],["채원","34.16","38.12","38.96","38.75"],["건우","34.24","39.60","36.19","33.82"]]},"variant_rule":{"alt":[{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 140.83초예요. 예선 통과 기준 141초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["17"],"explanation":["기준에서 우리 기록을 빼요.","141 − 140.83 = 0.17.","0.17은 0.01이 17개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","35.08","36.27","38.56","39.02"],["지유","36.16","38.70","35.59","38.26"],["채원","34.99","35.52","37.41","37.44"],["건우","37.71","36.45","36.16","34.64"]]}},{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 142.48초예요. 예선 통과 기준 144초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["152"],"explanation":["기준에서 우리 기록을 빼요.","144 − 142.48 = 1.52.","1.52는 0.01이 152개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","36.62","39.46","38.24","35.00"],["지유","38.73","36.07","39.63","36.70"],["채원","34.35","37.40","34.17","38.73"],["건우","38.49","35.73","37.06","36.20"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has