INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#9','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C1',2,'mc','auto','사육사가 기린 우리 문의 폭을 재어 보니 178 cm였어요. 안내판에는 m 단위로 적어야 해요. 178 cm는 몇 m인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":9,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"사육사가 기린 우리 문의 폭을 재어 보니 178 cm였어요. 안내판에는 m 단위로 적어야 해요. 178 cm는 몇 m인가요?","options":[{"t":"1.78 m","correct":true},{"t":"17.8 m","mis":"M4-2-u3-X04"},{"t":"0.178 m","mis":"M4-2-u3-X04"},{"t":"178 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","178 cm는 0.01 m가 178개예요.","178 cm = 1.78 m."],"variant_rule":{"alt":[{"stem":"사육사가 바다사자 먹이통의 높이를 재어 보니 333 cm였어요. 안내판에는 m 단위로 적어야 해요. 333 cm는 몇 m인가요?","options":[{"t":"3.33 m","correct":true},{"t":"33.3 m","mis":"M4-2-u3-X04"},{"t":"0.333 m","mis":"M4-2-u3-X04"},{"t":"333 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","333 cm는 0.01 m가 333개예요.","333 cm = 3.33 m."],"asset":null},{"stem":"사육사가 홍학의 다리 길이를 재어 보니 166 cm였어요. 안내판에는 m 단위로 적어야 해요. 166 cm는 몇 m인가요?","options":[{"t":"1.66 m","correct":true},{"t":"16.6 m","mis":"M4-2-u3-X04"},{"t":"0.166 m","mis":"M4-2-u3-X04"},{"t":"166 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","166 cm는 0.01 m가 166개예요.","166 cm = 1.66 m."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
