INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#11','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C3',2,'mc','auto','80.1의 100배는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":11,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"80.1의 100배는 얼마인가요?","options":[{"t":"8010","correct":true},{"t":"801","mis":"M4-2-u3-X06"},{"t":"8.01","mis":"M4-2-u3-X05"},{"t":"0.801","mis":"M4-2-u3-X05"}],"explanation":["100배 하면 숫자가 왼쪽으로 두 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","80.1의 100배 → 8010."],"variant_rule":{"alt":[{"stem":"14.2의 10배는 얼마인가요?","options":[{"t":"142","correct":true},{"t":"1420","mis":"M4-2-u3-X06"},{"t":"1.42","mis":"M4-2-u3-X05"},{"t":"0.142","mis":"M4-2-u3-X05"}],"explanation":["10배 하면 숫자가 왼쪽으로 한 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","14.2의 10배 → 142."],"asset":null},{"stem":"2.13의 10배는 얼마인가요?","options":[{"t":"21.3","correct":true},{"t":"213","mis":"M4-2-u3-X06"},{"t":"0.213","mis":"M4-2-u3-X05"},{"t":"2130","mis":"M4-2-u3-X06"}],"explanation":["10배 하면 숫자가 왼쪽으로 한 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","2.13의 10배 → 21.3."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#12','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C4',2,'mc','auto','1.7, 1.52, 1.954를 큰 수부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X07','M4-2-u3-X03']::text[],true,'{"seq":12,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"1.7, 1.52, 1.954를 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"1.954, 1.7, 1.52","correct":true},{"t":"1.52, 1.7, 1.954","mis":"M4-2-u3-X17"},{"t":"1.954, 1.52, 1.7","mis":"M4-2-u3-X07"},{"t":"1.7, 1.954, 1.52","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 1.954, 1.7, 1.52."],"variant_rule":{"alt":[{"stem":"1.6, 1.2, 1.534를 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"1.6, 1.534, 1.2","correct":true},{"t":"1.2, 1.534, 1.6","mis":"M4-2-u3-X17"},{"t":"1.534, 1.6, 1.2","mis":"M4-2-u3-X07"},{"t":"1.6, 1.2, 1.534","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 1.6, 1.534, 1.2."],"asset":null},{"stem":"2.394, 2.6, 2.37을 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"2.6, 2.394, 2.37","correct":true},{"t":"2.37, 2.394, 2.6","mis":"M4-2-u3-X17"},{"t":"2.394, 2.37, 2.6","mis":"M4-2-u3-X07"},{"t":"2.394, 2.6, 2.37","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 2.6, 2.394, 2.37."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#13','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C5',2,'mc','auto','집에서 동물 병원까지 4.5 km, 동물 병원에서 동물원까지 3.6 km예요. 집에서 동물 병원을 지나 동물원까지 간 거리는 몇 km인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],true,'{"seq":13,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"집에서 동물 병원까지 4.5 km, 동물 병원에서 동물원까지 3.6 km예요. 집에서 동물 병원을 지나 동물원까지 간 거리는 몇 km인가요?","options":[{"t":"8.1 km","correct":true},{"t":"7.1 km","mis":"M4-2-u3-X11"},{"t":"7.11 km","mis":"M4-2-u3-X10"},{"t":"0.9 km","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","4.5 + 3.6 = 8.1 — 소수점을 맞추어 더해요.","8.1 km예요."],"variant_rule":{"alt":[{"stem":"동물 보건사가 고양이들에게 오전에 사료 2.8 kg, 오후에 3.3 kg을 주었어요. 하루에 준 사료는 모두 몇 kg인가요?","options":[{"t":"6.1 kg","correct":true},{"t":"5.1 kg","mis":"M4-2-u3-X11"},{"t":"5.11 kg","mis":"M4-2-u3-X10"},{"t":"0.5 kg","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","2.8 + 3.3 = 6.1 — 소수점을 맞추어 더해요.","6.1 kg이에요."],"asset":null},{"stem":"집에서 동물 병원까지 1.7 km, 동물 병원에서 동물원까지 2.3 km예요. 집에서 동물 병원을 지나 동물원까지 간 거리는 몇 km인가요?","options":[{"t":"4 km","correct":true},{"t":"3 km","mis":"M4-2-u3-X11"},{"t":"3.1 km","mis":"M4-2-u3-X10"},{"t":"0.6 km","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","1.7 + 2.3 = 4 — 소수점을 맞추어 더해요.","4 km예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#14','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C6',2,'mc','auto','6.42 + 2.98은 얼마인가요?',ARRAY['M4-2-u3-X11']::text[],true,'{"seq":14,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"6.42 + 2.98은 얼마인가요?","options":[{"t":"9.4","correct":true},{"t":"8.3","mis":"M4-2-u3-X11"},{"t":"9.3","mis":"M4-2-u3-X11"},{"t":"8.4","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 642개 + 298개 = 940개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","6.42 + 2.98 = 9.4."],"variant_rule":{"alt":[{"stem":"1.35 + 0.92는 얼마인가요?","options":[{"t":"2.27","correct":true},{"t":"1.27","mis":"M4-2-u3-X11"},{"t":"0.43","mis":"M4-2-u3-X16"},{"t":"22.7","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 135개 + 92개 = 227개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","1.35 + 0.92 = 2.27."],"asset":null},{"stem":"1.97 + 0.36은 얼마인가요?","options":[{"t":"2.33","correct":true},{"t":"1.23","mis":"M4-2-u3-X11"},{"t":"2.23","mis":"M4-2-u3-X11"},{"t":"1.33","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 197개 + 36개 = 233개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","1.97 + 0.36 = 2.33."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#15','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C7',2,'mc','auto','참외가 든 바구니의 무게는 3.4 kg이고 빈 바구니는 1.7 kg이에요. 참외만의 무게는 몇 kg인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],true,'{"seq":15,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"참외가 든 바구니의 무게는 3.4 kg이고 빈 바구니는 1.7 kg이에요. 참외만의 무게는 몇 kg인가요?","options":[{"t":"1.7 kg","correct":true},{"t":"2.3 kg","mis":"M4-2-u3-X13"},{"t":"2.7 kg","mis":"M4-2-u3-X14"},{"t":"5.1 kg","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","3.4 − 1.7 = 1.7 — 소수점을 맞추어 빼요.","1.7 kg이에요."],"variant_rule":{"alt":[{"stem":"수의사가 소독약 3.8 L 가운데 0.9 L를 썼어요. 남은 소독약은 몇 L인가요?","options":[{"t":"2.9 L","correct":true},{"t":"3.1 L","mis":"M4-2-u3-X13"},{"t":"3.9 L","mis":"M4-2-u3-X14"},{"t":"4.7 L","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","3.8 − 0.9 = 2.9 — 소수점을 맞추어 빼요.","2.9 L예요."],"asset":null},{"stem":"참외가 든 바구니의 무게는 2.2 kg이고 빈 바구니는 0.8 kg이에요. 참외만의 무게는 몇 kg인가요?","options":[{"t":"1.4 kg","correct":true},{"t":"2.6 kg","mis":"M4-2-u3-X13"},{"t":"2.4 kg","mis":"M4-2-u3-X14"},{"t":"3 kg","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","2.2 − 0.8 = 1.4 — 소수점을 맞추어 빼요.","1.4 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#16','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C9',2,'mc','auto','혼계영 200 m에서 바다거북 팀의 기록은 146.52초, 물개 팀의 기록은 147.59초예요. 더 빠른 팀은 어느 팀인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X18']::text[],true,'{"seq":16,"concept":"M4-2-u3-C9","difficulty":2,"kind":"mc","stem":"혼계영 200 m에서 바다거북 팀의 기록은 146.52초, 물개 팀의 기록은 147.59초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"바다거북 팀","correct":true},{"t":"물개 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","146.52 < 147.59.","더 빠른 팀은 바다거북 팀이에요."],"variant_rule":{"alt":[{"stem":"혼계영 200 m에서 돌고래 팀의 기록은 153.64초, 아기 상어 팀의 기록은 151.92초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"아기 상어 팀","correct":true},{"t":"돌고래 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","153.64 > 151.92.","더 빠른 팀은 아기 상어 팀이에요."],"asset":null},{"stem":"혼계영 200 m에서 돌고래 팀의 기록은 150.68초, 아기 상어 팀의 기록은 151.54초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"돌고래 팀","correct":true},{"t":"아기 상어 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","150.68 < 151.54.","더 빠른 팀은 돌고래 팀이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#17','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C1',3,'mc','auto','수직선에서 작은 눈금 한 칸은 0.01이에요. 7.6에서 오른쪽으로 작은 눈금 5칸 더 간 곳의 수는 얼마인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X17']::text[],true,'{"seq":17,"concept":"M4-2-u3-C1","difficulty":3,"kind":"mc","stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 7.6에서 오른쪽으로 작은 눈금 5칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"7.65","correct":true},{"t":"8.1","mis":"M4-2-u3-X01"},{"t":"7.55","mis":"M4-2-u3-X17"},{"t":"12.6","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 5칸은 0.05예요.","7.6 + 0.05 = 7.65.","0.1씩이 아니라 0.01씩 커져요."],"variant_rule":{"alt":[{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 9.8에서 오른쪽으로 작은 눈금 4칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"9.84","correct":true},{"t":"10.2","mis":"M4-2-u3-X01"},{"t":"9.76","mis":"M4-2-u3-X17"},{"t":"13.8","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 4칸은 0.04예요.","9.8 + 0.04 = 9.84.","0.1씩이 아니라 0.01씩 커져요."],"asset":null},{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 6.3에서 오른쪽으로 작은 눈금 4칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"6.34","correct":true},{"t":"6.7","mis":"M4-2-u3-X01"},{"t":"6.26","mis":"M4-2-u3-X17"},{"t":"10.3","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 4칸은 0.04예요.","6.3 + 0.04 = 6.34.","0.1씩이 아니라 0.01씩 커져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#18','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C4',3,'sa','auto','1.9□7 > 1.948일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u3-C4","difficulty":3,"kind":"sa","stem":"1.9□7 > 1.948일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 5, 6, 7, 8, 9.","모두 5개 — 같아지는 수·경계의 수를 확인해요."],"variant_rule":{"alt":[{"stem":"2.62□ < 2.624일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 0, 1, 2, 3.","모두 4개 — 같아지는 수·경계의 수를 확인해요."],"asset":null},{"stem":"0.6□4 > 0.639일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 4, 5, 6, 7, 8, 9.","모두 6개 — 같아지는 수·경계의 수를 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#19','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C6',3,'error','auto','0.2 + 5.62를 세로로 계산해 5.64라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M4-2-u3-X12','M4-2-u3-X11','M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":19,"concept":"M4-2-u3-C6","difficulty":3,"kind":"error","stem":"0.2 + 5.62를 세로로 계산해 5.64라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 0.2 = 0.20으로 보면 자리가 맞아요.","0.01이 20개 + 562개 = 582개.","0.2 + 5.62 = 5.82."],"variant_rule":{"alt":[{"stem":"0.8 + 4.09를 세로로 계산해 4.17이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 0.8 = 0.80으로 보면 자리가 맞아요.","0.01이 80개 + 409개 = 489개.","0.8 + 4.09 = 4.89."],"asset":null},{"stem":"2.8 + 3.58을 세로로 계산해 3.86이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 2.8 = 2.80으로 보면 자리가 맞아요.","0.01이 280개 + 358개 = 638개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","2.8 + 3.58 = 6.38."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, 