INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#22','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C3',3,'mc','auto','어떤 수의 100배는 498이에요. 어떤 수는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":22,"concept":"M4-2-u3-C3","difficulty":3,"kind":"mc","stem":"어떤 수의 100배는 498이에요. 어떤 수는 얼마인가요?","options":[{"t":"4.98","correct":true},{"t":"4980","mis":"M4-2-u3-X06"},{"t":"49800","mis":"M4-2-u3-X05"},{"t":"49.8","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 100배 → 498.","거꾸로 498의 100분의 1을 구해요.","어떤 수 = 4.98."],"variant_rule":{"alt":[{"stem":"어떤 수의 10배는 87이에요. 어떤 수는 얼마인가요?","options":[{"t":"8.7","correct":true},{"t":"870","mis":"M4-2-u3-X05"},{"t":"8700","mis":"M4-2-u3-X06"},{"t":"0.87","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 10배 → 87.","거꾸로 87의 10분의 1을 구해요.","어떤 수 = 8.7."],"asset":null},{"stem":"어떤 수의 10배는 83.7이에요. 어떤 수는 얼마인가요?","options":[{"t":"8.37","correct":true},{"t":"837","mis":"M4-2-u3-X05"},{"t":"8370","mis":"M4-2-u3-X06"},{"t":"0.837","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 10배 → 83.7.","거꾸로 83.7의 10분의 1을 구해요.","어떤 수 = 8.37."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#23','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C6',4,'mc','auto','7.8 + □ = 16.53일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X13','M4-2-u3-X14']::text[],true,'{"seq":23,"concept":"M4-2-u3-C6","difficulty":4,"kind":"mc","stem":"7.8 + □ = 16.53일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"8.73","correct":true},{"t":"24.33","mis":"M4-2-u3-X16"},{"t":"11.33","mis":"M4-2-u3-X13"},{"t":"19.73","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","16.53 − 7.8 = 8.73.","확인: 7.8 + 8.73 = 16.53."],"variant_rule":{"alt":[{"stem":"2.8 + □ = 3.05일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"5.85","mis":"M4-2-u3-X16"},{"t":"1.85","mis":"M4-2-u3-X13"},{"t":"1.25","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","3.05 − 2.8 = 0.25.","확인: 2.8 + 0.25 = 3.05."],"asset":null},{"stem":"7.5 + □ = 17.39일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"9.89","correct":true},{"t":"24.89","mis":"M4-2-u3-X16"},{"t":"10.29","mis":"M4-2-u3-X13"},{"t":"10.89","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","17.39 − 7.5 = 9.89.","확인: 7.5 + 9.89 = 17.39."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#24','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C10',4,'sa','auto','한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 140.95초예요. 예선 통과 기준 141초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u3-C10","difficulty":4,"kind":"sa","stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 140.95초예요. 예선 통과 기준 141초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["5"],"explanation":["기준에서 우리 기록을 빼요.","141 − 140.95 = 0.05.","0.05는 0.01이 5개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","33.65","39.12","37.13","39.69"],["지유","34.08","39.19","35.49","36.25"],["채원","33.10","37.67","38.13","35.63"],["건우","33.34","36.18","39.36","35.65"]]},"variant_rule":{"alt":[{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 139.51초예요. 예선 통과 기준 141초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["149"],"explanation":["기준에서 우리 기록을 빼요.","141 − 139.51 = 1.49.","1.49는 0.01이 149개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","37.05","33.25","38.60","36.73"],["지유","34.16","37.71","38.95","33.42"],["채원","35.48","36.58","36.62","36.54"],["건우","36.91","38.40","37.36","39.61"]]}},{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 139.05초예요. 예선 통과 기준 140초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["95"],"explanation":["기준에서 우리 기록을 빼요.","140 − 139.05 = 0.95.","0.95는 0.01이 95개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","38.04","37.87","35.97","33.71"],["지유","35.13","33.07","33.39","35.82"],["채원","39.77","37.47","37.69","36.75"],["건우","34.58","35.36","36.09","38.62"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_var