INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_b#25','math',4,2,'u3','','g4_2_math_u3_review_b','unit_review','M4-2-u3-C4',4,'essay','teacher','7.84와 7.836 중 더 큰 수를 쓰고, 자리 수가 더 많은 7.836이 더 작은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u3-C4","difficulty":4,"kind":"essay","stem":"7.84와 7.836 중 더 큰 수를 쓰고, 자리 수가 더 많은 7.836이 더 작은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 7.84가 더 크다. 소수점을 기준으로 자리를 맞추면 7.840과 7.836이다. 일의 자리와 소수 첫째 자리가 같고 소수 둘째 자리에서 4 > 3이므로 7.84가 크다. 소수는 수의 길이가 아니라 큰 자리부터 견준다.","scoring_points":["7.84가 더 크다고 답했는가","7.840으로 자리를 맞추었는가","소수 둘째 자리 4 > 3으로 견주었는가"]},"explanation":["7.84 = 7.840.","소수 둘째 자리 4 > 3.","7.84가 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
