INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#9','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C1',2,'mc','auto','사육사가 바다사자 먹이통의 높이를 재어 보니 354 cm였어요. 안내판에는 m 단위로 적어야 해요. 354 cm는 몇 m인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":9,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"사육사가 바다사자 먹이통의 높이를 재어 보니 354 cm였어요. 안내판에는 m 단위로 적어야 해요. 354 cm는 몇 m인가요?","options":[{"t":"3.54 m","correct":true},{"t":"35.4 m","mis":"M4-2-u3-X04"},{"t":"0.354 m","mis":"M4-2-u3-X04"},{"t":"354 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","354 cm는 0.01 m가 354개예요.","354 cm = 3.54 m."],"variant_rule":{"alt":[{"stem":"사육사가 홍학의 다리 길이를 재어 보니 207 cm였어요. 안내판에는 m 단위로 적어야 해요. 207 cm는 몇 m인가요?","options":[{"t":"2.07 m","correct":true},{"t":"20.7 m","mis":"M4-2-u3-X04"},{"t":"0.207 m","mis":"M4-2-u3-X04"},{"t":"207 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","207 cm는 0.01 m가 207개예요.","207 cm = 2.07 m."],"asset":null},{"stem":"사육사가 펭귄의 키를 재어 보니 116 cm였어요. 안내판에는 m 단위로 적어야 해요. 116 cm는 몇 m인가요?","options":[{"t":"1.16 m","correct":true},{"t":"11.6 m","mis":"M4-2-u3-X04"},{"t":"0.116 m","mis":"M4-2-u3-X04"},{"t":"116 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","116 cm는 0.01 m가 116개예요.","116 cm = 1.16 m."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
