INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#11','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C3',2,'mc','auto','85.5의 10배는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":11,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"85.5의 10배는 얼마인가요?","options":[{"t":"855","correct":true},{"t":"8550","mis":"M4-2-u3-X06"},{"t":"8.55","mis":"M4-2-u3-X05"},{"t":"0.855","mis":"M4-2-u3-X05"}],"explanation":["10배 하면 숫자가 왼쪽으로 한 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","85.5의 10배 → 855."],"variant_rule":{"alt":[{"stem":"68.9의 100분의 1은 얼마인가요?","options":[{"t":"0.689","correct":true},{"t":"689","mis":"M4-2-u3-X05"},{"t":"6890","mis":"M4-2-u3-X05"},{"t":"6.89","mis":"M4-2-u3-X06"}],"explanation":["100분의 1 하면 숫자가 오른쪽으로 두 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","68.9의 100분의 1 → 0.689."],"asset":null},{"stem":"43.2의 10분의 1은 얼마인가요?","options":[{"t":"4.32","correct":true},{"t":"432","mis":"M4-2-u3-X05"},{"t":"4320","mis":"M4-2-u3-X05"},{"t":"0.432","mis":"M4-2-u3-X06"}],"explanation":["10분의 1 하면 숫자가 오른쪽으로 한 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","43.2의 10분의 1 → 4.32."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#12','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C4',2,'mc','auto','0.107, 0.34, 0.7을 큰 수부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X03']::text[],true,'{"seq":12,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"0.107, 0.34, 0.7을 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"0.7, 0.34, 0.107","correct":true},{"t":"0.107, 0.34, 0.7","mis":"M4-2-u3-X17"},{"t":"0.34, 0.7, 0.107","mis":"M4-2-u3-X03"},{"t":"0.7, 0.107, 0.34","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 0.7, 0.34, 0.107."],"variant_rule":{"alt":[{"stem":"1.5, 1.806, 1.78을 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"1.806, 1.78, 1.5","correct":true},{"t":"1.5, 1.78, 1.806","mis":"M4-2-u3-X17"},{"t":"1.78, 1.5, 1.806","mis":"M4-2-u3-X03"},{"t":"1.806, 1.5, 1.78","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 1.806, 1.78, 1.5."],"asset":null},{"stem":"2.91, 2.939, 2.1을 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"2.939, 2.91, 2.1","correct":true},{"t":"2.1, 2.91, 2.939","mis":"M4-2-u3-X17"},{"t":"2.939, 2.1, 2.91","mis":"M4-2-u3-X03"},{"t":"2.1, 2.939, 2.91","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 2.939, 2.91, 2.1."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#13','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C5',2,'mc','auto','집에서 동물 병원까지 1.9 km, 동물 병원에서 동물원까지 4.5 km예요. 집에서 동물 병원을 지나 동물원까지 간 거리는 몇 km인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],true,'{"seq":13,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"집에서 동물 병원까지 1.9 km, 동물 병원에서 동물원까지 4.5 km예요. 집에서 동물 병원을 지나 동물원까지 간 거리는 몇 km인가요?","options":[{"t":"6.4 km","correct":true},{"t":"5.4 km","mis":"M4-2-u3-X11"},{"t":"5.14 km","mis":"M4-2-u3-X10"},{"t":"2.6 km","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","1.9 + 4.5 = 6.4 — 소수점을 맞추어 더해요.","6.4 km예요."],"variant_rule":{"alt":[{"stem":"동물 보건사가 고양이들에게 오전에 사료 0.9 kg, 오후에 3.1 kg을 주었어요. 하루에 준 사료는 모두 몇 kg인가요?","options":[{"t":"4 kg","correct":true},{"t":"3 kg","mis":"M4-2-u3-X11"},{"t":"3.1 kg","mis":"M4-2-u3-X10"},{"t":"2.2 kg","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","0.9 + 3.1 = 4 — 소수점을 맞추어 더해요.","4 kg이에요."],"asset":null},{"stem":"집에서 동물 병원까지 3.9 km, 동물 병원에서 동물원까지 2.3 km예요. 집에서 동물 병원을 지나 동물원까지 간 거리는 몇 km인가요?","options":[{"t":"6.2 km","correct":true},{"t":"5.2 km","mis":"M4-2-u3-X11"},{"t":"5.12 km","mis":"M4-2-u3-X10"},{"t":"1.6 km","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","3.9 + 2.3 = 6.2 — 소수점을 맞추어 더해요.","6.2 km예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#14','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C6',2,'mc','auto','4.94 + 3.27은 얼마인가요?',ARRAY['M4-2-u3-X11']::text[],true,'{"seq":14,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"4.94 + 3.27은 얼마인가요?","options":[{"t":"8.21","correct":true},{"t":"7.11","mis":"M4-2-u3-X11"},{"t":"8.11","mis":"M4-2-u3-X11"},{"t":"7.21","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 494개 + 327개 = 821개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","4.94 + 3.27 = 8.21."],"variant_rule":{"alt":[{"stem":"5.76 + 6.49는 얼마인가요?","options":[{"t":"12.25","correct":true},{"t":"1.15","mis":"M4-2-u3-X11"},{"t":"12.15","mis":"M4-2-u3-X11"},{"t":"11.25","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 576개 + 649개 = 1225개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","5.76 + 6.49 = 12.25."],"asset":null},{"stem":"2.85 + 3.16은 얼마인가요?","options":[{"t":"6.01","correct":true},{"t":"5.91","mis":"M4-2-u3-X11"},{"t":"5.01","mis":"M4-2-u3-X11"},{"t":"0.31","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 285개 + 316개 = 601개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","2.85 + 3.16 = 6.01."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#15','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C7',2,'mc','auto','수의사가 소독약 5.2 L 가운데 0.3 L를 썼어요. 남은 소독약은 몇 L인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],true,'{"seq":15,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"수의사가 소독약 5.2 L 가운데 0.3 L를 썼어요. 남은 소독약은 몇 L인가요?","options":[{"t":"4.9 L","correct":true},{"t":"5.1 L","mis":"M4-2-u3-X13"},{"t":"5.9 L","mis":"M4-2-u3-X14"},{"t":"5.5 L","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","5.2 − 0.3 = 4.9 — 소수점을 맞추어 빼요.","4.9 L예요."],"variant_rule":{"alt":[{"stem":"참외가 든 바구니의 무게는 6.8 kg이고 빈 바구니는 2.9 kg이에요. 참외만의 무게는 몇 kg인가요?","options":[{"t":"3.9 kg","correct":true},{"t":"4.1 kg","mis":"M4-2-u3-X13"},{"t":"4.9 kg","mis":"M4-2-u3-X14"},{"t":"9.7 kg","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","6.8 − 2.9 = 3.9 — 소수점을 맞추어 빼요.","3.9 kg이에요."],"asset":null},{"stem":"수의사가 소독약 6.4 L 가운데 1.8 L를 썼어요. 남은 소독약은 몇 L인가요?","options":[{"t":"4.6 L","correct":true},{"t":"5.4 L","mis":"M4-2-u3-X13"},{"t":"5.6 L","mis":"M4-2-u3-X14"},{"t":"8.2 L","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","6.4 − 1.8 = 4.6 — 소수점을 맞추어 빼요.","4.6 L예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#16','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C9',2,'mc','auto','혼계영 200 m에서 바다거북 팀의 기록은 147.72초, 물개 팀의 기록은 150.79초예요. 더 빠른 팀은 어느 팀인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X18']::text[],true,'{"seq":16,"concept":"M4-2-u3-C9","difficulty":2,"kind":"mc","stem":"혼계영 200 m에서 바다거북 팀의 기록은 147.72초, 물개 팀의 기록은 150.79초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"바다거북 팀","correct":true},{"t":"물개 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","147.72 < 150.79.","더 빠른 팀은 바다거북 팀이에요."],"variant_rule":{"alt":[{"stem":"혼계영 200 m에서 수달 팀의 기록은 151.48초, 펭귄 팀의 기록은 152.51초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"수달 팀","correct":true},{"t":"펭귄 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","151.48 < 152.51.","더 빠른 팀은 수달 팀이에요."],"asset":null},{"stem":"혼계영 200 m에서 바다거북 팀의 기록은 152.56초, 물개 팀의 기록은 151.53초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"물개 팀","correct":true},{"t":"바다거북 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","152.56 > 151.53.","더 빠른 팀은 물개 팀이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#17','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C1',3,'mc','auto','수직선에서 작은 눈금 한 칸은 0.01이에요. 1.7에서 오른쪽으로 작은 눈금 8칸 더 간 곳의 수는 얼마인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X17']::text[],true,'{"seq":17,"concept":"M4-2-u3-C1","difficulty":3,"kind":"mc","stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 1.7에서 오른쪽으로 작은 눈금 8칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"1.78","correct":true},{"t":"2.5","mis":"M4-2-u3-X01"},{"t":"1.62","mis":"M4-2-u3-X17"},{"t":"9.7","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 8칸은 0.08이에요.","1.7 + 0.08 = 1.78.","0.1씩이 아니라 0.01씩 커져요."],"variant_rule":{"alt":[{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 7.4에서 오른쪽으로 작은 눈금 6칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"7.46","correct":true},{"t":"8","mis":"M4-2-u3-X01"},{"t":"7.34","mis":"M4-2-u3-X17"},{"t":"13.4","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 6칸은 0.06이에요.","7.4 + 0.06 = 7.46.","0.1씩이 아니라 0.01씩 커져요."],"asset":null},{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 7.7에서 오른쪽으로 작은 눈금 8칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"7.78","correct":true},{"t":"8.5","mis":"M4-2-u3-X01"},{"t":"7.62","mis":"M4-2-u3-X17"},{"t":"15.7","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 8칸은 0.08이에요.","7.7 + 0.08 = 7.78.","0.1씩이 아니라 0.01씩 커져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#18','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C4',3,'sa','auto','0.98□ < 0.984일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u3-C4","difficulty":3,"kind":"sa","stem":"0.98□ < 0.984일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 0, 1, 2, 3.","모두 4개 — 같아지는 수·경계의 수를 확인해요."],"variant_rule":{"alt":[{"stem":"2.47□ < 2.474일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 0, 1, 2, 3.","모두 4개 — 같아지는 수·경계의 수를 확인해요."],"asset":null},{"stem":"0.41□ > 0.412일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 3, 4, 5, 6, 7, 8, 9.","모두 7개 — 같아지는 수·경계의 수를 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#19','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C6',3,'error','auto','3.7 + 0.91을 세로로 계산해 1.28이라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M4-2-u3-X12','M4-2-u3-X11','M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":19,"concept":"M4-2-u3-C6","difficulty":3,"kind":"error","stem":"3.7 + 0.91을 세로로 계산해 1.28이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 3.7 = 3.70으로 보면 자리가 맞아요.","0.01이 370개 + 91개 = 461개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","3.7 + 0.91 = 4.61."],"variant_rule":{"alt":[{"stem":"5.81 + 5.5를 세로로 계산해 6.36이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 5.5 = 5.50으로 보면 자리가 맞아요.","0.01이 581개 + 550개 = 1131개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","5.81 + 5.5 = 11.31."],"asset":null},{"stem":"3.1 + 6.32를 세로로 계산해 6.63이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 3.1 = 3.10으로 보면 자리가 맞아요.","0.01이 310개 + 632개 = 942개.","3.1 + 6.32 = 9.42."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes,