INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#20','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C8',3,'mc','auto','4.8 − □ = 3.38일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X13','M4-2-u3-X14']::text[],true,'{"seq":20,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"4.8 − □ = 3.38일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"1.42","correct":true},{"t":"8.18","mis":"M4-2-u3-X16"},{"t":"1.58","mis":"M4-2-u3-X13"},{"t":"1.52","mis":"M4-2-u3-X14"}],"explanation":["4.8에서 □를 빼서 3.38 — □ = 4.8 − 3.38.","□ = 1.42.","확인: 4.8 − 1.42 = 3.38."],"variant_rule":{"alt":[{"stem":"5.8 − □ = 2.95일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"2.85","correct":true},{"t":"8.75","mis":"M4-2-u3-X16"},{"t":"3.15","mis":"M4-2-u3-X13"},{"t":"3.95","mis":"M4-2-u3-X14"}],"explanation":["5.8에서 □를 빼서 2.95 — □ = 5.8 − 2.95.","□ = 2.85.","확인: 5.8 − 2.85 = 2.95."],"asset":null},{"stem":"6.3 − □ = 0.29일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"6.01","correct":true},{"t":"6.59","mis":"M4-2-u3-X16"},{"t":"6.19","mis":"M4-2-u3-X13"},{"t":"6.11","mis":"M4-2-u3-X14"}],"explanation":["6.3에서 □를 빼서 0.29 — □ = 6.3 − 0.29.","□ = 6.01.","확인: 6.3 − 6.01 = 0.29."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#21','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C10',3,'mc','auto','한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?',ARRAY['M4-2-u3-X19','M4-2-u3-X17','M4-2-u3-X18']::text[],true,'{"seq":21,"concept":"M4-2-u3-C10","difficulty":3,"kind":"mc","stem":"한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배영 서준 · 평영 지유 · 접영 채원 · 자유형 건우","correct":true},{"t":"배영 서준 · 평영 지유 · 접영 지유 · 자유형 서준","mis":"M4-2-u3-X19"},{"t":"배영 지유 · 평영 건우 · 접영 서준 · 자유형 채원","mis":"M4-2-u3-X17"},{"t":"배영 서준 · 평영 채원 · 접영 지유 · 자유형 건우","mis":"M4-2-u3-X18"}],"explanation":["영법마다 가장 빠른 선수만 고르면 서준이 두 영법을 맡게 되어 안 돼요.","겹치는 영법은 두 번째로 빠른 선수와 짝지어 합을 견주어요.","가장 작은 합은 136.66초 — 배영 서준 · 평영 지유 · 접영 채원 · 자유형 건우."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","33.88","35.85","39.53","33.12"],["지유","37.60","33.87","33.55","35.67"],["채원","37.23","35.02","34.33","36.75"],["건우","38.11","36.92","33.92","34.58"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배영 서준 · 평영 채원 · 접영 지유 · 자유형 건우","correct":true},{"t":"배영 지유 · 평영 지유 · 접영 지유 · 자유형 건우","mis":"M4-2-u3-X19"},{"t":"배영 건우 · 평영 서준 · 접영 채원 · 자유형 지유","mis":"M4-2-u3-X17"},{"t":"배영 지유 · 평영 채원 · 접영 서준 · 자유형 건우","mis":"M4-2-u3-X18"}],"explanation":["영법마다 가장 빠른 선수만 고르면 지유가 두 영법을 맡게 되어 안 돼요.","겹치는 영법은 두 번째로 빠른 선수와 짝지어 합을 견주어요.","가장 작은 합은 136.43초 — 배영 서준 · 평영 채원 · 접영 지유 · 자유형 건우."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","33.42","37.69","33.94","35.61"],["지유","33.25","35.30","33.57","38.95"],["채원","38.25","35.38","38.49","34.44"],["건우","39.46","39.58","34.75","34.06"]]}},{"stem":"이번에는 다른 문제예요. 한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배영 지유 · 평영 채원 · 접