INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#22','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C3',3,'mc','auto','어떤 수의 100분의 1은 0.836이에요. 어떤 수는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":22,"concept":"M4-2-u3-C3","difficulty":3,"kind":"mc","stem":"어떤 수의 100분의 1은 0.836이에요. 어떤 수는 얼마인가요?","options":[{"t":"83.6","correct":true},{"t":"8.36","mis":"M4-2-u3-X06"},{"t":"0.836","mis":"M4-2-u3-X05"},{"t":"836","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 100분의 1 → 0.836.","거꾸로 0.836의 100배를 구해요.","어떤 수 = 83.6."],"variant_rule":{"alt":[{"stem":"어떤 수의 10분의 1은 9.51이에요. 어떤 수는 얼마인가요?","options":[{"t":"95.1","correct":true},{"t":"951","mis":"M4-2-u3-X06"},{"t":"0.951","mis":"M4-2-u3-X05"},{"t":"9.51","mis":"M4-2-u3-X05"}],"explanation":["어떤 수 → 10분의 1 → 9.51.","거꾸로 9.51의 10배를 구해요.","어떤 수 = 95.1."],"asset":null},{"stem":"어떤 수의 10분의 1은 0.301이에요. 어떤 수는 얼마인가요?","options":[{"t":"3.01","correct":true},{"t":"30.1","mis":"M4-2-u3-X06"},{"t":"0.301","mis":"M4-2-u3-X05"},{"t":"301","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 10분의 1 → 0.301.","거꾸로 0.301의 10배를 구해요.","어떤 수 = 3.01."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#23','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C6',4,'mc','auto','8.6 + □ = 18.15일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X13','M4-2-u3-X12']::text[],true,'{"seq":23,"concept":"M4-2-u3-C6","difficulty":4,"kind":"mc","stem":"8.6 + □ = 18.15일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"9.55","correct":true},{"t":"26.75","mis":"M4-2-u3-X16"},{"t":"10.55","mis":"M4-2-u3-X13"},{"t":"17.29","mis":"M4-2-u3-X12"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","18.15 − 8.6 = 9.55.","확인: 8.6 + 9.55 = 18.15."],"variant_rule":{"alt":[{"stem":"6.7 + □ = 15.64일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"8.94","correct":true},{"t":"22.34","mis":"M4-2-u3-X16"},{"t":"11.14","mis":"M4-2-u3-X13"},{"t":"19.94","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","15.64 − 6.7 = 8.94.","확인: 6.7 + 8.94 = 15.64."],"asset":null},{"stem":"5.8 + □ = 9.52일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"3.72","correct":true},{"t":"15.32","mis":"M4-2-u3-X16"},{"t":"4.32","mis":"M4-2-u3-X13"},{"t":"4.72","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","9.52 − 5.8 = 3.72.","확인: 5.8 + 3.72 = 9.52."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#24','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C10',4,'sa','auto','한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 140.46초예요. 예선 통과 기준 142초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u3-C10","difficulty":4,"kind":"sa","stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 140.46초예요. 예선 통과 기준 142초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["154"],"explanation":["기준에서 우리 기록을 빼요.","142 − 140.46 = 1.54.","1.54는 0.01이 154개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","36.05","39.00","39.73","36.42"],["지유","33.83","39.37","36.00","39.15"],["채원","39.67","33.35","36.06","33.75"],["건우","36.47","36.49","37.94","35.06"]]},"variant_rule":{"alt":[{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 141.25초예요. 예선 통과 기준 142초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["75"],"explanation":["기준에서 우리 기록을 빼요.","142 − 141.25 = 0.75.","0.75는 0.01이 75개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","37.68","35.49","38.14","39.57"],["지유","35.09","34.61","39.55","33.04"],["채원","39.57","35.59","37.71","33.99"],["건우","35.01","35.00","37.13","34.27"]]}},{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 136.59초예요. 예선 통과 기준 138초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["141"],"explanation":["기준에서 우리 기록을 빼요.","138 − 136.59 = 1.41.","1.41은 0.01이 141개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","36.63","35.58","36.86","35.64"],["지유","33.23","39.55","35.15","34.94"],["채원","35.18","37.83","35.87","33.04"],["건우","33.79","34.45","34.74","33.54"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has