INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_c#25','math',4,2,'u3','','g4_2_math_u3_review_c','unit_review','M4-2-u3-C6',4,'essay','teacher','나무의 키가 작년에 1.6 m였는데 올해는 52 cm 더 자랐어요. 올해 나무의 키를 m 단위로 구하고 계산 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u3-C6","difficulty":4,"kind":"essay","stem":"나무의 키가 작년에 1.6 m였는데 올해는 52 cm 더 자랐어요. 올해 나무의 키를 m 단위로 구하고 계산 방법을 설명해 보세요.","answer_guide":{"answer":"예: 52 cm = 0.52 m이다. 1.6 + 0.52를 소수점을 맞추어(1.60 + 0.52) 계산하면 소수 둘째 자리 0 + 2 = 2, 소수 첫째 자리 6 + 5 = 11이라 1을 받아올림, 일의 자리 1 + 0 + 1 = 2이므로 2.12 m이다.","scoring_points":["52 cm = 0.52 m로 바꾸었는가","소수점을 맞추어 더했는가","2.12 m라고 답했는가"]},"explanation":["52 cm = 0.52 m.","1.60 + 0.52.","2.12 m."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
