INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#9','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C1',2,'mc','auto','사육사가 홍학의 다리 길이를 재어 보니 283 cm였어요. 안내판에는 m 단위로 적어야 해요. 283 cm는 몇 m인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":9,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"사육사가 홍학의 다리 길이를 재어 보니 283 cm였어요. 안내판에는 m 단위로 적어야 해요. 283 cm는 몇 m인가요?","options":[{"t":"2.83 m","correct":true},{"t":"28.3 m","mis":"M4-2-u3-X04"},{"t":"0.283 m","mis":"M4-2-u3-X04"},{"t":"283 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","283 cm는 0.01 m가 283개예요.","283 cm = 2.83 m."],"variant_rule":{"alt":[{"stem":"사육사가 펭귄의 키를 재어 보니 221 cm였어요. 안내판에는 m 단위로 적어야 해요. 221 cm는 몇 m인가요?","options":[{"t":"2.21 m","correct":true},{"t":"22.1 m","mis":"M4-2-u3-X04"},{"t":"0.221 m","mis":"M4-2-u3-X04"},{"t":"221 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","221 cm는 0.01 m가 221개예요.","221 cm = 2.21 m."],"asset":null},{"stem":"사육사가 기린 우리 문의 폭을 재어 보니 142 cm였어요. 안내판에는 m 단위로 적어야 해요. 142 cm는 몇 m인가요?","options":[{"t":"1.42 m","correct":true},{"t":"14.2 m","mis":"M4-2-u3-X04"},{"t":"0.142 m","mis":"M4-2-u3-X04"},{"t":"142 m","mis":"M4-2-u3-X04"}],"explanation":["1 cm는 1 m를 100으로 나눈 하나 — 0.01 m예요.","142 cm는 0.01 m가 142개예요.","142 cm = 1.42 m."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
