INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#11','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C3',2,'mc','auto','64.7의 10배는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":11,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"64.7의 10배는 얼마인가요?","options":[{"t":"647","correct":true},{"t":"6470","mis":"M4-2-u3-X06"},{"t":"6.47","mis":"M4-2-u3-X05"},{"t":"0.647","mis":"M4-2-u3-X05"}],"explanation":["10배 하면 숫자가 왼쪽으로 한 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","64.7의 10배 → 647."],"variant_rule":{"alt":[{"stem":"69.8의 100배는 얼마인가요?","options":[{"t":"6980","correct":true},{"t":"698","mis":"M4-2-u3-X06"},{"t":"6.98","mis":"M4-2-u3-X05"},{"t":"0.698","mis":"M4-2-u3-X05"}],"explanation":["100배 하면 숫자가 왼쪽으로 두 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","69.8의 100배 → 6980."],"asset":null},{"stem":"48.8의 100분의 1은 얼마인가요?","options":[{"t":"0.488","correct":true},{"t":"488","mis":"M4-2-u3-X05"},{"t":"4880","mis":"M4-2-u3-X05"},{"t":"4.88","mis":"M4-2-u3-X06"}],"explanation":["100분의 1 하면 숫자가 오른쪽으로 두 자리 옮겨 가요.","소수점은 그대로 — 자리가 바뀌면 값이 달라져요.","48.8의 100분의 1 → 0.488."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#12','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C4',2,'mc','auto','1.52, 1.1, 1.16을 큰 수부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X03']::text[],true,'{"seq":12,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"1.52, 1.1, 1.16을 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"1.52, 1.16, 1.1","correct":true},{"t":"1.1, 1.16, 1.52","mis":"M4-2-u3-X17"},{"t":"1.1, 1.52, 1.16","mis":"M4-2-u3-X03"},{"t":"1.52, 1.1, 1.16","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 1.52, 1.16, 1.1."],"variant_rule":{"alt":[{"stem":"3.91, 3.5, 3.34를 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"3.91, 3.5, 3.34","correct":true},{"t":"3.34, 3.5, 3.91","mis":"M4-2-u3-X17"},{"t":"3.91, 3.34, 3.5","mis":"M4-2-u3-X07"},{"t":"3.5, 3.34, 3.91","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 3.91, 3.5, 3.34."],"asset":null},{"stem":"1.9, 1.897, 1.16을 큰 수부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"1.9, 1.897, 1.16","correct":true},{"t":"1.16, 1.897, 1.9","mis":"M4-2-u3-X17"},{"t":"1.897, 1.16, 1.9","mis":"M4-2-u3-X07"},{"t":"1.9, 1.16, 1.897","mis":"M4-2-u3-X03"}],"explanation":["소수점을 기준으로 자리를 맞추어요.","큰 자리부터 견주어요 — 자리 수가 많다고 큰 수가 아니에요.","큰 수부터 — 1.9, 1.897, 1.16."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#13','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C5',2,'mc','auto','동물 보건사가 고양이들에게 오전에 사료 0.8 kg, 오후에 3.2 kg을 주었어요. 하루에 준 사료는 모두 몇 kg인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],true,'{"seq":13,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"동물 보건사가 고양이들에게 오전에 사료 0.8 kg, 오후에 3.2 kg을 주었어요. 하루에 준 사료는 모두 몇 kg인가요?","options":[{"t":"4 kg","correct":true},{"t":"3 kg","mis":"M4-2-u3-X11"},{"t":"3.1 kg","mis":"M4-2-u3-X10"},{"t":"2.4 kg","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","0.8 + 3.2 = 4 — 소수점을 맞추어 더해요.","4 kg이에요."],"variant_rule":{"alt":[{"stem":"집에서 동물 병원까지 0.7 km, 동물 병원에서 동물원까지 3.9 km예요. 집에서 동물 병원을 지나 동물원까지 간 거리는 몇 km인가요?","options":[{"t":"4.6 km","correct":true},{"t":"3.6 km","mis":"M4-2-u3-X11"},{"t":"3.16 km","mis":"M4-2-u3-X10"},{"t":"3.2 km","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","0.7 + 3.9 = 4.6 — 소수점을 맞추어 더해요.","4.6 km예요."],"asset":null},{"stem":"동물 보건사가 고양이들에게 오전에 사료 2.4 kg, 오후에 3.8 kg을 주었어요. 하루에 준 사료는 모두 몇 kg인가요?","options":[{"t":"6.2 kg","correct":true},{"t":"5.2 kg","mis":"M4-2-u3-X11"},{"t":"5.12 kg","mis":"M4-2-u3-X10"},{"t":"1.4 kg","mis":"M4-2-u3-X16"}],"explanation":["「모두」는 두 양을 모으는 덧셈이에요.","2.4 + 3.8 = 6.2 — 소수점을 맞추어 더해요.","6.2 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#14','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C6',2,'mc','auto','6.99 + 3.59는 얼마인가요?',ARRAY['M4-2-u3-X11']::text[],true,'{"seq":14,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"6.99 + 3.59는 얼마인가요?","options":[{"t":"10.58","correct":true},{"t":"9.48","mis":"M4-2-u3-X11"},{"t":"10.48","mis":"M4-2-u3-X11"},{"t":"9.58","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 699개 + 359개 = 1058개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","6.99 + 3.59 = 10.58."],"variant_rule":{"alt":[{"stem":"1.44 + 1.27은 얼마인가요?","options":[{"t":"2.71","correct":true},{"t":"2.61","mis":"M4-2-u3-X11"},{"t":"0.17","mis":"M4-2-u3-X16"},{"t":"27.1","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 144개 + 127개 = 271개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","1.44 + 1.27 = 2.71."],"asset":null},{"stem":"2.43 + 5.68은 얼마인가요?","options":[{"t":"8.11","correct":true},{"t":"7.01","mis":"M4-2-u3-X11"},{"t":"8.01","mis":"M4-2-u3-X11"},{"t":"7.11","mis":"M4-2-u3-X11"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요.","0.01이 243개 + 568개 = 811개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","2.43 + 5.68 = 8.11."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#15','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C7',2,'mc','auto','참외가 든 바구니의 무게는 4.4 kg이고 빈 바구니는 0.9 kg이에요. 참외만의 무게는 몇 kg인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":15,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"참외가 든 바구니의 무게는 4.4 kg이고 빈 바구니는 0.9 kg이에요. 참외만의 무게는 몇 kg인가요?","options":[{"t":"3.5 kg","correct":true},{"t":"4.5 kg","mis":"M4-2-u3-X13"},{"t":"5.3 kg","mis":"M4-2-u3-X16"},{"t":"0.35 kg","mis":"M4-2-u3-X01"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","4.4 − 0.9 = 3.5 — 소수점을 맞추어 빼요.","3.5 kg이에요."],"variant_rule":{"alt":[{"stem":"수의사가 소독약 5.2 L 가운데 1.5 L를 썼어요. 남은 소독약은 몇 L인가요?","options":[{"t":"3.7 L","correct":true},{"t":"4.3 L","mis":"M4-2-u3-X13"},{"t":"4.7 L","mis":"M4-2-u3-X14"},{"t":"6.7 L","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","5.2 − 1.5 = 3.7 — 소수점을 맞추어 빼요.","3.7 L예요."],"asset":null},{"stem":"참외가 든 바구니의 무게는 2.3 kg이고 빈 바구니는 1.9 kg이에요. 참외만의 무게는 몇 kg인가요?","options":[{"t":"0.4 kg","correct":true},{"t":"1.6 kg","mis":"M4-2-u3-X13"},{"t":"1.4 kg","mis":"M4-2-u3-X14"},{"t":"4.2 kg","mis":"M4-2-u3-X16"}],"explanation":["「남은」·「더 높이」는 덜어 내거나 차를 구하는 뺄셈이에요.","2.3 − 1.9 = 0.4 — 소수점을 맞추어 빼요.","0.4 kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#16','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C9',2,'mc','auto','혼계영 200 m에서 돌고래 팀의 기록은 145.79초, 아기 상어 팀의 기록은 148.93초예요. 더 빠른 팀은 어느 팀인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X18']::text[],true,'{"seq":16,"concept":"M4-2-u3-C9","difficulty":2,"kind":"mc","stem":"혼계영 200 m에서 돌고래 팀의 기록은 145.79초, 아기 상어 팀의 기록은 148.93초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"돌고래 팀","correct":true},{"t":"아기 상어 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","145.79 < 148.93.","더 빠른 팀은 돌고래 팀이에요."],"variant_rule":{"alt":[{"stem":"혼계영 200 m에서 수달 팀의 기록은 153.43초, 펭귄 팀의 기록은 150.89초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"펭귄 팀","correct":true},{"t":"수달 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","153.43 > 150.89.","더 빠른 팀은 펭귄 팀이에요."],"asset":null},{"stem":"혼계영 200 m에서 수달 팀의 기록은 149.81초, 펭귄 팀의 기록은 147.81초예요. 더 빠른 팀은 어느 팀인가요?","options":[{"t":"펭귄 팀","correct":true},{"t":"수달 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 같아요","mis":"M4-2-u3-X18"},{"t":"견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["기록은 걸린 시간 — 작을수록 빨라요.","149.81 > 147.81.","더 빠른 팀은 펭귄 팀이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#17','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C1',3,'mc','auto','수직선에서 작은 눈금 한 칸은 0.01이에요. 2.4에서 오른쪽으로 작은 눈금 6칸 더 간 곳의 수는 얼마인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X17']::text[],true,'{"seq":17,"concept":"M4-2-u3-C1","difficulty":3,"kind":"mc","stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 2.4에서 오른쪽으로 작은 눈금 6칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"2.46","correct":true},{"t":"3","mis":"M4-2-u3-X01"},{"t":"2.34","mis":"M4-2-u3-X17"},{"t":"8.4","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 6칸은 0.06이에요.","2.4 + 0.06 = 2.46.","0.1씩이 아니라 0.01씩 커져요."],"variant_rule":{"alt":[{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 9.2에서 오른쪽으로 작은 눈금 8칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"9.28","correct":true},{"t":"10","mis":"M4-2-u3-X01"},{"t":"9.12","mis":"M4-2-u3-X17"},{"t":"17.2","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 8칸은 0.08이에요.","9.2 + 0.08 = 9.28.","0.1씩이 아니라 0.01씩 커져요."],"asset":null},{"stem":"수직선에서 작은 눈금 한 칸은 0.01이에요. 7.3에서 오른쪽으로 작은 눈금 7칸 더 간 곳의 수는 얼마인가요?","options":[{"t":"7.37","correct":true},{"t":"8","mis":"M4-2-u3-X01"},{"t":"7.23","mis":"M4-2-u3-X17"},{"t":"14.3","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸이 0.01 — 7칸은 0.07이에요.","7.3 + 0.07 = 7.37.","0.1씩이 아니라 0.01씩 커져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#18','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C4',3,'sa','auto','1.6□8 < 1.633일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u3-C4","difficulty":3,"kind":"sa","stem":"1.6□8 < 1.633일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 0, 1, 2.","모두 3개 — 같아지는 수·경계의 수를 확인해요."],"variant_rule":{"alt":[{"stem":"1.6□8 > 1.679일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 8, 9.","모두 2개 — 같아지는 수·경계의 수를 확인해요."],"asset":null},{"stem":"2.74□ < 2.746일 때 □ 안에 들어갈 수 있는 숫자는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["큰 자리부터 견주어요 — 앞자리가 같으니 □ 자리부터.","0부터 9까지 하나씩 넣어 보면 0, 1, 2, 3, 4, 5.","모두 6개 — 같아지는 수·경계의 수를 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#19','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C6',3,'error','auto','2.28 + 5.6을 세로로 계산해 2.84라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M4-2-u3-X12','M4-2-u3-X11','M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":19,"concept":"M4-2-u3-C6","difficulty":3,"kind":"error","stem":"2.28 + 5.6을 세로로 계산해 2.84라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 5.6 = 5.60으로 보면 자리가 맞아요.","0.01이 228개 + 560개 = 788개.","2.28 + 5.6 = 7.88."],"variant_rule":{"alt":[{"stem":"1.1 + 0.51을 세로로 계산해 0.62라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 1.1 = 1.10으로 보면 자리가 맞아요.","0.01이 110개 + 51개 = 161개.","1.1 + 0.51 = 1.61."],"asset":null},{"stem":"3.71 + 2.9를 세로로 계산해 4라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"소수점이 아니라 오른쪽 끝을 맞추어 썼어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림을 하지 않았어요","mis":"M4-2-u3-X11"},{"t":"더하지 않고 뺐어요","mis":"M4-2-u3-X16"},{"t":"소수 셋째 자리를 빠뜨렸어요","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 세로로 쓰고 같은 자리끼리 더해요 — 2.9 = 2.90으로 보면 자리가 맞아요.","0.01이 371개 + 290개 = 661개 — 0.01이 10개 모이면 윗자리 1로 받아올림해요.","3.71 + 2.9 = 6.61."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payl