INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#20','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C8',3,'mc','auto','5.5 − □ = 1.08일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X13','M4-2-u3-X14']::text[],true,'{"seq":20,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"5.5 − □ = 1.08일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"4.42","correct":true},{"t":"6.58","mis":"M4-2-u3-X16"},{"t":"4.58","mis":"M4-2-u3-X13"},{"t":"4.52","mis":"M4-2-u3-X14"}],"explanation":["5.5에서 □를 빼서 1.08 — □ = 5.5 − 1.08.","□ = 4.42.","확인: 5.5 − 4.42 = 1.08."],"variant_rule":{"alt":[{"stem":"7.4 − □ = 2.14일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"5.26","correct":true},{"t":"9.54","mis":"M4-2-u3-X16"},{"t":"5.34","mis":"M4-2-u3-X13"},{"t":"5.36","mis":"M4-2-u3-X14"}],"explanation":["7.4에서 □를 빼서 2.14 — □ = 7.4 − 2.14.","□ = 5.26.","확인: 7.4 − 5.26 = 2.14."],"asset":null},{"stem":"9.8 − □ = 2.42일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"7.38","correct":true},{"t":"12.22","mis":"M4-2-u3-X16"},{"t":"7.42","mis":"M4-2-u3-X13"},{"t":"7.48","mis":"M4-2-u3-X14"}],"explanation":["9.8에서 □를 빼서 2.42 — □ = 9.8 − 2.42.","□ = 7.38.","확인: 9.8 − 7.38 = 2.42."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#21','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C10',3,'mc','auto','한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?',ARRAY['M4-2-u3-X19','M4-2-u3-X17','M4-2-u3-X18']::text[],true,'{"seq":21,"concept":"M4-2-u3-C10","difficulty":3,"kind":"mc","stem":"한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배영 지유 · 평영 서준 · 접영 채원 · 자유형 건우","correct":true},{"t":"배영 지유 · 평영 서준 · 접영 채원 · 자유형 지유","mis":"M4-2-u3-X19"},{"t":"배영 서준 · 평영 건우 · 접영 지유 · 자유형 채원","mis":"M4-2-u3-X17"},{"t":"배영 채원 · 평영 서준 · 접영 건우 · 자유형 지유","mis":"M4-2-u3-X18"}],"explanation":["영법마다 가장 빠른 선수만 고르면 지유가 두 영법을 맡게 되어 안 돼요.","겹치는 영법은 두 번째로 빠른 선수와 짝지어 합을 견주어요.","가장 작은 합은 137.56초 — 배영 지유 · 평영 서준 · 접영 채원 · 자유형 건우."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.40","33.93","38.06","38.14"],["지유","34.72","37.56","38.34","34.74"],["채원","34.82","36.51","33.70","37.60"],["건우","39.09","39.12","34.50","35.21"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배영 지유 · 평영 건우 · 접영 서준 · 자유형 채원","correct":true},{"t":"배영 지유 · 평영 지유 · 접영 서준 · 자유형 지유","mis":"M4-2-u3-X19"},{"t":"배영 건우 · 평영 채원 · 접영 지유 · 자유형 서준","mis":"M4-2-u3-X17"},{"t":"배영 지유 · 평영 서준 · 접영 건우 · 자유형 채원","mis":"M4-2-u3-X18"}],"explanation":["영법마다 가장 빠른 선수만 고르면 지유가 두 영법을 맡게 되어 안 돼요.","겹치는 영법은 두 번째로 빠른 선수와 짝지어 합을 견주어요.","가장 작은 합은 138.84초 — 배영 지유 · 평영 건우 · 접영 서준 · 자유형 채원."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","38.75","34.79","33.72","38.22"],["지유","34.88","34.51","37.25","33.80"],["채원","38.02","39.39","35.91","34.38"],["건우","39.57","35.86","36.53","37.66"]]}},{"stem":"이번에는 다른 문제예요. 한 선수는 한 영법만 헤엄칠 수 있어요. 네 선수의 기록의 합이 가장 작아지는 명단은 어느 것인가요?","options":[{"t":"배영 건우 · 평영 채원 · 접