INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#22','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C3',3,'mc','auto','어떤 수의 100배는 277이에요. 어떤 수는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":22,"concept":"M4-2-u3-C3","difficulty":3,"kind":"mc","stem":"어떤 수의 100배는 277이에요. 어떤 수는 얼마인가요?","options":[{"t":"2.77","correct":true},{"t":"2770","mis":"M4-2-u3-X06"},{"t":"27700","mis":"M4-2-u3-X05"},{"t":"27.7","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 100배 → 277.","거꾸로 277의 100분의 1을 구해요.","어떤 수 = 2.77."],"variant_rule":{"alt":[{"stem":"어떤 수의 10배는 902예요. 어떤 수는 얼마인가요?","options":[{"t":"90.2","correct":true},{"t":"9020","mis":"M4-2-u3-X05"},{"t":"90200","mis":"M4-2-u3-X06"},{"t":"9.02","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 10배 → 902.","거꾸로 902의 10분의 1을 구해요.","어떤 수 = 90.2."],"asset":null},{"stem":"어떤 수의 100분의 1은 0.779예요. 어떤 수는 얼마인가요?","options":[{"t":"77.9","correct":true},{"t":"7.79","mis":"M4-2-u3-X06"},{"t":"0.779","mis":"M4-2-u3-X05"},{"t":"779","mis":"M4-2-u3-X06"}],"explanation":["어떤 수 → 100분의 1 → 0.779.","거꾸로 0.779의 100배를 구해요.","어떤 수 = 77.9."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#23','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C6',4,'mc','auto','7.3 + □ = 10.01일 때 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X14','M4-2-u3-X12']::text[],true,'{"seq":23,"concept":"M4-2-u3-C6","difficulty":4,"kind":"mc","stem":"7.3 + □ = 10.01일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"2.71","correct":true},{"t":"17.31","mis":"M4-2-u3-X16"},{"t":"13.71","mis":"M4-2-u3-X14"},{"t":"9.28","mis":"M4-2-u3-X12"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","10.01 − 7.3 = 2.71.","확인: 7.3 + 2.71 = 10.01."],"variant_rule":{"alt":[{"stem":"2.4 + □ = 9.38일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"6.98","correct":true},{"t":"11.78","mis":"M4-2-u3-X16"},{"t":"7.18","mis":"M4-2-u3-X13"},{"t":"7.98","mis":"M4-2-u3-X14"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","9.38 − 2.4 = 6.98.","확인: 2.4 + 6.98 = 9.38."],"asset":null},{"stem":"4.6 + □ = 5.15일 때 □에 알맞은 수는 얼마인가요?","options":[{"t":"0.55","correct":true},{"t":"9.75","mis":"M4-2-u3-X16"},{"t":"1.55","mis":"M4-2-u3-X13"},{"t":"4.69","mis":"M4-2-u3-X12"}],"explanation":["□는 덧셈의 거꾸로 — 뺄셈으로 구해요.","5.15 − 4.6 = 0.55.","확인: 4.6 + 0.55 = 5.15."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#24','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C10',4,'sa','auto','한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 144.4초예요. 예선 통과 기준 145초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u3-C10","difficulty":4,"kind":"sa","stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 144.4초예요. 예선 통과 기준 145초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["60"],"explanation":["기준에서 우리 기록을 빼요.","145 − 144.4 = 0.6.","0.6은 0.01이 60개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","36.60","36.62","38.69","35.09"],["지유","35.08","38.87","37.88","34.32"],["채원","36.65","39.39","38.75","36.45"],["건우","36.82","35.48","36.86","34.06"]]},"variant_rule":{"alt":[{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 141.16초예요. 예선 통과 기준 143초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["184"],"explanation":["기준에서 우리 기록을 빼요.","143 − 141.16 = 1.84.","1.84는 0.01이 184개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","36.39","36.55","39.95","38.43"],["지유","36.19","39.62","37.28","33.44"],["채원","38.88","36.73","36.66","37.11"],["건우","37.19","39.74","34.60","35.31"]]}},{"stem":"한 선수가 한 영법만 맡아 기록의 합이 가장 작아지게 명단을 짜면 141.22초예요. 예선 통과 기준 142초보다 몇 초 빠른지, 0.01이 몇 개인 수로 답하세요.","answer":["78"],"explanation":["기준에서 우리 기록을 빼요.","142 − 141.22 = 0.78.","0.78은 0.01이 78개예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.76","35.88","38.17","38.97"],["지유","37.94","39.75","39.26","35.79"],["채원","34.31","35.28","34.18","33.97"],["건우","35.90","35.05","37.61","33.22"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u3_review_d#25','math',4,2,'u3','','g4_2_math_u3_review_d','unit_review','M4-2-u3-C8',4,'essay','teacher','9.5 − 1.8과 6.98 − 1.23을 계산하고, 두 뺄셈에서 「같은 규칙 하나」가 무엇인지 받아내림과 함께 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u3-C8","difficulty":4,"kind":"essay","stem":"9.5 − 1.8과 6.98 − 1.23을 계산하고, 두 뺄셈에서 「같은 규칙 하나」가 무엇인지 받아내림과 함께 설명해 보세요.","answer_guide":{"answer":"예: 9.5 − 1.8 = 7.7, 6.98 − 1.23 = 5.75이다. 두 뺄셈 모두 소수점을 맞추고 같은 자리끼리 뺀다. 9.5 − 1.8에서는 소수 첫째 자리 5에서 8을 뺄 수 없어 일의 자리에서 1(0.1이 10개)을 받아내림했다. 자연수의 뺄셈과 같은 규칙이다.","scoring_points":["7.7과 5.75를 구했는가","소수점을 맞추고 같은 자리끼리 뺀다고 썼는가","받아내림(1 = 0.1이 10개)을 설명했는가"]},"explanation":["9.5 − 1.8 = 7.7.","6.98 − 1.23 = 5.75.","소수점 맞추고 같은 자리끼리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
